import React from 'react';
import { Product } from '../types';

interface ProductCardProps {
  product: Product;
  onAddToCart: (id: string) => void;
}

const ProductCard: React.FC<ProductCardProps> = ({ product, onAddToCart }) => {
  const isHot = product.hypeScore > 80;
  const isRare = product.stock < 5;

  return (
    <div className="group relative bg-zinc-900 border border-zinc-800 rounded-xl overflow-hidden transition-all duration-300 hover:border-pink-500/50 hover:shadow-2xl hover:shadow-pink-500/10">
      {/* Visual Triggers */}
      {isHot && (
        <div className="absolute top-3 left-3 z-10 bg-red-600 text-[10px] font-bold px-2 py-1 rounded-full uppercase tracking-tighter animate-pulse shadow-lg shadow-red-600/30">
          🔥 Viral Item
        </div>
      )}
      {isRare && (
        <div className="absolute top-3 right-3 z-10 bg-amber-500 text-[10px] font-bold px-2 py-1 rounded-full uppercase tracking-tighter text-black">
          Only {product.stock} Left!
        </div>
      )}

      {/* Image with overlay */}
      <div className="aspect-[3/4] overflow-hidden relative">
        <img 
          src={product.image} 
          alt={product.name} 
          className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110"
        />
        <div className="absolute inset-0 bg-gradient-to-t from-zinc-950 via-transparent to-transparent opacity-60"></div>

        {/* Social Proof Overlay */}
        <div className="absolute bottom-3 left-3 right-3 flex justify-between items-center text-[10px] font-medium text-zinc-300">
          <div className="flex items-center gap-1">
            <span className="inline-block w-1.5 h-1.5 rounded-full bg-green-500 animate-ping"></span>
            {product.viewers} people viewing
          </div>
          <div>Recently bought</div>
        </div>
      </div>

      {/* Content */}
      <div className="p-4">
        <h3 className="text-sm font-semibold text-zinc-100 group-hover:text-pink-400 transition-colors">
          {product.name}
        </h3>
        <div className="mt-1 flex items-baseline gap-2">
          <span className="text-lg font-bold text-white">${product.price}</span>
          <span className="text-xs text-zinc-500 line-through">${product.originalPrice}</span>
          <span className="text-[10px] font-bold text-green-400 ml-auto">
            SAVE {Math.round((1 - product.price / product.originalPrice) * 100)}%
