  );
};

export default ProductCard;

import React, { useState } from 'react';

interface MysteryBoxProps {
  onReveal: (reward: any) => void;
  cost: number;
}

const MysteryBox: React.FC<MysteryBoxProps> = ({ onReveal, cost }) => {
  const [isOpening, setIsOpening] = useState(false);
  const [reward, setReward] = useState<string | null>(null);

  const handleOpen = () => {
    if (isOpening) return;
    setIsOpening(true);
    // Simulate excitement
    setTimeout(() => {
      const rewards = [
        "15% Off Your Entire Cart",
        "500 Bonus Craze Coins",
        "Free Express Shipping",
        "Exclusive 'VIP' Badge Unlocked",
        "Early Access to Drop #42"
      ];
      const win = rewards[Math.floor(Math.random() * rewards.length)];
      setReward(win);
      setIsOpening(false);
      onReveal(win);
    }, 2000);
  };

  return (
    <div className="p-8 rounded-3xl bg-zinc-900 border-2 border-zinc-800 flex flex-col items-center justify-center text-center overflow-hidden relative">
      <div className="absolute inset-0 bg-gradient-to-br from-pink-500/5 to-purple-500/5"></div>

      {!reward ? (
        <>
          <div className={`text-7xl mb-6 transition-transform duration-300 ${isOpening ? 'animate-bounce' : 'hover:scale-110'}`}>
            🎁
          </div>
          <h2 className="text-2xl font-serif mb-2">Mystery Vault</h2>
          <p className="text-zinc-400 text-sm mb-6 max-w-xs">
            Unlock rare rewards, legendary coupons, and exclusive drops.
          </p>
          <button
            disabled={isOpening}
            onClick={handleOpen}
            className="px-8 py-3 bg-white text-black rounded-full font-black text-sm uppercase tracking-widest hover:bg-pink-500 hover:text-white transition-all duration-300 shadow-xl shadow-white/5 disabled:opacity-50"
          >
            {isOpening ? 'Cracking Vault...' : `Open for ${cost} Gems`}
          </button>
        </>
      ) : (
        <div className="animate-in fade-in zoom-in duration-500">
          <div className="text-5xl mb-4">✨</div>
          <h2 className="text-3xl font-serif text-white mb-2 italic">You Unlocked!</h2>
          <div className="text-xl font-bold text-pink-500 mb-6 bg-pink-500/10 px-4 py-2 rounded-xl">
            {reward}
          </div>
          <button
            onClick={() => setReward(null)}
            className="text-xs font-bold text-zinc-500 hover:text-white uppercase"
          >
            Try Another?
          </button>
        </div>
      )}
    </div>
  );
};

export default MysteryBox;

import React, { useState } from 'react';
