import React, { useState, useEffect, useCallback } from 'react';
import Navbar from './components/Navbar';
import ProductCard from './components/ProductCard';
import StylistAI from './components/StylistAI';
import MysteryBox from './components/MysteryBox';
import { MOCK_PRODUCTS } from './constants';
import { UserStats, Notification, GameState } from './types';

const App: React.FC = () => {
  const [view, setView] = useState<GameState>(GameState.HOME);
  const [stats, setStats] = useState<UserStats>({
    coins: 2450,
    gems: 12,
    streak: 3,
    rank: 'Gold Fashionista'
  });
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [timeLeft, setTimeLeft] = useState(300); // 5 minute flash deal

  // Flash Sale Timer
  useEffect(() => {
    if (timeLeft <= 0) return;
    const timer = setInterval(() => setTimeLeft(prev => prev - 1), 1000);
    return () => clearInterval(timer);
  }, [timeLeft]);

  // FOMO Notifications generator
  useEffect(() => {
    const interval = setInterval(() => {
      const names = ['Sarah', 'James', 'Marco', 'Elena', 'Kaito'];
      const actions = ['just bought the Cyber Jacket', 'unlocked a Rare Box', 'grabbed the last Pair of Heels'];
      const newNotif = {
        id: Math.random().toString(),
        message: `${names[Math.floor(Math.random() * names.length)]} ${actions[Math.floor(Math.random() * actions.length)]}!`,
        type: 'sale' as const
      };
      setNotifications(prev => [newNotif, ...prev.slice(0, 2)]);

      // Auto remove after 5s
      setTimeout(() => {
        setNotifications(prev => prev.filter(n => n.id !== newNotif.id));
      }, 5000);
    }, 8000);
    return () => clearInterval(interval);
  }, []);

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const handleAddToCart = (id: string) => {
    // Basic gamification: Buying gives coins
    setStats(prev => ({ ...prev, coins: prev.coins + 50 }));
    // More complex UI feedback could be here
  };

  const handleMysteryReveal = (reward: string) => {
    setStats(prev => ({ ...prev, gems: Math.max(0, prev.gems - 5) }));
    // In a real app, update user inventory/coupons
  };

  const renderView = () => {
    switch (view) {
      case GameState.HOME:
        return (
          <main className="px-6 py-12 max-w-7xl mx-auto">
            {/* Hero Section */}
            <div className="relative rounded-[2rem] overflow-hidden bg-zinc-900 h-[70vh] flex items-center mb-12 border border-zinc-800">
              <img src="https://picsum.photos/seed/hero/1600/900" className="absolute inset-0 w-full h-full object-cover opacity-40 mix-blend-overlay" />
              <div className="relative z-10 px-12 max-w-2xl">
                <div className="inline-flex items-center gap-2 bg-pink-500 text-[10px] font-black tracking-widest px-3 py-1 rounded-full uppercase mb-6 shadow-lg shadow-pink-500/30">
                  <span className="w-1.5 h-1.5 rounded-full bg-white animate-pulse"></span> Live Drop: Spring Cyberpunk
                </div>
                <h1 className="text-7xl font-serif italic text-white leading-[0.9] mb-8">
                  Style that <br/> <span className="text-pink-500">Demands</span> Attention.
                </h1>
                <p className="text-zinc-300 text-lg mb-8 leading-relaxed">
                  Join 12k+ trendsetters. Build your streak. Unlock the legendary vault.
                </p>
                <div className="flex gap-4">
                  <button 
                    onClick={() => setView(GameState.SHOP)}
                    className="px-10 py-4 bg-white text-black font-black uppercase tracking-widest rounded-xl hover:bg-pink-500 hover:text-white transition-all shadow-xl shadow-white/5 active:scale-95"
                  >
                    Shop Flash Drop
                  </button>
                  <button 
                    onClick={() => setView(GameState.MYSTERY_BOX)}
                    className="px-10 py-4 border border-zinc-700 text-white font-bold uppercase tracking-widest rounded-xl hover:bg-zinc-800 transition-all active:scale-95"
                  >
                    Open Vault
                  </button>
                </div>
              </div>
            </div>

            {/* Trending Preview */}
            <div className="mb-12">
              <div className="flex justify-between items-end mb-8">
                <div>
                  <h2 className="text-3xl font-serif">Hype-Meter Trending</h2>
                  <p className="text-zinc-500 text-sm">Real-time demand tracking</p>
                </div>
                <div className="text-sm font-bold text-pink-500 flex items-center gap-2">
                  View All Trends <span className="text-lg">→</span>
                </div>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                {MOCK_PRODUCTS.slice(0, 4).map(p => (
                  <ProductCard key={p.id} product={p} onAddToCart={handleAddToCart} />
                ))}
              </div>
            </div>
          </main>
        );
      case GameState.SHOP:
        return (
          <div className="px-6 py-12 max-w-7xl mx-auto">
            {/* Flash Sale Header */}
            <div className="bg-gradient-to-r from-red-600 to-pink-600 rounded-2xl p-8 mb-12 flex flex-col md:flex-row items-center justify-between gap-6 shadow-2xl shadow-red-600/20">
              <div className="text-center md:text-left">
                <h2 className="text-4xl font-black uppercase tracking-tighter italic">Rush Hour Sale!</h2>
                <p className="text-red-100 font-medium">Extra 20% off ends when the timer hits zero.</p>
              </div>
              <div className="bg-black/20 backdrop-blur-sm px-8 py-4 rounded-2xl border border-white/20 text-center">
                <div className="text-[10px] font-bold uppercase tracking-widest text-red-100 mb-1">Price Spike In</div>
                <div className="text-5xl font-black tabular-nums">{formatTime(timeLeft)}</div>
              </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
              {MOCK_PRODUCTS.map(p => (
                <ProductCard key={p.id} product={p} onAddToCart={handleAddToCart} />
              ))}
            </div>
          </div>
        );
      case GameState.AI_STYLIST:
        return <StylistAI />;
      case GameState.MYSTERY_BOX:
        return (
          <div className="max-w-xl mx-auto py-24 px-6">
            <MysteryBox onReveal={handleMysteryReveal} cost={5} />
            <div className="mt-12 grid grid-cols-3 gap-4 text-center">
              <div className="p-4 bg-zinc-900 border border-zinc-800 rounded-xl">
                <div className="text-2xl mb-1">💎</div>
                <div className="text-xs text-zinc-500">Your Gems</div>
                <div className="font-bold">{stats.gems}</div>
              </div>
              <div className="p-4 bg-zinc-900 border border-zinc-800 rounded-xl">
                <div className="text-2xl mb-1">📈</div>
                <div className="text-xs text-zinc-500">Win Rate</div>
                <div className="font-bold text-green-400">High</div>
              </div>
              <div className="p-4 bg-zinc-900 border border-zinc-800 rounded-xl">
                <div className="text-2xl mb-1">🔥</div>
                <div className="text-xs text-zinc-500">Streak</div>
                <div className="font-bold text-orange-400">{stats.streak} Days</div>
              </div>
            </div>
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen pb-24">
      <Navbar stats={stats} currentView={view} onNavigate={setView} />

      {/* FOMO Toasts */}
      <div className="fixed bottom-6 right-6 z-[60] flex flex-col gap-3 pointer-events-none">
        {notifications.map(n => (
          <div key={n.id} className="bg-zinc-900/90 backdrop-blur border border-zinc-800 px-4 py-3 rounded-xl shadow-2xl animate-in slide-in-from-right-full duration-300 flex items-center gap-3">
            <div className="w-2 h-2 rounded-full bg-pink-500"></div>
            <p className="text-xs font-medium text-zinc-100">{n.message}</p>
          </div>
        ))}
      </div>

      {renderView()}

      {/* Bottom Sticky CTA for Flash Sale */}
      {view !== GameState.SHOP && (
        <div className="fixed bottom-0 left-0 right-0 p-4 z-40 bg-gradient-to-t from-zinc-950 to-transparent flex justify-center pointer-events-none">
          <button 
            onClick={() => setView(GameState.SHOP)}
            className="pointer-events-auto bg-pink-600 text-white px-8 py-3 rounded-full font-bold shadow-xl shadow-pink-500/40 border border-white/20 animate-bounce hover:scale-105 transition-transform"
          >
            🔥 Flash Deals Ending in {formatTime(timeLeft)}!
          </button>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { getStylingAdvice, generateDreamOutfit } from '../services/geminiService';

const StylistAI: React.FC = () => {
  // Styling Advice State
  const [mood, setMood] = useState('');
  const [occasion, setOccasion] = useState('');
  const [advice, setAdvice] = useState('');
  const [isLoadingAdvice, setIsLoadingAdvice] = useState(false);

  // Dream Outfit State
  const [dreamDescription, setDreamDescription] = useState('');
  const [dreamImage, setDreamImage] = useState<string | null>(null);
  const [isGeneratingImage, setIsGeneratingImage] = useState(false);

  const handleConsult = async () => {
    if (!mood || !occasion) return;
    setIsLoadingAdvice(true);
    try {
      const result = await getStylingAdvice(mood, occasion);
      setAdvice(result || "My stylistic sensors are jammed. Try again later, darling.");
    } catch (error) {
      setAdvice("Oops! Even fashion geniuses have off days. Try later.");
    } finally {
      setIsLoadingAdvice(false);
    }
  };

  const handleGenerateDream = async () => {
    if (!dreamDescription) return;
    setIsGeneratingImage(true);
    try {
