import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import ProductCard from './components/ProductCard';
import StylistAI from './components/StylistAI';
import MysteryBox from './components/MysteryBox';
import { MOCK_PRODUCTS } from './constants';
import { UserStats, Notification, GameState } from './types';

const App: React.FC = () => {
  const [view, setView] = useState<GameState>(GameState.HOME);
  const [stats, setStats] = useState<UserStats>({
    coins: 2450,
    gems: 12,
    streak: 3,
    rank: 'Gold Fashionista'
  });
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [timeLeft, setTimeLeft] = useState(300);

  useEffect(() => {
    if (timeLeft <= 0) return;
    const timer = setInterval(() => setTimeLeft(prev => prev - 1), 1000);
    return () => clearInterval(timer);
  }, [timeLeft]);

  useEffect(() => {
    const interval = setInterval(() => {
      const names = ['Sarah', 'James', 'Marco', 'Elena', 'Kaito'];
      const actions = ['bought the Cyber Jacket', 'unlocked a Rare Box', 'grabbed the last pair'];
      const newNotif = {
        id: Math.random().toString(),
        message: `${names[Math.floor(Math.random() * names.length)]} ${actions[Math.floor(Math.random() * actions.length)]}!`,
        type: 'sale' as const
      };
      setNotifications(prev => [newNotif, ...prev.slice(0, 2)]);
      setTimeout(() => {
        setNotifications(prev => prev.filter(n => n.id !== newNotif.id));
      }, 5000);
    }, 12000);
    return () => clearInterval(interval);
  }, []);

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const handleAddToCart = (id: string) => {
    setStats(prev => ({ ...prev, coins: prev.coins + 50 }));
  };

  const handleMysteryReveal = (reward: string) => {
    setStats(prev => ({ ...prev, gems: Math.max(0, prev.gems - 5) }));
  };

  const renderView = () => {
    switch (view) {
      case GameState.HOME:
        return (
          <main className="px-4 md:px-6 py-6 md:py-12 max-w-7xl mx-auto space-y-12">
            {/* Hero Section */}
            <div className="relative rounded-[1.5rem] md:rounded-[2rem] overflow-hidden bg-zinc-900 min-h-[50vh] md:h-[70vh] flex items-center border border-zinc-800">
              <img src="https://picsum.photos/seed/hero/1600/900" className="absolute inset-0 w-full h-full object-cover opacity-30 md:opacity-40 mix-blend-overlay" />
              <div className="relative z-10 p-6 md:p-12 max-w-2xl">
                <div className="inline-flex items-center gap-2 bg-pink-500 text-[9px] md:text-[10px] font-black tracking-widest px-3 py-1 rounded-full uppercase mb-4 md:mb-6 shadow-lg shadow-pink-500/30">
                  <span className="w-1.5 h-1.5 rounded-full bg-white animate-pulse"></span> Live Drop: Spring Cyberpunk
                </div>
                <h1 className="text-4xl md:text-7xl font-serif italic text-white leading-[1] mb-6 md:mb-8">
                  Style that <br className="hidden md:block"/> <span className="text-pink-500">Demands</span> Attention.
                </h1>
                <p className="text-zinc-400 text-sm md:text-lg mb-8 leading-relaxed max-w-md">
                  Join 12k+ trendsetters. Build your streak. Unlock the legendary vault.
                </p>
                <div className="flex flex-col sm:flex-row gap-4">
                  <button 
                    onClick={() => setView(GameState.SHOP)}
                    className="w-full sm:w-auto px-8 py-4 bg-white text-black font-black uppercase tracking-widest rounded-xl hover:bg-pink-500 hover:text-white transition-all shadow-xl active:scale-95 text-xs"
                  >
                    Shop Flash Drop
                  </button>
                  <button 
                    onClick={() => setView(GameState.MYSTERY_BOX)}
                    className="w-full sm:w-auto px-8 py-4 border border-zinc-700 text-white font-bold uppercase tracking-widest rounded-xl hover:bg-zinc-800 transition-all active:scale-95 text-xs"
                  >
                    Open Vault
                  </button>
                </div>
              </div>
            </div>

            {/* Trending Preview */}
            <div className="space-y-6">
              <div className="flex justify-between items-end">
                <div>
                  <h2 className="text-2xl md:text-3xl font-serif">Trending Now</h2>
                  <p className="text-zinc-500 text-xs md:text-sm">Real-time demand tracking</p>
                </div>
                <button onClick={() => setView(GameState.SHOP)} className="text-[10px] md:text-sm font-bold text-pink-500 flex items-center gap-2 uppercase tracking-widest">
                  View All <span className="text-lg">→</span>
                </button>
              </div>
              {/* Responsive Grid: 2 columns on mobile, 4 on desktop */}
              <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 md:gap-6">
                {MOCK_PRODUCTS.slice(0, 4).map(p => (
                  <ProductCard key={p.id} product={p} onAddToCart={handleAddToCart} />
                ))}
              </div>
            </div>
          </main>
        );
      case GameState.SHOP:
        return (
          <div className="px-4 md:px-6 py-6 md:py-12 max-w-7xl mx-auto">
            {/* Responsive Flash Sale Banner */}
            <div className="bg-gradient-to-br from-red-600 to-pink-600 rounded-xl md:rounded-2xl p-6 md:p-8 mb-8 md:mb-12 flex flex-col md:flex-row items-center justify-between gap-6 shadow-2xl shadow-red-600/20">
              <div className="text-center md:text-left space-y-1">
                <h2 className="text-2xl md:text-4xl font-black uppercase tracking-tighter italic">Rush Hour Sale!</h2>
                <p className="text-red-100 font-medium text-xs md:text-base">Extra 20% off ends when the timer hits zero.</p>
              </div>
              <div className="bg-black/20 backdrop-blur-sm px-6 md:px-8 py-3 md:py-4 rounded-xl md:rounded-2xl border border-white/20 text-center w-full md:w-auto">
