          </div>
        );
      case GameState.AI_STYLIST:
        return <StylistAI />;
      case GameState.MYSTERY_BOX:
        return (
          <div className="max-w-xl mx-auto py-12 md:py-24 px-4 md:px-6">
            <MysteryBox onReveal={handleMysteryReveal} cost={5} />
            <div className="mt-8 md:mt-12 grid grid-cols-3 gap-3 md:gap-4 text-center">
              <div className="p-3 md:p-4 bg-zinc-900 border border-zinc-800 rounded-xl">
                <div className="text-xl md:text-2xl mb-1">💎</div>
                <div className="text-[10px] text-zinc-500 uppercase font-bold">Gems</div>
                <div className="font-black text-sm md:text-base">{stats.gems}</div>
              </div>
              <div className="p-3 md:p-4 bg-zinc-900 border border-zinc-800 rounded-xl">
                <div className="text-xl md:text-2xl mb-1">📈</div>
                <div className="text-[10px] text-zinc-500 uppercase font-bold">Win Rate</div>
                <div className="font-black text-sm md:text-base text-green-400">High</div>
              </div>
              <div className="p-3 md:p-4 bg-zinc-900 border border-zinc-800 rounded-xl">
                <div className="text-xl md:text-2xl mb-1">🔥</div>
                <div className="text-[10px] text-zinc-500 uppercase font-bold">Streak</div>
                <div className="font-black text-sm md:text-base text-orange-400">{stats.streak}d</div>
              </div>
            </div>
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen pb-24 md:pb-0 selection:bg-pink-500/30">
      <Navbar stats={stats} currentView={view} onNavigate={setView} />

      {/* FOMO Toasts - Elevated on mobile to avoid bottom nav overlap */}
