            <div className="space-y-6 md:space-y-8 bg-zinc-900/50 p-6 md:p-8 rounded-2xl border border-zinc-800">
              <div>
                <label className="block text-[10px] font-black text-zinc-500 uppercase tracking-widest mb-2 md:mb-3">The Vibe</label>
