const App: React.FC = () => {
  const [view, setView] = useState<GameState>(GameState.HOME);
  const [logoUrl, setLogoUrl] = useState<string | null>(localStorage.getItem('cc_logo'));
  const [stats, setStats] = useState<UserStats>({
    coins: 2450,
    gems: 12,
    streak: 3,
    rank: 'Gold Fashionista'
  });
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [timeLeft, setTimeLeft] = useState(300);

  // Logo Generation Logic
  useEffect(() => {
    const initLogo = async () => {
      if (!logoUrl) {
        try {
          const generated = await generateAppLogo();
          if (generated) {
            setLogoUrl(generated);
            localStorage.setItem('cc_logo', generated);
          }
        } catch (error) {
          console.error("Failed to generate brand logo", error);
        }
      }
    };
    initLogo();
  }, [logoUrl]);

  useEffect(() => {
    if (timeLeft <= 0) return;
    const timer = setInterval(() => setTimeLeft(prev => prev - 1), 1000);
    return () => clearInterval(timer);
  }, [timeLeft]);

  useEffect(() => {
    const interval = setInterval(() => {
      const names = ['Sarah', 'James', 'Marco', 'Elena', 'Kaito'];
      const actions = ['bought the Cyber Jacket', 'unlocked a Rare Box', 'grabbed the last pair'];
      const newNotif = {
        id: Math.random().toString(),
        message: `${names[Math.floor(Math.random() * names.length)]} ${actions[Math.floor(Math.random() * actions.length)]}!`,
        type: 'sale' as const
      };
      setNotifications(prev => [newNotif, ...prev.slice(0, 2)]);
      setTimeout(() => {
        setNotifications(prev => prev.filter(n => n.id !== newNotif.id));
      }, 5000);
    }, 12000);
    return () => clearInterval(interval);
  }, []);

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
