                <div className="text-[10px] font-black text-red-500/50 uppercase tracking-[0.2em]">Tick Tock, Hunter.</div>
              </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
              {MOCK_PRODUCTS.map(p => (
                <ProductCard key={p.id} product={p} onAddToCart={handleAddToCart} />
              ))}
            </div>
          </div>
        );
      case GameState.AI_STYLIST:
        return <StylistAI />;
      case GameState.MYSTERY_BOX:
        return (
          <div className="max-w-2xl mx-auto py-20 px-6 animate-in slide-in-from-bottom-8 duration-700">
