            }`}
          >
            <div className={`w-2 h-2 rounded-full animate-pulse ${n.type === 'level_up' ? 'bg-yellow-500' : 'bg-pink-500'}`}></div>
            <p className="text-[10px] font-black text-zinc-100 uppercase tracking-tighter leading-tight">{n.message}</p>
          </div>
        ))}
      </div>

      <div className="pt-8">
        {renderView()}
      </div>

      {/* Persistent Level Progress Bar (Mobile) */}
      <div className="md:hidden fixed bottom-[72px] left-0 right-0 h-1 bg-zinc-900 z-50">
         <div 
          className="h-full bg-pink-500 shadow-[0_0_10px_rgba(236,72,153,0.8)] transition-all duration-1000"
          style={{ width: `${(stats.xp/stats.maxXP)*100}%` }}
         ></div>
      </div>

      {/* Persistent CTA */}
      {view !== GameState.SHOP && view !== GameState.OUTFIT_BUILDER && (
        <div className="fixed bottom-24 md:bottom-10 left-1/2 -translate-x-1/2 z-50 pointer-events-auto">
          <button 
            onClick={() => setView(GameState.SHOP)}
            className="bg-white text-black px-10 py-4 rounded-full text-[10px] font-black uppercase tracking-widest shadow-3xl hover:bg-pink-500 hover:text-white transition-all active:scale-95 flex items-center gap-4 group"
          >
            <span>Raid the Drops</span>
            <span className="bg-black text-white px-3 py-1 rounded-full group-hover:bg-white group-hover:text-pink-500 transition-colors">
              {Math.floor(timeLeft / 60)}:{(timeLeft % 60).toString().padStart(2, '0')}
            </span>
          </button>
        </div>
      )}
    </div>
  );
};

