interface LandingScreenProps {
  onComplete: (archetype: string) => void;
}

const LandingScreen: React.FC<LandingScreenProps> = ({ onComplete }) => {
  const [step, setStep] = useState<'START' | 'QUIZ' | 'REVEAL'>('START');
  const [currentQuizIndex, setCurrentQuizIndex] = useState(0);
  const [selectedArchetype, setSelectedArchetype] = useState<string>('');

  const handleOptionSelect = (archetype: string) => {
    setSelectedArchetype(archetype);
    if (currentQuizIndex < QUIZ_STEPS.length - 1) {
      setCurrentQuizIndex(prev => prev + 1);
    } else {
      setStep('REVEAL');
    }
  };

  if (step === 'START') {
    return (
      <div className="fixed inset-0 z-[100] bg-black flex flex-col items-center justify-center p-6 text-center">
        <div className="absolute inset-0 opacity-40">
           <img src="https://images.unsplash.com/photo-1490481651871-ab68de25d43d?auto=format&fit=crop&q=80&w=1600" className="w-full h-full object-cover" alt="Fashion Background" />
           <div className="absolute inset-0 bg-gradient-to-t from-black via-black/80 to-transparent"></div>
        </div>
        <div className="relative z-10 space-y-8 animate-in fade-in zoom-in-95 duration-1000">
          <div className="text-[10px] font-black uppercase tracking-[0.5em] text-pink-500 mb-4">Closet Craze Protocol v1.0</div>
          <h1 className="text-5xl md:text-8xl font-serif italic text-white leading-none tracking-tighter">
            Your Closet Is a Game.<br/><span className="not-italic font-sans font-black text-pink-500 glow-text uppercase">Play It Better.</span>
          </h1>
          <p className="text-zinc-400 text-sm md:text-lg max-w-xl mx-auto uppercase font-bold tracking-tight">
            Stop shopping. Start progressing. Discover your archetype and unlock the high-fashion circuit.
          </p>
          <div className="flex flex-col md:flex-row gap-4 justify-center pt-8">
            <button 
              onClick={() => setStep('QUIZ')}
              className="px-12 py-5 bg-white text-black rounded-2xl font-black uppercase tracking-widest text-xs hover:bg-pink-500 hover:text-white transition-all shadow-2xl active:scale-95"
            >
              Start Your Style Run
            </button>
            <button className="px-12 py-5 glass text-zinc-500 rounded-2xl font-black uppercase tracking-widest text-xs hover:text-white transition-colors">
              Browse as Guest
            </button>
          </div>
        </div>
      </div>
    );
  }

  if (step === 'QUIZ') {
    const currentStep = QUIZ_STEPS[currentQuizIndex];
    const progress = ((currentQuizIndex + 1) / QUIZ_STEPS.length) * 100;

    return (
      <div className="fixed inset-0 z-[100] bg-zinc-950 flex flex-col items-center justify-center p-6">
        <div className="w-full max-w-4xl space-y-12">
          <div className="space-y-4 text-center">
            <div className="w-full h-1 bg-zinc-900 rounded-full overflow-hidden">
               <div className="h-full bg-pink-500 transition-all duration-500" style={{ width: `${progress}%` }}></div>
            </div>
            <div className="text-[10px] font-black text-zinc-600 uppercase tracking-widest">{Math.floor(progress)}% Complete</div>
            <h2 className="text-4xl font-serif italic text-white">{currentStep.question}</h2>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {currentStep.options.map((opt) => (
              <div 
                key={opt.id}
                onClick={() => handleOptionSelect(opt.archetype)}
                className="group relative aspect-[3/4] rounded-3xl overflow-hidden cursor-pointer border-2 border-transparent hover:border-pink-500 transition-all hover:scale-[1.02]"
              >
                <img src={opt.img} className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-700" alt={opt.label} />
                <div className="absolute inset-0 bg-gradient-to-t from-black to-transparent opacity-80"></div>
                <div className="absolute bottom-6 left-6">
                   <div className="text-xs font-black text-white uppercase tracking-widest">{opt.label}</div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    );
  }

  if (step === 'REVEAL') {
    const names: Record<string, string> = {
      'CYBER': 'The Street Vanguard',
      'LUXE': 'The Ethereal Heir',
      'VOID': 'The Void Minimalist'
    };
    const desc: Record<string, string> = {
      'CYBER': 'You command attention through tactical neon and technical silhouettes.',
      'LUXE': 'You dress to signal status without whispering a single word.',
      'VOID': 'Your presence is felt through the absence of noise and the power of form.'
    };

    return (
      <div className="fixed inset-0 z-[100] bg-black flex flex-col items-center justify-center p-6 text-center animate-in fade-in duration-1000">
        <div className="absolute inset-0 overflow-hidden">
           <div className="absolute inset-0 bg-gradient-to-b from-pink-500/20 via-transparent to-black"></div>
           <div className="w-full h-full bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-zinc-800 to-black opacity-40"></div>
        </div>

        <div className="relative z-10 space-y-12 max-w-xl">
           <div className="flex flex-col items-center space-y-4">
              <div className="text-6xl animate-bounce">✨</div>
              <div className="text-[10px] font-black text-pink-500 uppercase tracking-[0.5em]">Archetype Detected</div>
           </div>

           <div className="space-y-4 animate-in slide-in-from-bottom-8 duration-1000">
              <h2 className="text-6xl md:text-7xl font-serif italic text-white leading-tight">{names[selectedArchetype]}</h2>
              <p className="text-zinc-500 text-sm md:text-lg font-medium uppercase tracking-tight leading-relaxed px-10">
                "{desc[selectedArchetype]}"
              </p>
           </div>

           <button 
             onClick={() => onComplete(selectedArchetype)}
             className="px-12 py-5 bg-white text-black rounded-2xl font-black uppercase tracking-widest text-xs hover:bg-pink-500 hover:text-white transition-all shadow-3xl shadow-pink-500/20 active:scale-95"
           >
             Enter Closet Craze
           </button>
        </div>
      </div>
    );
  }

  return null;
};

export default LandingScreen;

