import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import ProductCard from './components/ProductCard';
import StylistAI from './components/StylistAI';
import MysteryBox from './components/MysteryBox';
import HomeLobby from './components/HomeLobby';
import IdentityPaths from './components/IdentityPaths';
import OutfitBuilder from './components/OutfitBuilder';
import LandingScreen from './components/LandingScreen';
import StyleArena from './components/StyleArena';
import ProductDetail from './components/ProductDetail';
import { MOCK_PRODUCTS } from './constants';
import { UserStats, Notification, GameState, Product } from './types';
import { generateAppLogo } from './services/geminiService';

const App: React.FC = () => {
  const [view, setView] = useState<GameState>(
    localStorage.getItem('cc_onboarded') ? GameState.HOME : GameState.ONBOARDING
  );

  // Products state to handle dynamic updates like synergy changes
  const [products, setProducts] = useState<Product[]>(MOCK_PRODUCTS);
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [logoUrl, setLogoUrl] = useState<string | null>(localStorage.getItem('cc_logo'));

  // Wishlist state
  const [wishlist, setWishlist] = useState<string[]>(() => {
    const saved = localStorage.getItem('cc_wishlist');
    return saved ? JSON.parse(saved) : [];
  });

  const [stats, setStats] = useState<UserStats>({
    coins: 2450,
    gems: 12,
    streak: 3,
    rank: 'Gold Fashionista',
    level: 12,
    xp: 450,
    maxXP: 1000,
    selectedPath: localStorage.getItem('cc_path'),
    archetype: localStorage.getItem('cc_archetype'),
    quests: [
      { id: 'q1', title: 'Create 1 Outfit', rewardXP: 150, completed: false, icon: '👕' },
      { id: 'q2', title: 'Vote in Arena', rewardXP: 100, completed: false, icon: '🗳️' },
      { id: 'q3', title: 'Unlock 1 Vault', rewardXP: 250, completed: false, icon: '🎁' },
    ]
  });

  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [timeLeft, setTimeLeft] = useState(300);

  // Sync wishlist to localStorage
  useEffect(() => {
    localStorage.setItem('cc_wishlist', JSON.stringify(wishlist));
  }, [wishlist]);

  useEffect(() => {
    const initLogo = async () => {
      if (!logoUrl) {
        try {
          const generated = await generateAppLogo();
          if (generated) {
            setLogoUrl(generated);
            localStorage.setItem('cc_logo', generated);
          }
        } catch (error) {
          console.error("Failed to generate brand logo", error);
        }
      }
    };
    initLogo();
  }, [logoUrl]);

  useEffect(() => {
    if (timeLeft <= 0) return;
    const timer = setInterval(() => setTimeLeft(prev => prev - 1), 1000);
    return () => clearInterval(timer);
  }, [timeLeft]);

  const addNotification = (message: string, type: Notification['type']) => {
    const id = Math.random().toString();
    setNotifications(prev => [{ id, message, type }, ...prev.slice(0, 2)]);
    setTimeout(() => {
      setNotifications(prev => prev.filter(n => n.id !== id));
    }, 5000);
  };

  const gainXP = (amount: number) => {
    setStats(prev => {
      let newXP = prev.xp + amount;
      let newLevel = prev.level;
      let newMaxXP = prev.maxXP;

      if (newXP >= newMaxXP) {
        newLevel += 1;
        newXP = newXP - newMaxXP;
        newMaxXP = Math.floor(newMaxXP * 1.2);
        addNotification(`LEVEL UP! REACHED LEVEL ${newLevel}`, 'level_up');
      }

      return {
        ...prev,
        xp: newXP,
        level: newLevel,
        maxXP: newMaxXP
      };
    });
  };

  const handleProductClick = (product: Product) => {
    setSelectedProduct(product);
    setView(GameState.PRODUCT_DETAIL);
  };

  const handleAddToCart = (id: string) => {
    setStats(prev => ({ ...prev, coins: prev.coins + 50 }));
    gainXP(150);
    addNotification('Item claimed! +150 XP rewarded.', 'reward');
    setView(GameState.HOME);
    setSelectedProduct(null);
  };

  const handleToggleWishlist = (id: string) => {
    setWishlist(prev => {
      if (prev.includes(id)) {
        addNotification('Removed from Wishlist.', 'reward');
        return prev.filter(item => item !== id);
      } else {
        addNotification('Added to Style Vault.', 'reward');
        return [...prev, id];
      }
    });
  };

  const handleUpdateProductSynergy = (synergy: string) => {
    if (!selectedProduct) return;

    // Update local products list
    setProducts(prev => prev.map(p => 
      p.id === selectedProduct.id ? { ...p, synergyPath: synergy } : p
    ));

    // Update the currently viewed product
    setSelectedProduct(prev => prev ? { ...prev, synergyPath: synergy } : null);

    addNotification(`Synergy recalibrated to ${synergy}.`, 'reward');
  };

  const handleOnboardingComplete = (archetype: string) => {
    setStats(prev => ({ ...prev, archetype }));
    localStorage.setItem('cc_archetype', archetype);
    localStorage.setItem('cc_onboarded', 'true');
    gainXP(500);
    setView(GameState.HOME);
    addNotification(`Archetype Synchronized: ${archetype}`, 'reward');
  };

  const handleCompleteQuest = (questId: string) => {
    setStats(prev => {
      const quest = prev.quests.find(q => q.id === questId);
      if (quest && !quest.completed) {
        gainXP(quest.rewardXP);
        addNotification(`Quest Completed: ${quest.title}!`, 'reward');
        return {
          ...prev,
          quests: prev.quests.map(q => q.id === questId ? { ...q, completed: true } : q)
        };
      }
      return prev;
    });
  };

  const handleVoteInArena = () => {
    gainXP(20);
    handleCompleteQuest('q2');
  };

  const renderView = () => {
    switch (view) {
      case GameState.ONBOARDING:
        return <LandingScreen onComplete={handleOnboardingComplete} />;
      case GameState.HOME:
        return (
          <HomeLobby 
            products={products} 
            stats={stats} 
            onNavigate={setView} 
            onAddToCart={() => {}} 
            onCompleteQuest={handleCompleteQuest}
          />
        );
      case GameState.ARENA:
        return <StyleArena onVote={handleVoteInArena} onExit={() => setView(GameState.HOME)} />;
      case GameState.PRODUCT_DETAIL:
        return selectedProduct ? (
          <ProductDetail 
            product={selectedProduct} 
            stats={stats} 
            onClose={() => setView(GameState.HOME)} 
            onAddToOutfit={handleAddToCart}
            onUpdateSynergy={handleUpdateProductSynergy}
            onToggleWishlist={handleToggleWishlist}
            isInWishlist={wishlist.includes(selectedProduct.id)}
          />
        ) : null;
      case GameState.OUTFIT_BUILDER:
        return (
          <OutfitBuilder 
            products={products} 
            stats={stats} 
            onNavigate={setView} 
            onLockLook={(items) => {
              gainXP(items.length * 200);
              handleCompleteQuest('q1');
              setView(GameState.HOME);
            }}
          />
        );
      case GameState.SHOP:
        return (
          <div className="px-6 md:px-10 py-10 max-w-7xl mx-auto space-y-12 animate-in fade-in duration-700">
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
              {products.map(p => (
                <div key={p.id} onClick={() => handleProductClick(p)} className="cursor-pointer">
                  <ProductCard product={p} onAddToCart={(id) => {
                    const found = products.find(p => p.id === id);
                    if (found) handleProductClick(found);
                  }} />
                </div>
              ))}
            </div>
          </div>
        );
      case GameState.AI_STYLIST: return <StylistAI />;
      case GameState.MYSTERY_BOX: return (
        <div className="max-w-2xl mx-auto py-20 px-6">
          <MysteryBox onReveal={(r) => { gainXP(300); handleCompleteQuest('q3'); }} cost={5} />
        </div>
      );
      case GameState.PATH_SELECTION: return <IdentityPaths onSelect={(p) => { 
        setStats(s => ({...s, selectedPath: p})); 
        setView(GameState.HOME); 
      }} currentPath={stats.selectedPath} />;
      default: return null;
    }
  };

  return (
    <div className="min-h-screen pb-32 md:pb-0 selection:bg-pink-500/30">
      {view !== GameState.ONBOARDING && (
        <Navbar stats={stats} currentView={view} onNavigate={setView} logoUrl={logoUrl} />
      )}

      {view !== GameState.ONBOARDING && (
        <div className="fixed top-[74px] left-0 right-0 z-40 bg-pink-600 h-8 flex items-center overflow-hidden border-y border-white/10 shadow-lg">
          <div className="whitespace-nowrap flex gap-20 animate-marquee text-[10px] font-black uppercase tracking-[0.3em] text-white/90">
            <span>🔥 NEW ARENA CHALLENGE: MIDNIGHT GALA</span>
            <span>💎 GEMS MULTIPLIER ACTIVE FOR {stats.archetype} ARCHETYPE</span>
            <span>⚡ NEXT DROP IN {Math.floor(timeLeft / 60)}:{(timeLeft % 60).toString().padStart(2, '0')}</span>
          </div>
        </div>
      )}

      {/* Notifications */}
      <div className="fixed bottom-24 md:bottom-8 right-6 z-[110] flex flex-col gap-3 pointer-events-none">
        {notifications.map(n => (
          <div key={n.id} className="glass px-5 py-3 rounded-2xl shadow-2xl animate-in slide-in-from-right-full duration-700 flex items-center gap-4 border-l-4 border-pink-500">
            <p className="text-[10px] font-black text-zinc-100 uppercase tracking-tighter leading-tight">{n.message}</p>
          </div>
        ))}
      </div>

      <div className={view === GameState.ONBOARDING ? '' : 'pt-8'}>
        {renderView()}
      </div>

      {/* Progress Bar (Global) */}
      {view !== GameState.ONBOARDING && (
        <div className="fixed bottom-[72px] md:bottom-0 left-0 right-0 h-1 bg-zinc-900 z-[100]">
           <div 
            className="h-full bg-pink-500 shadow-[0_0_10px_rgba(236,72,153,0.8)] transition-all duration-1000"
            style={{ width: `${(stats.xp/stats.maxXP)*100}%` }}
           ></div>
        </div>
      )}

      {/* Persistent CTA */}
      {view === GameState.HOME && (
        <div className="fixed bottom-24 md:bottom-10 left-1/2 -translate-x-1/2 z-50 pointer-events-auto">
          <button 
            onClick={() => setView(GameState.SHOP)}
            className="bg-white text-black px-10 py-4 rounded-full text-[10px] font-black uppercase tracking-widest shadow-3xl hover:bg-pink-500 hover:text-white transition-all active:scale-95 flex items-center gap-4 group"
          >
            <span>Raid the Drops</span>
            <span className="bg-black text-white px-3 py-1 rounded-full group-hover:bg-white group-hover:text-pink-600 transition-colors">
              {Math.floor(timeLeft / 60)}:{(timeLeft % 60).toString().padStart(2, '0')}
            </span>
          </button>
        </div>
      )}
    </div>
  );
};

