import React, { useState, useMemo } from 'react';
import Header from './components/Header';
import Hero from './components/Hero';
import ProductGrid from './components/ProductGrid';
import CartDrawer from './components/CartDrawer';
import ProductModal from './components/ProductModal';
import Footer from './components/Footer';
import { MOCK_PRODUCTS } from './constants';
import { Product, CartItem, Page, Category } from './types';

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<Page>(Page.HOME);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [filter, setFilter] = useState<Category>('All');

  const filteredProducts = useMemo(() => {
    if (filter === 'All') return MOCK_PRODUCTS;
    return MOCK_PRODUCTS.filter(p => p.category === filter);
  }, [filter]);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        return prev.map(item => 
          item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prev, { ...product, quantity: 1 }];
    });
    setIsCartOpen(true);
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.filter(item => item.id !== id));
  };

  const updateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === id) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }));
  };

  return (
    <div className="min-h-screen bg-[#FDFDFD] text-[#1A1A1A] selection:bg-[#E5E5E5]">
      <Header 
        cartCount={cart.reduce((acc, item) => acc + item.quantity, 0)} 
        onCartOpen={() => setIsCartOpen(true)}
        onNavigate={setCurrentPage}
        currentPage={currentPage}
      />

      <main className="pt-20">
        {currentPage === Page.HOME && (
          <>
            <Hero onShopNow={() => setCurrentPage(Page.SHOP)} />
            <section className="px-6 md:px-12 py-20">
              <div className="flex flex-col md:flex-row justify-between items-baseline mb-12 gap-6">
                <h2 className="text-4xl font-serif italic">New Arrivals</h2>
                <div className="flex gap-8 overflow-x-auto pb-4 md:pb-0 scrollbar-hide">
                  {(['All', 'Apparel', 'Accessories', 'Home', 'Beauty'] as Category[]).map(cat => (
                    <button 
                      key={cat}
                      onClick={() => setFilter(cat)}
                      className={`text-xs uppercase tracking-[0.2em] font-bold whitespace-nowrap transition-colors ${
                        filter === cat ? 'text-black border-b border-black' : 'text-zinc-400 hover:text-black'
                      }`}
                    >
                      {cat}
                    </button>
                  ))}
                </div>
              </div>
              <ProductGrid 
                products={filteredProducts} 
                onProductClick={setSelectedProduct}
                onAddToCart={addToCart}
              />
            </section>
          </>
        )}

        {currentPage === Page.SHOP && (
          <section className="px-6 md:px-12 py-12">
            <h1 className="text-6xl font-serif italic mb-12">The Collection</h1>
            <ProductGrid 
              products={MOCK_PRODUCTS} 
              onProductClick={setSelectedProduct}
              onAddToCart={addToCart}
            />
          </section>
        )}
      </main>

      <Footer />

      <CartDrawer 
        isOpen={isCartOpen} 
        onClose={() => setIsCartOpen(false)} 
        items={cart}
        onRemove={removeFromCart}
        onUpdateQuantity={updateQuantity}
      />

      {selectedProduct && (
        <ProductModal 
          product={selectedProduct} 
          onClose={() => setSelectedProduct(null)} 
          onAddToCart={addToCart}
        />
      )}
    </div>
  );
};

