import { Product, CartItem, Page, Category } from './types';

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<Page>(Page.HOME);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [filter, setFilter] = useState<Category>('All');

  // Psychological triggers: Urgency
  const [timeLeft, setTimeLeft] = useState(300); // 5 minute drop timer
  const [recentPurchase, setRecentPurchase] = useState<string | null>(null);

  useEffect(() => {
    const timer = setInterval(() => {
      setTimeLeft(prev => (prev > 0 ? prev - 1 : 0));
    }, 1000);

    const notificationTimer = setInterval(() => {
      const names = ['Leo', 'Sarah', 'Alex', 'Mika', 'Jordan'];
      const city = ['NYC', 'London', 'Tokyo', 'Berlin', 'Seoul'];
      setRecentPurchase(`${names[Math.floor(Math.random() * 5)]} from ${city[Math.floor(Math.random() * 5)]} just grabbed a Cyber Cloak`);
      setTimeout(() => setRecentPurchase(null), 4000);
    }, 15000);

    return () => {
      clearInterval(timer);
      clearInterval(notificationTimer);
    };
  }, []);

  const filteredProducts = useMemo(() => {
    if (filter === 'All') return MOCK_PRODUCTS;
    return MOCK_PRODUCTS.filter(p => p.category === filter);
  }, [filter]);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        return prev.map(item => 
          item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prev, { ...product, quantity: 1 }];
    });
    setIsCartOpen(true);
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.filter(item => item.id !== id));
  };

  const updateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === id) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }));
  };

  return (
    <div className="min-h-screen bg-[#050505] text-[#FAFAFA] selection:bg-[#EC4899]/30">
      <Header 
        cartCount={cart.reduce((acc, item) => acc + item.quantity, 0)} 
        onCartOpen={() => setIsCartOpen(true)}
        onNavigate={setCurrentPage}
        currentPage={currentPage}
        dropTime={timeLeft}
      />

      {/* Social Proof Notification */}
      {recentPurchase && (
        <div className="fixed bottom-10 left-10 z-[200] glass px-6 py-4 rounded-2xl shadow-2xl animate-in slide-in-from-left-full duration-700 flex items-center gap-4 border-l-4 border-[#EC4899]">
          <div className="w-10 h-10 rounded-full bg-zinc-800 flex items-center justify-center">👤</div>
          <p className="text-xs font-bold text-zinc-300 uppercase tracking-tighter leading-tight">{recentPurchase}</p>
        </div>
      )}

      <main className="pt-24">
        {currentPage === Page.HOME && (
          <>
            <Hero onShopNow={() => setCurrentPage(Page.SHOP)} />
            <section className="px-6 md:px-12 py-20 bg-zinc-950/50">
              <div className="flex flex-col md:flex-row justify-between items-end mb-16 gap-6">
                <div>
                  <div className="text-[10px] font-black text-[#EC4899] uppercase tracking-[0.4em] mb-4">Limited Availability</div>
                  <h2 className="text-5xl md:text-7xl font-serif italic tracking-tighter">Current <span className="not-italic font-sans font-black text-white glow-text">CRAZE</span></h2>
                </div>
                <div className="flex gap-4 md:gap-8 overflow-x-auto pb-4 md:pb-0 scrollbar-hide w-full md:w-auto">
                  {(['All', 'Apparel', 'Accessories', 'Home', 'Beauty'] as Category[]).map(cat => (
                    <button 
                      key={cat}
                      onClick={() => setFilter(cat)}
                      className={`text-[10px] uppercase tracking-[0.2em] font-black whitespace-nowrap transition-all px-4 py-2 rounded-full border ${
                        filter === cat ? 'bg-white text-black border-white' : 'text-zinc-500 border-zinc-800 hover:border-zinc-500'
                      }`}
                    >
                      {cat}
                    </button>
                  ))}
                </div>
              </div>
              <ProductGrid 
                products={filteredProducts} 
                onProductClick={setSelectedProduct}
                onAddToCart={addToCart}
              />
            </section>
          </>
        )}

        {currentPage === Page.SHOP && (
          <section className="px-6 md:px-12 py-12">
            <h1 className="text-6xl font-serif italic mb-12">The Archives</h1>
            <ProductGrid 
              products={MOCK_PRODUCTS} 
              onProductClick={setSelectedProduct}
              onAddToCart={addToCart}
            />
          </section>
        )}
      </main>

      <Footer />

      <CartDrawer 
        isOpen={isCartOpen} 
        onClose={() => setIsCartOpen(false)} 
        items={cart}
        onRemove={removeFromCart}
        onUpdateQuantity={updateQuantity}
      />

      {selectedProduct && (
        <ProductModal 
          product={selectedProduct} 
          onClose={() => setSelectedProduct(null)} 
          onAddToCart={addToCart}
        />
      )}
    </div>
  );
};

export default App;

