import React, { useState, useEffect } from 'react';
import { CartItem } from '../types';

interface CartDrawerProps {
  isOpen: boolean;
  onClose: () => void;
  items: CartItem[];
  onRemove: (id: string) => void;
  onUpdateQuantity: (id: string, delta: number) => void;
}

const CartDrawer: React.FC<CartDrawerProps> = ({ isOpen, onClose, items, onRemove, onUpdateQuantity }) => {
  const subtotal = items.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const savings = items.reduce((acc, item) => acc + ((item.originalPrice - item.price) * item.quantity), 0);

  // Psychological Trigger: Loss Aversion (Cart Timer)
  const [expiry, setExpiry] = useState(600); // 10 minutes

  useEffect(() => {
    if (!isOpen || items.length === 0) return;
    const timer = setInterval(() => setExpiry(prev => (prev > 0 ? prev - 1 : 0)), 1000);
    return () => clearInterval(timer);
  }, [isOpen, items]);

  const min = Math.floor(expiry / 60);
  const sec = expiry % 60;

  return (
    <>
      <div 
        className={`fixed inset-0 bg-black/60 backdrop-blur-md z-[100] transition-opacity duration-500 ${isOpen ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}
        onClick={onClose}
      />
      <div className={`fixed top-0 right-0 h-full w-full max-w-md bg-[#09090B] z-[110] shadow-2xl transition-transform duration-700 ease-out border-l border-white/5 ${isOpen ? 'translate-x-0' : 'translate-x-full'}`}>
        <div className="h-full flex flex-col p-10">
          <div className="flex justify-between items-center mb-12">
            <div>
              <h2 className="text-3xl font-serif italic text-white leading-none">Your Haul</h2>
              <p className="text-[10px] text-zinc-600 uppercase tracking-widest mt-2">Reserved Selection</p>
            </div>
            <button onClick={onClose} className="w-10 h-10 rounded-full glass flex items-center justify-center hover:bg-white hover:text-black transition-colors">✕</button>
          </div>

          {items.length > 0 && (
            <div className="bg-[#EC4899]/10 border border-[#EC4899]/20 p-4 rounded-xl mb-10 flex items-center justify-between">
               <div className="text-[10px] font-black uppercase text-[#EC4899] tracking-widest">Releasing in {min}:{sec.toString().padStart(2, '0')}</div>
               <div className="w-2 h-2 rounded-full bg-[#EC4899] animate-pulse"></div>
            </div>
          )}

          <div className="flex-1 overflow-y-auto space-y-10 pr-2 scrollbar-hide">
            {items.length === 0 ? (
              <div className="h-full flex flex-col items-center justify-center text-center">
                <div className="text-6xl mb-6 opacity-20">🎒</div>
                <p className="text-zinc-500 uppercase text-[10px] font-black tracking-[0.3em] mb-8">Archive selection is empty.</p>
                <button 
                  onClick={onClose}
                  className="px-10 py-4 bg-[#EC4899] text-white text-[10px] font-black uppercase tracking-[0.2em] shadow-xl"
                >
                  Start The Run
                </button>
              </div>
            ) : (
              items.map(item => (
                <div key={item.id} className="flex gap-6 animate-in fade-in slide-in-from-right-4 duration-500">
                  <div className="w-28 aspect-[3/4] bg-zinc-900 overflow-hidden relative border border-white/5">
                    <img src={item.image} className="w-full h-full object-cover" alt={item.name} />
                  </div>
                  <div className="flex-1 flex flex-col justify-between py-1">
                    <div>
                      <div className="flex justify-between items-start mb-2">
                        <h3 className="text-sm font-black uppercase tracking-tight text-white">{item.name}</h3>
                        <button onClick={() => onRemove(item.id)} className="text-[10px] text-zinc-600 hover:text-white transition-colors">REMOVE</button>
                      </div>
                      <div className="text-[10px] text-[#EC4899] font-black uppercase tracking-widest">SKU-{item.id}</div>
                    </div>
                    <div className="flex justify-between items-end">
                      <div className="flex items-center bg-black border border-white/10 px-4 py-2 gap-6 rounded-lg">
                        <button onClick={() => onUpdateQuantity(item.id, -1)} className="text-lg text-zinc-400 hover:text-white transition-colors">−</button>
                        <span className="text-[11px] font-black font-mono">{item.quantity}</span>
                        <button onClick={() => onUpdateQuantity(item.id, 1)} className="text-lg text-zinc-400 hover:text-white transition-colors">+</button>
                      </div>
                      <div className="text-right">
                        <span className="text-lg font-mono font-black text-white block">${item.price * item.quantity}</span>
                        <span className="text-[9px] font-mono text-[#EC4899]">-${(item.originalPrice - item.price) * item.quantity} SAVED</span>
                      </div>
                    </div>
                  </div>
                </div>
              ))
            )}
          </div>

          {items.length > 0 && (
            <div className="pt-10 border-t border-white/5 space-y-6">
              <div className="flex justify-between items-baseline">
                <span className="text-[10px] uppercase tracking-[0.4em] font-black text-zinc-500">Acquisition Total</span>
                <span className="text-3xl font-serif italic text-white">${subtotal}</span>
              </div>
              <div className="flex justify-between items-center text-[#EC4899] bg-[#EC4899]/5 px-4 py-2 rounded-lg">
                <span className="text-[9px] font-black uppercase tracking-widest">Hype Savings</span>
                <span className="text-sm font-mono font-bold">-${savings}</span>
              </div>
              <button className="w-full py-7 bg-white text-black text-[11px] uppercase tracking-[0.4em] font-black hover:bg-[#EC4899] hover:text-white transition-all shadow-[0_0_40px_rgba(236,72,153,0.3)]">
                Initialize Secure Checkout
              </button>
              <div className="flex items-center justify-center gap-4 opacity-30 grayscale grayscale-100">
                <span className="text-[8px] font-black uppercase">Apple Pay</span>
                <span className="text-[8px] font-black uppercase">Crypto</span>
                <span className="text-[8px] font-black uppercase">Stripe</span>
              </div>
            </div>
          )}
        </div>
      </div>
    </>
  );
};

