import React, { useState } from 'react';

interface GameShowroomProps {
  attemptsRemaining: number;
  onPlay: () => void;
  onWin: (reward: string) => void;
}

const GameShowroom: React.FC<GameShowroomProps> = ({ attemptsRemaining, onPlay, onWin }) => {
  const [activeGame, setActiveGame] = useState<'NONE' | 'RPS' | 'GUESS' | 'SPIN'>('NONE');
  const [gameState, setGameState] = useState<any>(null);

  const startRPS = (choice: string) => {
    if (attemptsRemaining <= 0) return alert("Attempts exhausted for today.");
    onPlay();
    const bot = ['ROCK', 'PAPER', 'SCISSORS'][Math.floor(Math.random() * 3)];
    let result = '';
    if (choice === bot) result = 'TIE';
    else if ((choice === 'ROCK' && bot === 'SCISSORS') || (choice === 'PAPER' && bot === 'ROCK') || (choice === 'SCISSORS' && bot === 'PAPER')) {
      result = 'WIN';
      onWin('50 GEMS');
    } else {
      result = 'LOSE';
    }
    setGameState({ player: choice, bot, result });
  };

  const startGuess = (num: number) => {
    if (attemptsRemaining <= 0) return alert("Attempts exhausted.");
    onPlay();
    const target = Math.floor(Math.random() * 5) + 1;
    if (num === target) {
      setGameState({ result: 'WIN', target });
      onWin('10% OFF VOUCHER');
    } else {
      setGameState({ result: 'LOSE', target });
    }
  };

  const startSpin = () => {
    if (attemptsRemaining <= 0) return alert("Attempts exhausted.");
    onPlay();
    const rewards = ['TRY AGAIN', '10 GEMS', 'LOSE', '100 COINS', 'RARE BADGE'];
    const outcome = rewards[Math.floor(Math.random() * rewards.length)];
    setGameState({ result: outcome });
    if (outcome !== 'LOSE' && outcome !== 'TRY AGAIN') onWin(outcome);
  };

  const reset = () => {
    setActiveGame('NONE');
    setGameState(null);
  };

  return (
    <div className="p-8 space-y-12 animate-in fade-in duration-500 pb-32">
      <div className="text-center space-y-4">
        <h1 className="text-5xl font-serif italic text-white">Arcade <span className="text-[#EC4899] not-italic font-sans font-black">ARENA</span></h1>
        <div className="inline-flex gap-4 glass px-6 py-2 rounded-full border-[#EC4899]/30">
          <span className="text-[10px] font-black uppercase tracking-widest text-[#EC4899]">Daily Passes: {attemptsRemaining}/3</span>
        </div>
      </div>

      {activeGame === 'NONE' ? (
        <div className="grid gap-6">
          {[
            { id: 'RPS', name: 'Cyber RPS', icon: '✊', color: 'from-pink-500 to-purple-600' },
            { id: 'GUESS', name: 'Oracle Number', icon: '🔮', color: 'from-blue-500 to-indigo-600' },
            { id: 'SPIN', name: 'The Wheel of Fate', icon: '🎡', color: 'from-orange-500 to-red-600' }
          ].map(g => (
            <button
              key={g.id}
              onClick={() => setActiveGame(g.id as any)}
              className={`relative overflow-hidden group p-8 rounded-[2rem] bg-gradient-to-br ${g.color} text-left transition-all hover:scale-[1.02] shadow-2xl`}
            >
              <div className="relative z-10 flex justify-between items-center">
                <div>
                  <h3 className="text-2xl font-serif italic text-white">{g.name}</h3>
                  <p className="text-[10px] font-black uppercase tracking-widest text-white/70">Wager 1 Daily Pass</p>
                </div>
                <span className="text-5xl group-hover:rotate-12 transition-transform">{g.icon}</span>
              </div>
              <div className="absolute inset-0 bg-black/10 group-hover:bg-black/0 transition-colors"></div>
            </button>
          ))}
        </div>
      ) : (
        <div className="glass p-10 rounded-[3rem] border-white/10 text-center space-y-8 animate-in zoom-in-95">
          <button onClick={reset} className="absolute top-6 left-6 text-zinc-500 hover:text-white">← BACK</button>

          {activeGame === 'RPS' && !gameState && (
            <div className="space-y-8">
              <h2 className="text-3xl font-serif italic">Choose Your Move</h2>
              <div className="flex justify-center gap-6">
                {['ROCK', 'PAPER', 'SCISSORS'].map(m => (
                  <button onClick={() => startRPS(m)} className="w-20 h-20 rounded-2xl glass text-3xl hover:bg-white hover:text-black transition-all">{m === 'ROCK' ? '✊' : m === 'PAPER' ? '✋' : '✌️'}</button>
                ))}
              </div>
            </div>
          )}

          {activeGame === 'GUESS' && !gameState && (
            <div className="space-y-8">
              <h2 className="text-3xl font-serif italic">Oracle's Number (1-5)</h2>
              <div className="flex justify-center gap-4 flex-wrap">
                {[1,2,3,4,5].map(n => (
                  <button onClick={() => startGuess(n)} className="w-14 h-14 rounded-xl glass text-xl font-black hover:bg-white hover:text-black transition-all">{n}</button>
                ))}
              </div>
            </div>
          )}

          {activeGame === 'SPIN' && !gameState && (
            <div className="space-y-8">
              <h2 className="text-3xl font-serif italic">The Wheel of Fate</h2>
              <div className="relative w-48 h-48 mx-auto border-4 border-[#EC4899] rounded-full flex items-center justify-center animate-spin-slow">
                <span className="text-6xl">🎡</span>
              </div>
              <button onClick={startSpin} className="px-12 py-5 bg-[#EC4899] text-white rounded-2xl font-black uppercase tracking-widest shadow-2xl">SPIN FOR DESTINY</button>
            </div>
          )}

          {gameState && (
            <div className="space-y-6 animate-in zoom-in-90">
              <div className="text-6xl mb-4">{gameState.result === 'WIN' || (typeof gameState.result === 'string' && gameState.result !== 'LOSE') ? '🏆' : '💀'}</div>
              <h2 className="text-4xl font-serif italic uppercase">{gameState.result}</h2>
              <p className="text-zinc-500 text-xs font-black uppercase tracking-widest">
                {activeGame === 'RPS' && `You played ${gameState.player}. Bot played ${gameState.bot}.`}
                {activeGame === 'GUESS' && `The Oracle chose ${gameState.target}.`}
                {activeGame === 'SPIN' && `Fate delivered: ${gameState.result}`}
              </p>
              <button onClick={reset} className="w-full py-5 glass text-white rounded-2xl font-black uppercase tracking-widest">CONTINUE CIRCUIT</button>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default GameShowroom;

