import ProductModal from './components/ProductModal';
import CartDrawer from './components/CartDrawer';
import Lobby from './components/HomeLobby'; // Reusing HomeLobby as Lobby
import FamousProducts from './components/FamousProducts';
import TryOn from './components/TryOn';
import GameShowroom from './components/GameShowroom';
import Profile from './components/Profile'; // (Placeholder below)
import Bundles from './components/Bundles';
import { MOCK_PRODUCTS } from './constants';
import { EXTENDED_PRODUCTS, MOCK_BUNDLES } from './mockData';
import { Product, CartItem, Page, Category, ViewState, UserStats, Bundle } from './types';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.LOBBY);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [timeLeft, setTimeLeft] = useState(300);

  const [stats, setStats] = useState<UserStats>({
    coins: 2500,
    gems: 50,
    xp: 450,
    maxXP: 1000,
    level: 4,
    rank: 'SILVER VANGUARD',
    dailyGameAttempts: 3,
    lastGameReset: new Date().toDateString()
  });

  useEffect(() => {
    const timer = setInterval(() => setTimeLeft(prev => prev > 0 ? prev - 1 : 0), 1000);
    return () => clearInterval(timer);
  }, []);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) return prev.map(i => i.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { ...product, quantity: 1 }];
    });
    setIsCartOpen(true);
  };

  const addBundleToCart = (bundle: Bundle) => {
    bundle.products.forEach(p => addToCart(p));
  };

  const handleGamePlay = () => {
    setStats(prev => ({ ...prev, dailyGameAttempts: prev.dailyGameAttempts - 1 }));
  };

  const handleGameWin = (reward: string) => {
    if (reward.includes('GEMS')) {
      const amt = parseInt(reward);
      setStats(prev => ({ ...prev, gems: prev.gems + amt }));
    }
    // Other rewards logic
    alert(`REWARD SECURED: ${reward}`);
  };

  const renderView = () => {
    switch (currentView) {
      case ViewState.LOBBY:
        return (
          <Lobby 
            products={EXTENDED_PRODUCTS} 
            stats={{...stats, quests: [] as any, selectedPath: null}} 
            onNavigate={(v: any) => setCurrentView(v)} 
            onAddToCart={(pId) => {
              const p = EXTENDED_PRODUCTS.find(x => x.id === pId);
              if (p) addToCart(p);
            }} 
            onCompleteQuest={() => {}}
          />
        );
      case ViewState.FAMOUS:
        return <FamousProducts products={EXTENDED_PRODUCTS} onProductClick={setSelectedProduct} />;
      case ViewState.TRY_ON:
        return <TryOn />;
      case ViewState.BUNDLES:
        return <Bundles bundles={MOCK_BUNDLES} onAddBundle={addBundleToCart} />;
      case ViewState.GAMES:
        return <GameShowroom attemptsRemaining={stats.dailyGameAttempts} onPlay={handleGamePlay} onWin={handleGameWin} />;
      case ViewState.PROFILE:
        return (
          <div className="p-8 space-y-12 pb-32">
            <h1 className="text-5xl font-serif italic text-white">The <span className="text-[#EC4899] not-italic font-sans font-black">DOSSIER</span></h1>
            <div className="glass p-10 rounded-[3rem] border-white/10 space-y-10">
              <div className="flex items-center gap-8">
                <div className="w-24 h-24 rounded-[2rem] bg-gradient-to-tr from-pink-500 to-purple-600 p-1">
                  <div className="w-full h-full bg-black rounded-[1.8rem] flex items-center justify-center text-4xl">👤</div>
                </div>
                <div>
                  <h2 className="text-3xl font-serif italic text-white">Archiver_{stats.level}</h2>
                  <p className="text-[#EC4899] text-[10px] font-black uppercase tracking-widest">{stats.rank}</p>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="glass p-6 rounded-2xl text-center">
                  <span className="text-zinc-500 text-[8px] font-black uppercase block tracking-widest mb-2">Coins</span>
                  <span className="text-2xl font-mono font-black">{stats.coins}</span>
                </div>
                <div className="glass p-6 rounded-2xl text-center">
                  <span className="text-zinc-500 text-[8px] font-black uppercase block tracking-widest mb-2">Gems</span>
                  <span className="text-2xl font-mono font-black">{stats.gems}</span>
                </div>
              </div>
            </div>
            <button 
              onClick={() => setCurrentView(ViewState.BUNDLES)}
              className="w-full py-6 bg-white text-black rounded-2xl font-black uppercase tracking-[0.3em] shadow-3xl"
            >
              Access Special Bundles
            </button>
          </div>
        );
      default:
        return <Lobby products={EXTENDED_PRODUCTS} stats={stats as any} onNavigate={() => {}} onAddToCart={() => {}} onCompleteQuest={() => {}} />;
    }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-[#FAFAFA] pb-24">
      <Header 
        cartCount={cart.reduce((a, b) => a + b.quantity, 0)} 
        onCartOpen={() => setIsCartOpen(true)}
        onNavigate={() => {}}
        currentPage={Page.HOME}
        dropTime={timeLeft}
      />

      <main className="pt-24 min-h-screen">
        {renderView()}
      </main>

      <BottomNav currentView={currentView} onNavigate={setCurrentView} />

      <CartDrawer 
        isOpen={isCartOpen} 
        onClose={() => setIsCartOpen(false)} 
        items={cart}
        onRemove={(id) => setCart(prev => prev.filter(i => i.id !== id))}
        onUpdateQuantity={(id, d) => setCart(prev => prev.map(i => i.id === id ? { ...i, quantity: Math.max(1, i.quantity + d) } : i))}
      />

      {selectedProduct && (
        <ProductModal 
          product={selectedProduct} 
          onClose={() => setSelectedProduct(null)} 
          onAddToCart={addToCart}
        />
      )}
    </div>
  );
};

export default App;

