import React, { useState, useEffect } from 'react';
import { FlashSale } from '../types';

interface FlashSalesProps {
  sales: FlashSale[];
  onAddToCart: (sale: FlashSale) => void;
}

const FlashSales: React.FC<FlashSalesProps> = ({ sales, onAddToCart }) => {
  const [timeLeft, setTimeLeft] = useState<{ [key: string]: number }>({});

  useEffect(() => {
    const timer = setInterval(() => {
      const now = Date.now();
      const updatedTime: { [key: string]: number } = {};
      sales.forEach(s => {
        updatedTime[s.id] = Math.max(0, Math.floor((s.saleEndTime - now) / 1000));
      });
      setTimeLeft(updatedTime);
    }, 1000);
    return () => clearInterval(timer);
  }, [sales]);

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="p-8 space-y-12 animate-in fade-in duration-500 pb-32">
      <header className="flex justify-between items-center">
        <div>
          <h1 className="text-5xl font-serif italic text-white">Thermal <span className="text-[#EC4899] not-italic font-sans font-black">DROPS</span></h1>
          <p className="text-zinc-500 text-[10px] font-black uppercase tracking-[0.3em] mt-4">Unstable price fluctuations. First come, first secure.</p>
        </div>
        <div className="w-12 h-12 rounded-full border border-red-500/30 flex items-center justify-center animate-pulse">
          <span className="text-red-500 text-xl">🔥</span>
        </div>
      </header>

      <div className="grid gap-8">
        {sales.map(sale => (
          <div key={sale.id} className="glass p-8 rounded-[3rem] border-red-500/10 relative overflow-hidden group">
            <div className="absolute top-0 right-0 bg-red-600 text-white px-6 py-2 rounded-bl-3xl text-[10px] font-black uppercase tracking-widest z-10">
              -{sale.discountPercent}% OFF
            </div>

            <div className="flex flex-col md:flex-row gap-8">
              <div className="w-full md:w-1/3 aspect-[3/4] rounded-[2rem] overflow-hidden border border-white/5">
                <img src={sale.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-1000" />
              </div>

              <div className="flex-1 flex flex-col justify-between py-2">
                <div className="space-y-4">
                  <div>
                    <h3 className="text-3xl font-serif italic text-white">{sale.name}</h3>
                    <p className="text-[10px] font-black text-zinc-500 uppercase tracking-widest mt-1">Limited Release Archive</p>
                  </div>

                  <div className="flex items-center gap-6">
                    <div className="text-center bg-zinc-900/50 p-4 rounded-2xl border border-white/5 flex-1">
                      <span className="text-[8px] font-black text-zinc-500 uppercase block tracking-widest mb-1">Evaporates In</span>
                      <span className="text-2xl font-mono font-black text-red-500">{formatTime(timeLeft[sale.id] || 0)}</span>
                    </div>
                    <div className="text-right">
                      <span className="text-[10px] font-black text-zinc-500 uppercase block tracking-widest line-through">${sale.originalPrice}</span>
                      <span className="text-4xl font-mono font-black text-white">${sale.price}</span>
                    </div>
                  </div>
                </div>

                <button 
                  onClick={() => onAddToCart(sale)}
                  disabled={(timeLeft[sale.id] || 0) <= 0}
                  className="w-full py-5 bg-white text-black rounded-2xl font-black text-xs uppercase tracking-[0.3em] hover:bg-red-600 hover:text-white transition-all shadow-2xl disabled:opacity-20 disabled:grayscale mt-8"
                >
                  {(timeLeft[sale.id] || 0) <= 0 ? 'VOIDED' : 'Secure Transaction'}
                </button>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default FlashSales;

