import { PRODUCT_PERFORMANCE_DATA } from '../data/extendedMock';
import { Product } from '../types';

/**
 * Calculates velocity score based on the specific psychological demand formula:
 * ((purchases / total_users) / (initial_stock / hours_to_sold_out)) * 100
 */
export const calculateVelocityScore = (productId: string): number => {
  const stats = PRODUCT_PERFORMANCE_DATA.find(p => p.productId === productId);
  if (!stats) return 0;

  const adoptionRate = stats.totalPurchases / stats.totalSystemUsers;
  const depletionRate = stats.initialStock / stats.hoursToSoldOut;

  // The formula provided: (purchases/users) / (stock/time)
  // We multiply by a factor to get a readable 0-100 score
  const rawScore = (adoptionRate / depletionRate) * 1000;

  return Math.min(100, Math.round(rawScore));
};

export const getHypeRankedProducts = (products: Product[]): Product[] => {
  return products.map(p => ({
    ...p,
    velocityScore: calculateVelocityScore(p.id)
  })).sort((a, b) => b.velocityScore - a.velocityScore);
};

