    { id: ViewState.PROFILE, icon: '👤', label: 'Vault' },
  ];

  return (
    <nav className="fixed bottom-0 left-0 right-0 z-[100] pb-safe px-6 py-4 glass border-t border-white/5 flex justify-around items-center rounded-t-[3rem] shadow-[0_-20px_50px_rgba(0,0,0,0.6)] animate-in slide-in-from-bottom-full duration-700">
      {items.map((item) => {
        const isActive = currentView === item.id;
        return (
          <button
            key={item.id}
            onClick={() => onNavigate(item.id)}
            className={`flex flex-col items-center gap-1.5 transition-all duration-500 relative group ${
              isActive ? 'text-[#EC4899] scale-110' : 'text-zinc-600 hover:text-zinc-300'
            }`}
          >
            <span className={`text-2xl mb-0.5 transition-transform duration-500 ${isActive ? 'translate-y-[-2px]' : ''}`}>
              {item.icon}
            </span>
            <span className={`text-[8px] font-black uppercase tracking-[0.2em] transition-opacity duration-500 ${isActive ? 'opacity-100' : 'opacity-40 group-hover:opacity-70'}`}>
              {item.label}
            </span>

            {/* Active Indicator */}
            {isActive && (
              <div className="absolute -bottom-1 w-1.5 h-1.5 bg-[#EC4899] rounded-full shadow-[0_0_12px_#EC4899] animate-pulse"></div>
            )}
          </button>
        );
      })}
    </nav>
  );
};

