import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import BottomNav from './components/BottomNav';
import ProductDetail from './components/ProductDetail';
import CartDrawer from './components/CartDrawer';
import Lobby from './components/HomeLobby';
import FamousProducts from './components/FamousProducts';
import TryOn from './components/TryOn';
import GameShowroom from './components/GameShowroom';
import Bundles from './components/Bundles';
import StylistAI from './components/StylistAI';
import OutfitBuilder from './components/OutfitBuilder';
import IdentityPaths from './components/IdentityPaths';
import StyleArena from './components/StyleArena';
import Categories from './components/Categories';
import FlashSales from './components/FlashSales';
import Profile from './components/Profile';
import WishlistView from './components/WishlistView';
import { EXTENDED_PRODUCTS, MOCK_BUNDLES, MOCK_FLASH_SALES } from './mockData';
import { getHypeRankedProducts } from './services/metricsService';
import { Product, CartItem, Page, ViewState, UserStats, Bundle, Category } from './types';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.LOBBY);
  const [cart, setCart] = useState<CartItem[]>(() => {
    const saved = localStorage.getItem('closet-craze-cart');
    return saved ? JSON.parse(saved) : [];
  });
  const [wishlist, setWishlist] = useState<string[]>(() => {
    const saved = localStorage.getItem('closet-craze-wishlist');
    return saved ? JSON.parse(saved) : [];
  });
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [selectedCategory, setSelectedCategory] = useState<Category>('All');
  const [timeLeft, setTimeLeft] = useState(300);

  const [stats, setStats] = useState<UserStats>({
    coins: 2500,
    gems: 50,
    dailyGameAttempts: 3,
    lastGameReset: new Date().toDateString(),
    quests: [
      { id: 'q1', title: 'Consult AI Stylist', rewardXP: 100, icon: '✨', completed: false },
      { id: 'q2', title: 'Vote in Arena', rewardXP: 50, icon: '🔥', completed: false },
      { id: 'q3', title: 'Manifest a Look', rewardXP: 150, icon: '🎨', completed: false }
    ],
    selectedPath: 'CYBER'
  });

  useEffect(() => {
    localStorage.setItem('closet-craze-wishlist', JSON.stringify(wishlist));
  }, [wishlist]);

  useEffect(() => {
    localStorage.setItem('closet-craze-cart', JSON.stringify(cart));
  }, [cart]);

  useEffect(() => {
    const timer = setInterval(() => setTimeLeft(prev => prev > 0 ? prev - 1 : 0), 1000);
    return () => clearInterval(timer);
  }, []);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) return prev.map(i => i.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { ...product, quantity: 1 }];
    });
    setIsCartOpen(true);
  };

  const toggleWishlist = (product: Product) => {
    setWishlist(prev => 
      prev.includes(product.id) 
        ? prev.filter(id => id !== product.id) 
        : [...prev, product.id]
    );
  };

  const handleUpdateSynergy = (pathId: string) => {
    if (selectedProduct) {
      setSelectedProduct({ ...selectedProduct, synergyPath: pathId });
    }
  };

  const addBundleToCart = (bundle: Bundle) => {
    bundle.products.forEach(p => addToCart(p));
  };

  const handleGamePlay = () => {
    setStats(prev => ({ ...prev, dailyGameAttempts: Math.max(0, prev.dailyGameAttempts - 1) }));
  };

  const handleGameWin = (reward: string) => {
    if (reward.includes('GEMS')) {
      const amt = parseInt(reward) || 10;
      setStats(prev => ({ ...prev, gems: prev.gems + amt }));
    } else if (reward.includes('COINS')) {
      const amt = parseInt(reward) || 100;
      setStats(prev => ({ ...prev, coins: prev.coins + amt }));
    }
  };

  const rankedProducts = getHypeRankedProducts(EXTENDED_PRODUCTS);
  const filteredProducts = selectedCategory === 'All' 
    ? rankedProducts 
    : rankedProducts.filter(p => p.category === selectedCategory);

  const renderView = () => {
    switch (currentView) {
      case ViewState.LOBBY:
        return (
          <Lobby 
            products={EXTENDED_PRODUCTS} 
            stats={stats} 
            wishlist={wishlist}
            onNavigate={setCurrentView} 
            onAddToCart={(pId) => {
              const p = EXTENDED_PRODUCTS.find(x => x.id === pId);
              if (p) addToCart(p);
            }} 
            onToggleWishlist={toggleWishlist}
            onCompleteQuest={(qId) => {
              setStats(prev => ({
                ...prev,
                quests: prev.quests.map(q => q.id === qId ? { ...q, completed: true } : q)
              }));
            }}
          />
        );
      case ViewState.FAMOUS:
        return (
          <FamousProducts 
            products={filteredProducts} 
            wishlist={wishlist}
            onProductClick={setSelectedProduct} 
            onAddToCart={addToCart}
            onToggleWishlist={toggleWishlist}
          />
        );
      case ViewState.TRY_ON:
        return <TryOn />;
      case ViewState.BUNDLES:
        return <Bundles bundles={MOCK_BUNDLES} onAddBundle={addBundleToCart} />;
      case ViewState.CATEGORIES:
        return <Categories onSelectCategory={setSelectedCategory} onNavigate={setCurrentView} />;
      case ViewState.FLASH:
        return <FlashSales sales={MOCK_FLASH_SALES} onAddToCart={(s) => addToCart(s as Product)} />;
      case ViewState.GAMES:
        return <GameShowroom attemptsRemaining={stats.dailyGameAttempts} onPlay={handleGamePlay} onWin={handleGameWin} />;
      case ViewState.AI_STYLIST:
        return <StylistAI />;
      case ViewState.OUTFIT_BUILDER:
        return <OutfitBuilder products={EXTENDED_PRODUCTS} stats={stats} onNavigate={() => {}} onLockLook={() => alert("Look Locked!")} />;
      case ViewState.PATH_SELECTION:
        return <IdentityPaths currentPath={stats.selectedPath} onSelect={(id) => setStats(prev => ({ ...prev, selectedPath: id }))} />;
      case ViewState.ARENA:
        return <StyleArena onVote={() => {}} onExit={() => setCurrentView(ViewState.LOBBY)} />;
      case ViewState.PROFILE:
        return <Profile stats={stats} onNavigate={setCurrentView} />;
      case ViewState.WISHLIST:
        return (
          <WishlistView 
            products={EXTENDED_PRODUCTS} 
            wishlistIds={wishlist} 
            onAddToCart={addToCart} 
            onToggleWishlist={toggleWishlist} 
            onProductClick={setSelectedProduct} 
          />
        );
      default:
        return <Lobby products={EXTENDED_PRODUCTS} stats={stats} wishlist={wishlist} onNavigate={setCurrentView} onAddToCart={() => {}} onToggleWishlist={() => {}} onCompleteQuest={() => {}} />;
    }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-[#FAFAFA] flex flex-col font-sans">
      <Header 
        cartCount={cart.reduce((a, b) => a + b.quantity, 0)} 
        wishlistCount={wishlist.length}
        stats={stats}
        onCartOpen={() => setIsCartOpen(true)}
        onNavigatePage={(p) => {
          if (p === Page.HOME) setCurrentView(ViewState.LOBBY);
          else setCurrentView(ViewState.FAMOUS);
        }}
        onNavigateView={setCurrentView}
        currentPage={currentView === ViewState.LOBBY ? Page.HOME : Page.SHOP}
        currentView={currentView}
        dropTime={timeLeft}
      />

      <main className="pt-24 flex-1 overflow-x-hidden">
        {renderView()}
      </main>

      <BottomNav currentView={currentView} onNavigate={setCurrentView} />

      <CartDrawer 
        isOpen={isCartOpen} 
        onClose={() => setIsCartOpen(false)} 
        items={cart}
        onRemove={(id) => setCart(prev => prev.filter(i => i.id !== id))}
        onUpdateQuantity={(id, delta) => setCart(prev => prev.map(i => i.id === id ? { ...i, quantity: Math.max(1, i.quantity + delta) } : i))}
      />

      {selectedProduct && (
        <ProductDetail 
          product={selectedProduct} 
          stats={stats}
          onClose={() => setSelectedProduct(null)} 
          onAddToCart={addToCart}
          onUpdateSynergy={handleUpdateSynergy}
          onToggleWishlist={toggleWishlist}
          isInWishlist={wishlist.includes(selectedProduct.id)}
        />
      )}
    </div>
  );
};

export default App;

