import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import BottomNav from './components/BottomNav';
import ProductDetail from './components/ProductDetail';
import CartDrawer from './components/CartDrawer';
import Lobby from './components/HomeLobby';
import FamousProducts from './components/FamousProducts';
import TryOn from './components/TryOn';
import GameShowroom from './components/GameShowroom';
import Bundles from './components/Bundles';
import StylistAI from './components/StylistAI';
import OutfitBuilder from './components/OutfitBuilder';
import StyleArena from './components/StyleArena';
import Categories from './components/Categories';
import FlashSales from './components/FlashSales';
import Profile from './components/Profile';
import WishlistView from './components/WishlistView';
import { EXTENDED_PRODUCTS, MOCK_BUNDLES, MOCK_FLASH_SALES } from './mockData';
import { getHypeRankedProducts } from './services/metricsService';
import { Product, CartItem, Page, ViewState, UserStats, Bundle, Category } from './types';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.LOBBY);
  const [cart, setCart] = useState<CartItem[]>(() => {
    const saved = localStorage.getItem('closet-craze-cart');
    return saved ? JSON.parse(saved) : [];
  });
  const [wishlist, setWishlist] = useState<string[]>(() => {
    const saved = localStorage.getItem('closet-craze-wishlist');
    return saved ? JSON.parse(saved) : [];
  });
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [selectedCategory, setSelectedCategory] = useState<Category>('All');
  const [timeLeft, setTimeLeft] = useState(300);

  const [stats, setStats] = useState<UserStats>({
    coins: 2500,
    gems: 50,
    dailyGameAttempts: 3,
    lastGameReset: new Date().toDateString(),
    quests: [
      { id: 'q1', title: 'Consult AI Stylist', rewardXP: 100, icon: '✨', completed: false },
      { id: 'q2', title: 'Vote in Arena', rewardXP: 50, icon: '🔥', completed: false },
      { id: 'q3', title: 'Manifest a Look', rewardXP: 150, icon: '🎨', completed: false }
    ],
    selectedPath: 'CYBER'
  });

  useEffect(() => {
    localStorage.setItem('closet-craze-wishlist', JSON.stringify(wishlist));
  }, [wishlist]);

  useEffect(() => {
    localStorage.setItem('closet-craze-cart', JSON.stringify(cart));
  }, [cart]);

  useEffect(() => {
    const timer = setInterval(() => setTimeLeft(prev => prev > 0 ? prev - 1 : 0), 1000);
    return () => clearInterval(timer);
  }, []);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) return prev.map(i => i.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { ...product, quantity: 1 }];
    });
    setIsCartOpen(true);
  };

  const toggleWishlist = (product: Product) => {
    setWishlist(prev => 
      prev.includes(product.id) 
        ? prev.filter(id => id !== product.id) 
        : [...prev, product.id]
    );
  };

  const handleUpdateSynergy = (pathId: string) => {
    if (selectedProduct) {
      setSelectedProduct({ ...selectedProduct, synergyPath: pathId });
    }
  };

  const addBundleToCart = (bundle: Bundle) => {
    bundle.products.forEach(p => addToCart(p));
  };

  const handleGamePlay = () => {
    setStats(prev => ({ ...prev, dailyGameAttempts: Math.max(0, prev.dailyGameAttempts - 1) }));
  };

  const handleGameWin = (reward: string) => {
    if (reward.includes('GEMS')) {
      const amt = parseInt(reward) || 10;
      setStats(prev => ({ ...prev, gems: prev.gems + amt }));
    } else if (reward.includes('COINS')) {
      const amt = parseInt(reward) || 100;
      setStats(prev => ({ ...prev, coins: prev.coins + amt }));
    }
  };

  const rankedProducts = getHypeRankedProducts(EXTENDED_PRODUCTS);
  const filteredProducts = selectedCategory === 'All' 
    ? rankedProducts 
    : rankedProducts.filter(p => p.category === selectedCategory);

  const renderView = () => {
    switch (currentView) {
      case ViewState.LOBBY:
        return (
          <Lobby 
            products={EXTENDED_PRODUCTS} 
            stats={stats} 
            wishlist={wishlist}
            onNavigate={setCurrentView} 
            onAddToCart={(pId) => {
              const p = EXTENDED_PRODUCTS.find(x => x.id === pId);
              if (p) addToCart(p);
            }} 
            onToggleWishlist={toggleWishlist}
            onProductClick={setSelectedProduct}
            onCompleteQuest={(qId) => {
              setStats(prev => ({
                ...prev,
                quests: prev.quests.map(q => q.id === qId ? { ...q, completed: true } : q)
              }));
            }}
          />
        );
      case ViewState.FAMOUS:
        return (
          <FamousProducts 
            products={filteredProducts} 
            wishlist={wishlist}
            onProductClick={setSelectedProduct} 
            onAddToCart={addToCart}
            onToggleWishlist={toggleWishlist}
          />
        );
      case ViewState.TRY_ON:
        return <TryOn />;
      case ViewState.BUNDLES:
        return <Bundles bundles={MOCK_BUNDLES} onAddBundle={addBundleToCart} />;
      case ViewState.CATEGORIES:
        return <Categories onSelectCategory={setSelectedCategory} onNavigate={setCurrentView} />;
      case ViewState.FLASH:
        return <FlashSales sales={MOCK_FLASH_SALES} onAddToCart={(s) => addToCart(s as Product)} />;
      case ViewState.GAMES:
        return <GameShowroom attemptsRemaining={stats.dailyGameAttempts} onPlay={handleGamePlay} onWin={handleGameWin} />;
      case ViewState.AI_STYLIST:
        return <StylistAI />;
      case ViewState.OUTFIT_BUILDER:
        return <OutfitBuilder products={EXTENDED_PRODUCTS} stats={stats} onNavigate={() => {}} onLockLook={() => alert("Look Locked!")} />;
      case ViewState.ARENA:
        return <StyleArena onVote={() => {}} onExit={() => setCurrentView(ViewState.LOBBY)} />;
      case ViewState.PROFILE:
        return <Profile stats={stats} onNavigate={setCurrentView} />;
      case ViewState.WISHLIST:
        return (
          <WishlistView 
            products={EXTENDED_PRODUCTS} 
            wishlistIds={wishlist} 
            onAddToCart={addToCart} 
            onToggleWishlist={toggleWishlist} 
            onProductClick={setSelectedProduct} 
          />
        );
      default:
        return <Lobby products={EXTENDED_PRODUCTS} stats={stats} wishlist={wishlist} onNavigate={setCurrentView} onAddToCart={() => {}} onToggleWishlist={() => {}} onProductClick={setSelectedProduct} onCompleteQuest={() => {}} />;
    }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-[#FAFAFA] flex flex-col font-sans">
      <Header 
        cartCount={cart.reduce((a, b) => a + b.quantity, 0)} 
        wishlistCount={wishlist.length}
        stats={stats}
        onCartOpen={() => setIsCartOpen(true)}
        onNavigatePage={(p) => {
          if (p === Page.HOME) setCurrentView(ViewState.LOBBY);
          else setCurrentView(ViewState.FAMOUS);
        }}
        onNavigateView={setCurrentView}
        currentPage={currentView === ViewState.LOBBY ? Page.HOME : Page.SHOP}
        currentView={currentView}
        dropTime={timeLeft}
      />

      <main className="pt-24 flex-1 overflow-x-hidden">
        {renderView()}
      </main>

      <BottomNav currentView={currentView} onNavigate={setCurrentView} />

      <CartDrawer 
        isOpen={isCartOpen} 
        onClose={() => setIsCartOpen(false)} 
        items={cart}
        onRemove={(id) => setCart(prev => prev.filter(i => i.id !== id))}
        onUpdateQuantity={(id, delta) => setCart(prev => prev.map(i => i.id === id ? { ...i, quantity: Math.max(1, i.quantity + delta) } : i))}
      />

      {selectedProduct && (
        <ProductDetail 
          product={selectedProduct} 
          stats={stats}
          onClose={() => setSelectedProduct(null)} 
          onAddToCart={addToCart}
          onUpdateSynergy={handleUpdateSynergy}
          onToggleWishlist={toggleWishlist}
          isInWishlist={wishlist.includes(selectedProduct.id)}
        />
      )}
    </div>
  );
};

export default App;

import React from 'react';
import { Product } from '../types';

interface ProductCardProps {
  product: Product;
  onClick: (product: Product) => void;
  onAddToCart: (product: Product) => void;
  onToggleWishlist: (product: Product) => void;
  isWishlisted: boolean;
}

const ProductCard: React.FC<ProductCardProps> = ({ 
  product, 
  onClick, 
  onAddToCart, 
  onToggleWishlist,
  isWishlisted 
}) => {
  const discountPercent = Math.round(((product.originalPrice - product.price) / product.originalPrice) * 100);

  // Simulated dynamic "watching" count for FOMO
  const watchingCount = Math.floor(product.viewers / 10) + 2;

  return (
    <div className="group relative">
      <div 
        className="relative aspect-[3/4] overflow-hidden bg-zinc-900 mb-6 border border-white/5 cursor-pointer"
        onClick={() => onClick(product)}
      >
        <img 
          src={product.image} 
          alt={product.name} 
          className="w-full h-full object-cover transition-all duration-1000 group-hover:scale-110 group-hover:opacity-40"
        />

        {/* Psychological Trigger: High Discount */}
        {discountPercent > 0 && (
          <div className="absolute top-4 right-4 z-10">
            <div className="bg-[#EC4899] px-3 py-1.5 rounded-full flex items-center gap-1 shadow-[0_0_15px_rgba(236,72,153,0.5)]">
              <span className="text-[10px] font-black uppercase tracking-widest text-white">-{discountPercent}% OFF</span>
            </div>
          </div>
        )}

        {/* Competition Indicator: FOMO */}
        <div className="absolute top-4 left-4 z-10">
          <div className="bg-black/80 backdrop-blur-md px-3 py-1.5 rounded-full flex items-center gap-2 border border-white/10 shadow-lg">
            <div className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse"></div>
            <span className="text-[8px] font-black uppercase tracking-[0.2em] text-white">
              {watchingCount} Watching
            </span>
          </div>
        </div>

        {/* Quick Add Overlay */}
        <div className="absolute inset-0 flex flex-col items-center justify-center translate-y-full group-hover:translate-y-0 transition-all duration-500 p-6 bg-black/40 backdrop-blur-sm">
          <div className="text-[9px] font-black uppercase tracking-[0.3em] text-[#EC4899] mb-5 text-center">Protocol: High Demand Priority</div>

          <div className="flex w-full gap-2">
            <button 
              onClick={(e) => {
                e.stopPropagation();
                onAddToCart(product);
              }}
              className="flex-1 py-4 bg-white text-black text-[9px] uppercase tracking-[0.2em] font-black hover:bg-[#EC4899] hover:text-white transition-all shadow-xl active:scale-95"
            >
              Add to Bag
            </button>
            <button 
              onClick={(e) => {
                e.stopPropagation();
                onToggleWishlist(product);
              }}
              className={`w-12 h-12 flex items-center justify-center rounded-xl border transition-all active:scale-90 ${
                isWishlisted 
                ? 'bg-[#EC4899] border-[#EC4899] text-white shadow-[0_0_20px_rgba(236,72,153,0.4)]' 
                : 'bg-black/50 border-white/20 text-white hover:bg-white hover:text-black'
              }`}
            >
              {isWishlisted ? '💖' : '🤍'}
            </button>
          </div>
        </div>

        {/* Scarcity Badge */}
        {product.stockCount <= 5 && product.stockCount > 0 && (
          <div className="absolute bottom-6 left-6 flex items-center gap-2">
             <div className="px-3 py-1 bg-red-600 text-white text-[8px] font-black uppercase tracking-widest animate-pulse border border-red-500/50 shadow-[0_0_15px_rgba(220,38,38,0.5)]">
               Critical Stock: {product.stockCount} Left
             </div>
          </div>
        )}

        {!product.inStock && (
          <div className="absolute inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center">
            <span className="text-[10px] uppercase tracking-[0.4em] font-black text-white border-y border-white/20 py-4 px-8">Vault Closed</span>
          </div>
        )}
      </div>

      <div className="flex justify-between items-start gap-4" onClick={() => onClick(product)}>
        <div className="flex-1">
          <div className="flex items-center gap-2 mb-1.5">
            <h3 className="text-sm font-black uppercase tracking-tight text-white group-hover:text-[#EC4899] transition-colors">{product.name}</h3>
            {product.isNew && <span className="text-[8px] text-[#EC4899] font-black">NEW</span>}
          </div>

          {/* Enhanced Tag Chips immediately below the name */}
          {product.tags && product.tags.length > 0 && (
            <div className="flex flex-wrap gap-1.5 mb-3">
              {product.tags.map(tag => (
                <span 
                  key={tag} 
                  className="text-[7px] font-black uppercase tracking-[0.2em] bg-white/5 border border-white/10 px-2 py-0.5 rounded text-zinc-400 group-hover:text-zinc-100 group-hover:border-[#EC4899]/30 transition-all"
                >
                  #{tag}
                </span>
              ))}
            </div>
          )}

          <p className="text-[10px] text-zinc-500 font-bold uppercase tracking-widest">{product.category}</p>
        </div>
        <div className="text-right">
          <span className="text-lg font-black font-mono tracking-tighter text-white block">${product.price}</span>
          <span className="text-[10px] font-mono text-zinc-600 line-through">${product.originalPrice}</span>
        </div>
      </div>
    </div>
  );
};

export default ProductCard;

export type Category = 'All' | 'Apparel' | 'Accessories' | 'Home' | 'Beauty';

export interface Product {
  id: string;
  name: string;
  price: number;
  originalPrice: number;
  image: string;
  category: Category;
  description: string;
  details: string[];
  inStock: boolean;
  isNew?: boolean;
  viewers: number;
  stockCount: number;
  hypeScore: number;
  velocityScore: number; // Calculated: (Sales/TotalUsers) / (Stock/TimeToSoldOut)
  synergyPath?: string;
  tags?: string[];
}

export interface Bundle {
  id: string;
  name: string;
  products: Product[];
  bundlePrice: number;
  description: string;
  expiresIn: number; // seconds
}

export interface FlashSale extends Product {
  saleEndTime: number; // timestamp
  discountPercent: number;
}

export interface CartItem extends Product {
  quantity: number;
}

export enum ViewState {
  LOBBY = 'LOBBY',
  FAMOUS = 'FAMOUS',
  TRY_ON = 'TRY_ON',
  CATEGORIES = 'CATEGORIES',
  BUNDLES = 'BUNDLES',
  FLASH = 'FLASH',
  PROFILE = 'PROFILE',
