import BottomNav from './components/BottomNav';
import ProductDetail from './components/ProductDetail';
import CartDrawer from './components/CartDrawer';
import Lobby from './components/HomeLobby';
import FamousProducts from './components/FamousProducts';
import TryOn from './components/TryOn';
import Bundles from './components/Bundles';
import OutfitBuilder from './components/OutfitBuilder';
import Categories from './components/Categories';
import FlashSales from './components/FlashSales';
import Profile from './components/Profile';
import WishlistView from './components/WishlistView';
import CategoryPanel from './components/CategoryPanel';
import SocialProofPopup from './components/SocialProofPopup';
import { EXTENDED_PRODUCTS, MOCK_BUNDLES, MOCK_FLASH_SALES } from './mockData';
import { getHypeRankedProducts } from './services/metricsService';
import { Product, CartItem, Page, ViewState, UserStats, Bundle, Category } from './types';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.LOBBY);
  const [cart, setCart] = useState<CartItem[]>(() => {
    const saved = localStorage.getItem('closet-craze-cart');
    return saved ? JSON.parse(saved) : [];
  });
  const [wishlist, setWishlist] = useState<string[]>(() => {
    const saved = localStorage.getItem('closet-craze-wishlist');
    return saved ? JSON.parse(saved) : [];
  });
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isCategoryPanelOpen, setIsCategoryPanelOpen] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [selectedCategory, setSelectedCategory] = useState<Category>('All');
  const [timeLeft, setTimeLeft] = useState(300);

  const [stats, setStats] = useState<UserStats>({
    dailyGameAttempts: 0,
    lastGameReset: new Date().toDateString(),
    quests: [
      { id: 'q1', title: 'Analyze Velocity Heat', rewardXP: 100, icon: '🔥', completed: false },
      { id: 'q2', title: 'Refine Identity', rewardXP: 150, icon: '🎨', completed: false }
    ],
    selectedPath: 'CYBER'
  });

  useEffect(() => {
    localStorage.setItem('closet-craze-wishlist', JSON.stringify(wishlist));
  }, [wishlist]);

  useEffect(() => {
    localStorage.setItem('closet-craze-cart', JSON.stringify(cart));
  }, [cart]);

  useEffect(() => {
    const timer = setInterval(() => setTimeLeft(prev => prev > 0 ? prev - 1 : 0), 1000);
    return () => clearInterval(timer);
  }, []);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) return prev.map(i => i.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { ...product, quantity: 1 }];
    });
    setIsCartOpen(true);
  };

  const toggleWishlist = (product: Product) => {
    setWishlist(prev => 
      prev.includes(product.id) 
        ? prev.filter(id => id !== product.id) 
        : [...prev, product.id]
    );
  };

  const handleUpdateSynergy = (pathId: string) => {
    if (selectedProduct) {
      setSelectedProduct({ ...selectedProduct, synergyPath: pathId });
    }
  };

  const addBundleToCart = (bundle: Bundle) => {
    bundle.products.forEach(p => addToCart(p));
  };

  const rankedProducts = getHypeRankedProducts(EXTENDED_PRODUCTS);
  const filteredProducts = selectedCategory === 'All' 
    ? rankedProducts 
    : rankedProducts.filter(p => p.category === selectedCategory);

  const renderView = () => {
    switch (currentView) {
      case ViewState.LOBBY:
        return (
          <Lobby 
            products={EXTENDED_PRODUCTS} 
            stats={stats} 
            wishlist={wishlist}
            onNavigate={setCurrentView} 
            onAddToCart={(pId) => {
              const p = EXTENDED_PRODUCTS.find(x => x.id === pId);
              if (p) addToCart(p);
            }} 
            onToggleWishlist={toggleWishlist}
            onProductClick={setSelectedProduct}
            onCompleteQuest={(qId) => {
              setStats(prev => ({
                ...prev,
                quests: prev.quests.map(q => q.id === qId ? { ...q, completed: true } : q)
              }));
            }}
          />
        );
      case ViewState.FAMOUS:
        return (
          <FamousProducts 
            products={filteredProducts} 
            wishlist={wishlist}
            onProductClick={setSelectedProduct} 
            onAddToCart={addToCart}
            onToggleWishlist={toggleWishlist}
          />
        );
      case ViewState.TRY_ON:
        return <TryOn />;
      case ViewState.BUNDLES:
        return <Bundles bundles={MOCK_BUNDLES} onAddBundle={addBundleToCart} />;
      case ViewState.CATEGORIES:
        return <Categories onSelectCategory={setSelectedCategory} onNavigate={setCurrentView} />;
      case ViewState.FLASH:
        return <FlashSales onAddToCart={(s) => addToCart(s as Product)} />;
      case ViewState.OUTFIT_BUILDER:
        return <OutfitBuilder products={EXTENDED_PRODUCTS} stats={stats} onNavigate={() => {}} onLockLook={() => alert("Look Locked!")} />;
      case ViewState.PROFILE:
        return <Profile stats={stats} onNavigate={setCurrentView} />;
      case ViewState.WISHLIST:
        return (
          <WishlistView 
            products={EXTENDED_PRODUCTS} 
            wishlistIds={wishlist} 
            onAddToCart={addToCart} 
            onToggleWishlist={toggleWishlist} 
            onProductClick={setSelectedProduct} 
          />
        );
      default:
        return <Lobby products={EXTENDED_PRODUCTS} stats={stats} wishlist={wishlist} onNavigate={setCurrentView} onAddToCart={() => {}} onToggleWishlist={() => {}} onProductClick={setSelectedProduct} onCompleteQuest={() => {}} />;
    }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-[#FAFAFA] flex flex-col font-sans">
      <Header 
        cartCount={cart.reduce((a, b) => a + b.quantity, 0)} 
        wishlistCount={wishlist.length}
        stats={stats}
        onCartOpen={() => setIsCartOpen(true)}
        onNavigatePage={(p) => {
          if (p === Page.HOME) setCurrentView(ViewState.LOBBY);
          else setCurrentView(ViewState.FAMOUS);
        }}
        onNavigateView={setCurrentView}
        currentPage={currentView === ViewState.LOBBY ? Page.HOME : Page.SHOP}
        currentView={currentView}
        dropTime={timeLeft}
        onOpenCategories={() => setIsCategoryPanelOpen(true)}
      />

      <main className="pt-24 flex-1 overflow-x-hidden">
        {renderView()}
      </main>

      <BottomNav currentView={currentView} onNavigate={setCurrentView} />

      <CartDrawer 
        isOpen={isCartOpen} 
        onClose={() => setIsCartOpen(false)} 
        items={cart}
        onRemove={(id) => setCart(prev => prev.filter(i => i.id !== id))}
        onUpdateQuantity={(id, delta) => setCart(prev => prev.map(i => i.id === id ? { ...i, quantity: Math.max(1, i.quantity + delta) } : i))}
      />

      <CategoryPanel 
        isOpen={isCategoryPanelOpen}
        onClose={() => setIsCategoryPanelOpen(false)}
        onSelectCategory={setSelectedCategory}
        onNavigate={setCurrentView}
        activeCategory={selectedCategory}
      />

      <SocialProofPopup />

      {selectedProduct && (
        <ProductDetail 
          product={selectedProduct} 
          stats={stats}
          onClose={() => setSelectedProduct(null)} 
          onAddToCart={addToCart}
          onUpdateSynergy={handleUpdateSynergy}
          onToggleWishlist={toggleWishlist}
          isInWishlist={wishlist.includes(selectedProduct.id)}
        />
      )}
    </div>
  );
};

export default App;

import React from 'react';
import { ViewState, UserStats, Page } from '../types';

interface HeaderProps {
  cartCount: number;
  wishlistCount: number;
  stats: UserStats;
  onCartOpen: () => void;
  onNavigatePage: (page: Page) => void;
  onNavigateView: (view: ViewState) => void;
  currentPage: Page;
  currentView: ViewState;
  dropTime: number;
  onOpenCategories?: () => void;
}

const Header: React.FC<HeaderProps> = ({ 
  cartCount, 
  wishlistCount,
  onCartOpen,
  onNavigateView, 
  currentView,
  dropTime,
  onOpenCategories
}) => {
  const minutes = Math.floor(dropTime / 60);
  const seconds = dropTime % 60;

  const navItems = [
    { label: 'Heat', view: ViewState.FAMOUS },
    { label: 'Synergy Kits', view: ViewState.BUNDLES, highlight: true },
  ];

  return (
    <nav className="fixed top-0 left-0 right-0 glass z-50 border-b border-white/5">
      <div className="h-20 px-6 md:px-10 flex items-center justify-between">
        {/* Left: Identity & Desktop Nav */}
        <div className="flex items-center gap-8">
          <button 
            onClick={onOpenCategories}
            className="w-10 h-10 flex flex-col items-center justify-center gap-1.5 glass rounded-xl border-white/10 hover:bg-white/5 transition-all group active:scale-95"
          >
            <div className="w-5 h-0.5 bg-white group-hover:bg-[#EC4899] transition-colors"></div>
            <div className="w-5 h-0.5 bg-white group-hover:bg-[#EC4899] transition-colors"></div>
            <div className="w-3 h-0.5 bg-white group-hover:bg-[#EC4899] self-start ml-2.5 transition-colors"></div>
          </button>

          <div 
            className="flex flex-col cursor-pointer group"
            onClick={() => onNavigateView(ViewState.LOBBY)}
          >
            <div className="text-xl font-serif italic tracking-tighter leading-none text-white">
              CLOSET<span className="text-[#EC4899] font-sans font-black not-italic ml-0.5 glow-text">CRAZE</span>
            </div>
            <div className="text-[8px] font-black uppercase tracking-[0.3em] text-zinc-500 mt-1">New Tokyo // V.2.5</div>
          </div>

          {/* Navigation Links */}
          <div className="hidden md:flex items-center gap-6 ml-4">
            {navItems.map((item) => (
              <button
                key={item.view}
                onClick={() => onNavigateView(item.view)}
                className={`text-[10px] font-black uppercase tracking-[0.2em] transition-all relative py-2 ${
                  currentView === item.view 
                    ? 'text-white' 
                    : 'text-zinc-500 hover:text-zinc-300'
                } ${item.highlight ? 'bg-white/5 px-4 rounded-full border border-white/10' : ''}`}
              >
                {item.label}
                {currentView === item.view && !item.highlight && (
                  <span className="absolute bottom-0 left-0 w-full h-0.5 bg-[#EC4899] shadow-[0_0_10px_#EC4899]"></span>
                )}
              </button>
            ))}
          </div>
        </div>

        {/* Center: Drop Timer */}
        <div className="hidden lg:flex flex-col items-center">
          <span className="text-[8px] font-black text-pink-500 uppercase tracking-widest mb-1">Thermal Drop Window</span>
          <span className="text-sm font-mono font-bold text-white leading-none">
            {minutes}:{seconds.toString().padStart(2, '0')}
          </span>
        </div>

        {/* Right: Actions */}
        <div className="flex items-center gap-3">
          {/* Wishlist Button */}
          <button 
            onClick={() => onNavigateView(ViewState.WISHLIST)}
            className={`relative flex items-center justify-center w-10 h-10 rounded-full border transition-all group ${
              currentView === ViewState.WISHLIST ? 'bg-white text-black border-white' : 'bg-transparent border-white/10 text-zinc-500 hover:text-white'
            }`}
          >
            <span className="text-lg">💖</span>
            {wishlistCount > 0 && (
              <span className="absolute -top-1 -right-1 w-4 h-4 bg-[#EC4899] rounded-full text-[8px] font-black flex items-center justify-center text-white border border-black shadow-[0_0_8px_#EC4899]">
                {wishlistCount}
              </span>
            )}
          </button>

          {/* Profile Button */}
          <button 
            onClick={() => onNavigateView(ViewState.PROFILE)}
            className={`hidden sm:flex w-10 h-10 rounded-full items-center justify-center text-lg border transition-all ${
              currentView === ViewState.PROFILE ? 'bg-white text-black border-white' : 'bg-transparent border-white/10 text-zinc-500 hover:text-white'
            }`}
          >
            👤
          </button>

          {/* Cart Button */}
          <button 
            onClick={onCartOpen}
            className="group relative flex items-center gap-3 bg-white text-black px-5 py-2.5 rounded-full hover:bg-[#EC4899] hover:text-white transition-all shadow-xl active:scale-95"
          >
            <span className="text-sm">🛍️</span>
            <span className="text-[10px] font-black uppercase tracking-widest">{cartCount}</span>
            {cartCount > 0 && (
              <span className="absolute -top-1 -right-1 w-4 h-4 bg-red-500 rounded-full text-[8px] font-black flex items-center justify-center text-white animate-bounce border-2 border-black">
                !
              </span>
            )}
          </button>
        </div>
      </div>
    </nav>
  );
};

export default Header;

