  {
    question: "Choose your environment",
    options: [
      { id: '1', label: 'Neon Tokyo', archetype: 'CYBER', img: 'https://images.unsplash.com/photo-1542641728-6ca359b085f4?auto=format&fit=crop&q=80&w=800' },
