      { id: '5', label: 'Sculpted Silk', archetype: 'LUXE', img: 'https://images.unsplash.com/photo-1595777457583-95e059d581b8?auto=format&fit=crop&q=80&w=800' },
      { id: '6', label: 'Liquid Chrome', archetype: 'VOID', img: 'https://images.unsplash.com/photo-1543163521-1bf539c55dd2?auto=format&fit=crop&q=80&w=800' },
