interface LandingScreenProps {
  onComplete: (archetype: string) => void;
}

const LandingScreen: React.FC<LandingScreenProps> = ({ onComplete }) => {
  const [step, setStep] = useState<'START' | 'AUTH' | 'QUIZ' | 'REVEAL'>('START');
  const [authMode, setAuthMode] = useState<'LOGIN' | 'SIGNUP'>('LOGIN');
  const [currentQuizIndex, setCurrentQuizIndex] = useState(0);
  const [selectedArchetype, setSelectedArchetype] = useState<string>('');

  const handleOptionSelect = (archetype: string) => {
    setSelectedArchetype(archetype);
    if (currentQuizIndex < QUIZ_STEPS.length - 1) {
      setCurrentQuizIndex(prev => prev + 1);
    } else {
      setStep('REVEAL');
    }
  };

  const handleAuthSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    // Simulate auth success
    setStep('QUIZ');
  };

  if (step === 'START') {
    return (
      <div className="fixed inset-0 z-[100] bg-black flex flex-col items-center justify-center p-6 text-center">
        <div className="absolute inset-0 opacity-60">
           <img src="https://images.unsplash.com/photo-1483985988355-763728e1935b?auto=format&fit=crop&q=80&w=2000" className="w-full h-full object-cover" alt="Fashion Background" />
           <div className="absolute inset-0 bg-gradient-to-t from-black via-black/80 to-transparent"></div>
        </div>
        <div className="relative z-10 space-y-12 animate-in fade-in zoom-in-95 duration-1000">
          <div className="flex flex-col items-center">
            <div className="text-[10px] font-black uppercase tracking-[0.5em] text-pink-500 mb-6 border border-pink-500/30 px-4 py-1 rounded-full bg-black/50">Access Protocol Required</div>
            <h1 className="text-6xl md:text-9xl font-serif italic text-white leading-none tracking-tighter mb-4">
              CLOSET<br/><span className="not-italic font-sans font-black text-white glow-text uppercase">CRAZE</span>
            </h1>
          </div>

          <button 
            onClick={() => setStep('AUTH')}
            className="group relative px-16 py-8 bg-white text-black rounded-full font-black uppercase tracking-[0.4em] text-sm hover:bg-pink-500 hover:text-white transition-all shadow-3xl active:scale-95 overflow-hidden"
          >
            <span className="relative z-10">Enter Circuit</span>
            <div className="absolute inset-0 bg-pink-500 translate-y-full group-hover:translate-y-0 transition-transform duration-300"></div>
          </button>

          <p className="text-zinc-500 text-[10px] font-black uppercase tracking-[0.3em] max-w-xs mx-auto leading-relaxed opacity-60">
            Secure high-tier silhouettes through gamified acquisition. Auth status: Unauthorized.
          </p>
        </div>
      </div>
    );
  }

  if (step === 'AUTH') {
    return (
      <div className="fixed inset-0 z-[100] bg-[#050505] flex flex-col items-center justify-center p-6">
        <div className="w-full max-w-md space-y-12 animate-in fade-in slide-in-from-bottom-8 duration-700">
          <div className="text-center space-y-4">
            <h2 className="text-4xl font-serif italic text-white">{authMode === 'LOGIN' ? 'Welcome Back' : 'Initialize Identity'}</h2>
            <p className="text-zinc-500 text-[10px] font-black uppercase tracking-widest">Authorized Access Only</p>
          </div>

          <form onSubmit={handleAuthSubmit} className="space-y-6">
            <div className="space-y-4">
              <input 
                type="email" 
                required
                placeholder="EMAIL_ADDRESS"
                className="w-full bg-zinc-900 border border-white/5 px-6 py-5 rounded-2xl text-xs font-black focus:outline-none focus:border-pink-500 transition-colors uppercase tracking-widest text-white"
              />
              <input 
                type="password" 
                required
                placeholder="IDENTITY_PHRASE"
                className="w-full bg-zinc-900 border border-white/5 px-6 py-5 rounded-2xl text-xs font-black focus:outline-none focus:border-pink-500 transition-colors uppercase tracking-widest text-white"
              />
            </div>

            <button 
              type="submit"
              className="w-full py-6 bg-white text-black rounded-2xl font-black uppercase tracking-[0.3em] text-[10px] hover:bg-pink-500 hover:text-white transition-all shadow-2xl active:scale-95"
            >
              {authMode === 'LOGIN' ? 'Verify Identity' : 'Create Archive'}
            </button>
          </form>

          <div className="text-center">
            <button 
              onClick={() => setAuthMode(authMode === 'LOGIN' ? 'SIGNUP' : 'LOGIN')}
              className="text-zinc-500 hover:text-white text-[9px] font-black uppercase tracking-widest transition-colors border-b border-zinc-800 pb-1"
            >
              {authMode === 'LOGIN' ? "Don't have an archive? Create one" : "Already have an identity? Login"}
            </button>
          </div>
        </div>
      </div>
    );
  }

  if (step === 'QUIZ') {
    const currentStep = QUIZ_STEPS[currentQuizIndex];
    const progress = ((currentQuizIndex + 1) / QUIZ_STEPS.length) * 100;

    return (
      <div className="fixed inset-0 z-[100] bg-zinc-950 flex flex-col items-center justify-center p-6">
        <div className="w-full max-w-4xl space-y-12 animate-in fade-in duration-500">
          <div className="space-y-4 text-center">
            <div className="w-full h-1 bg-zinc-900 rounded-full overflow-hidden">
               <div className="h-full bg-pink-500 transition-all duration-500" style={{ width: `${progress}%` }}></div>
            </div>
            <div className="text-[10px] font-black text-zinc-600 uppercase tracking-widest">{Math.floor(progress)}% Archetype Analysis</div>
            <h2 className="text-4xl font-serif italic text-white">{currentStep.question}</h2>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {currentStep.options.map((opt) => (
              <div 
                key={opt.id}
                onClick={() => handleOptionSelect(opt.archetype)}
                className="group relative aspect-[3/4] rounded-3xl overflow-hidden cursor-pointer border-2 border-transparent hover:border-pink-500 transition-all hover:scale-[1.02]"
              >
                <img src={opt.img} className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-700" alt={opt.label} />
                <div className="absolute inset-0 bg-gradient-to-t from-black to-transparent opacity-80"></div>
                <div className="absolute bottom-6 left-6">
                   <div className="text-xs font-black text-white uppercase tracking-widest">{opt.label}</div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    );
  }

  if (step === 'REVEAL') {
    const names: Record<string, string> = {
      'CYBER': 'The Style Vanguard',
      'LUXE': 'The Ethereal Heir',
      'VOID': 'The Void Minimalist'
    };
    const desc: Record<string, string> = {
      'CYBER': 'You command attention through tactical neon and technical silhouettes.',
      'LUXE': 'You dress to signal status without whispering a single word.',
      'VOID': 'Your presence is felt through the absence of noise and the power of form.'
    };

    return (
      <div className="fixed inset-0 z-[100] bg-black flex flex-col items-center justify-center p-6 text-center animate-in fade-in duration-1000">
        <div className="absolute inset-0 overflow-hidden">
           <div className="absolute inset-0 bg-gradient-to-b from-pink-500/20 via-transparent to-black"></div>
           <div className="w-full h-full bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-zinc-800 to-black opacity-40"></div>
        </div>

        <div className="relative z-10 space-y-12 max-w-xl">
           <div className="flex flex-col items-center space-y-4">
              <div className="text-6xl animate-bounce">✨</div>
              <div className="text-[10px] font-black text-pink-500 uppercase tracking-[0.5em]">Archetype Detected</div>
           </div>

           <div className="space-y-4 animate-in slide-in-from-bottom-8 duration-1000">
              <h2 className="text-6xl md:text-7xl font-serif italic text-white leading-tight">{names[selectedArchetype]}</h2>
              <p className="text-zinc-500 text-sm md:text-lg font-medium uppercase tracking-tight leading-relaxed px-10">
                "{desc[selectedArchetype]}"
              </p>
           </div>

           <button 
             onClick={() => onComplete(selectedArchetype)}
             className="px-12 py-5 bg-white text-black rounded-2xl font-black uppercase tracking-widest text-xs hover:bg-pink-500 hover:text-white transition-all shadow-3xl shadow-pink-500/20 active:scale-95"
           >
             Enter Closet Craze
           </button>
        </div>
      </div>
    );
  }

  return null;
};

