              <span className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-500">🔍</span>
              <input 
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Search products..."
