    if (editingProduct) {
      // Update existing
      setLocalProducts(prev => prev.map(p => p.id === editingProduct.id ? { ...p, ...formData } : p));
    } else {
      // Create new
      const newProduct: Product = {
        ...formData as Product,
        id: (localProducts.length + 1).toString(),
        inStock: (formData.stockCount || 0) > 0,
        viewers: 0,
        velocityScore: formData.velocityScore || 50,
        hypeScore: formData.hypeScore || 50
      };
      setLocalProducts(prev => [newProduct, ...prev]);
    }
    setIsEditorOpen(false);
  };

