            >
              JSON Dump
            </button>
            <button 
              onClick={downloadCSV}
              className="px-6 py-2 bg-[#EC4899] text-white rounded-xl text-[8px] font-black uppercase tracking-widest hover:bg-white hover:text-[#EC4899] transition-all shadow-[0_0_15px_rgba(236,72,153,0.3)]"
