    setAchievements(prev => prev.map(ach => {
      if (ach.id === id) {
        const newProgress = Math.max(ach.progress, progress);
        const unlocked = newProgress >= ach.goal;
        return { ...ach, progress: newProgress, unlocked };
      }
      return ach;
    }));
  };

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) return prev.map(i => i.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { ...product, quantity: 1 }];
    });

    if (product.velocityScore > 90) {
      const highHeatCount = cart.filter(i => i.velocityScore > 90).length + 1;
      updateAchievementProgress('a2', highHeatCount);
    }

    setIsCartOpen(true);
  };

  const toggleWishlist = (product: Product) => {
    setWishlist(prev => 
      prev.includes(product.id) 
        ? prev.filter(id => id !== product.id) 
        : [...prev, product.id]
    );
  };

  const addBundleToCart = (bundle: Bundle) => {
    bundle.products.forEach(p => addToCart(p));
    const currentBundles = achievements.find(a => a.id === 'a3')?.progress || 0;
    updateAchievementProgress('a3', currentBundles + 1);
  };

  const handleOnboardingComplete = (archetype: string) => {
    setStats(prev => ({ ...prev, selectedPath: archetype }));
    setIsAuthenticated(true);
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    localStorage.removeItem('closet-craze-auth');
    setCurrentView(ViewState.LOBBY);
  };

  const handleCheckoutComplete = (details: any) => {
    setCart([]);
    setCurrentView(ViewState.LOBBY);
  };

  const rankedProducts = getHypeRankedProducts(EXTENDED_PRODUCTS);
  const filteredProducts = selectedCategory === 'All' 
    ? rankedProducts 
    : rankedProducts.filter(p => p.category === selectedCategory);

  const renderView = () => {
    switch (currentView) {
      case ViewState.LOBBY:
        return (
          <Lobby 
            products={EXTENDED_PRODUCTS} 
            stats={stats} 
            wishlist={wishlist}
            onNavigate={setCurrentView} 
            onAddToCart={(pId) => {
              const p = EXTENDED_PRODUCTS.find(x => x.id === pId);
              if (p) addToCart(p);
            }} 
            onToggleWishlist={toggleWishlist}
            onProductClick={setSelectedProduct}
            onCompleteQuest={(qId) => {
              setStats(prev => ({
                ...prev,
                quests: prev.quests.map(q => q.id === qId ? { ...q, completed: true } : q)
              }));
            }}
          />
        );
      case ViewState.FAMOUS:
        return (
          <FamousProducts 
            products={filteredProducts} 
            wishlist={wishlist}
            onProductClick={setSelectedProduct} 
            onAddToCart={addToCart}
            onToggleWishlist={toggleWishlist}
          />
        );
      case ViewState.TRY_ON:
        return <TryOn />;
      case ViewState.BUNDLES:
        return <Bundles bundles={MOCK_BUNDLES} onAddBundle={addBundleToCart} />;
      case ViewState.CATEGORIES:
        return <Categories onSelectCategory={setSelectedCategory} onNavigate={setCurrentView} />;
      case ViewState.FLASH:
        return <FlashSales onAddToCart={(s) => addToCart(s as Product)} />;
      case ViewState.OUTFIT_BUILDER:
        return <OutfitBuilder products={EXTENDED_PRODUCTS} stats={stats} onNavigate={() => {}} onLockLook={() => alert("Look Locked!")} />;
      case ViewState.PROFILE:
        return <Profile stats={stats} onNavigate={setCurrentView} onLogout={handleLogout} />;
      case ViewState.WISHLIST:
        return (
          <WishlistView 
            products={EXTENDED_PRODUCTS} 
            wishlistIds={wishlist} 
            onAddToCart={addToCart} 
            onToggleWishlist={toggleWishlist} 
            onProductClick={setSelectedProduct} 
          />
        );
      case ViewState.ADMIN_LOGIN:
        return <AdminLogin onSuccess={() => setCurrentView(ViewState.ADMIN)} onCancel={() => setCurrentView(ViewState.LOBBY)} />;
      case ViewState.ADMIN:
        return <AdminPanel onExit={() => setCurrentView(ViewState.LOBBY)} onNavigate={setCurrentView} />;
      case ViewState.CHECKOUT:
        return <CheckoutView items={cart} onComplete={handleCheckoutComplete} onCancel={() => setCurrentView(ViewState.LOBBY)} balances={balances} />;
      default:
        return <Lobby products={EXTENDED_PRODUCTS} stats={stats} wishlist={wishlist} onNavigate={setCurrentView} onAddToCart={() => {}} onToggleWishlist={() => {}} onProductClick={setSelectedProduct} onCompleteQuest={() => {}} />;
    }
  };

  if (currentView === ViewState.ADMIN_LOGIN) {
    return <AdminLogin onSuccess={() => setCurrentView(ViewState.ADMIN)} onCancel={() => setCurrentView(ViewState.LOBBY)} />;
  }

  if (currentView === ViewState.ADMIN) {
    return <AdminPanel onExit={() => setCurrentView(ViewState.LOBBY)} onNavigate={setCurrentView} />;
  }

  if (currentView === ViewState.CHECKOUT) {
    return <CheckoutView items={cart} onComplete={handleCheckoutComplete} onCancel={() => setCurrentView(ViewState.LOBBY)} balances={balances} />;
  }

  if (!isAuthenticated) {
    return <LandingScreen 
      onComplete={handleOnboardingComplete} 
      onAdminAccess={() => setCurrentView(ViewState.ADMIN_LOGIN)}
    />;
  }

  return (
    <div className="min-h-screen bg-[#050505] text-[#FAFAFA] flex flex-col font-sans">
      <Header 
        cartCount={cart.reduce((a, b) => a + b.quantity, 0)} 
        wishlistCount={wishlist.length}
        stats={stats}
        onCartOpen={() => setIsCartOpen(true)}
        onNavigatePage={(p) => {
          if (p === Page.HOME) setCurrentView(ViewState.LOBBY);
          else setCurrentView(ViewState.FAMOUS);
        }}
        onNavigateView={setCurrentView}
        currentPage={currentView === ViewState.LOBBY ? Page.HOME : Page.SHOP}
        currentView={currentView}
        dropTime={timeLeft}
        onOpenCategories={() => setIsCategoryPanelOpen(true)}
      />

      <main className="pt-24 flex-1 overflow-x-hidden">
        {renderView()}
      </main>

      <BottomNav 
        currentView={currentView} 
        onNavigate={setCurrentView} 
        onOpenCategories={() => setIsCategoryPanelOpen(true)}
      />

      <CartDrawer 
        isOpen={isCartOpen} 
        onClose={() => setIsCartOpen(false)} 
        items={cart}
        onRemove={(id) => setCart(prev => prev.filter(i => i.id !== id))}
        onUpdateQuantity={(id, delta) => setCart(prev => prev.map(i => i.id === id ? { ...i, quantity: Math.max(1, i.quantity + delta) } : i))}
        onNavigate={setCurrentView}
      />

      <CategoryPanel 
        isOpen={isCategoryPanelOpen}
        onClose={() => setIsCategoryPanelOpen(false)}
        onSelectCategory={setSelectedCategory}
        onNavigate={setCurrentView}
        activeCategory={selectedCategory}
        products={EXTENDED_PRODUCTS}
        onProductSelect={setSelectedProduct}
      />

      <SocialProofPopup />

      {selectedProduct && (
        <ProductDetail 
          product={selectedProduct} 
          stats={stats}
          onClose={() => setSelectedProduct(null)} 
          onAddToCart={addToCart}
          onUpdateSynergy={() => {}}
          onToggleWishlist={toggleWishlist}
          isInWishlist={wishlist.includes(selectedProduct.id)}
        />
      )}
    </div>
  );
};

