import React, { useState, useEffect } from 'react';

interface AdminLoginProps {
  onSuccess: (role: 'ADMIN' | 'SUPPLIER') => void;
  onCancel: () => void;
}

const AdminLogin: React.FC<AdminLoginProps> = ({ onSuccess, onCancel }) => {
  const [loginType, setLoginType] = useState<'ADMIN' | 'SUPPLIER'>('ADMIN');
  const [credentials, setCredentials] = useState({ username: '', password: '' });
  const [status, setStatus] = useState<'IDLE' | 'AUTHENTICATING' | 'SUCCESS' | 'ERROR'>('IDLE');
  const [authProgress, setAuthProgress] = useState(0);
  const [errorMessage, setErrorMessage] = useState('');

  useEffect(() => {
    let interval: any;
    if (status === 'AUTHENTICATING') {
      interval = setInterval(() => {
        setAuthProgress(prev => {
          if (prev >= 100) {
            clearInterval(interval);
            handleFinalAuth();
            return 100;
          }
          return prev + Math.random() * 15;
        });
      }, 150);
    }
    return () => clearInterval(interval);
  }, [status]);

  const handleFinalAuth = () => {
    const isAdmin = loginType === 'ADMIN' && 
                    credentials.username.toUpperCase() === 'ROOT' && 
                    credentials.password === 'OVERRIDE_2025';

    const isSupplier = loginType === 'SUPPLIER' && 
                       credentials.username.toUpperCase() === 'SUPPLIER' && 
                       credentials.password === 'NODE_2025';

    if (isAdmin || isSupplier) {
      setStatus('SUCCESS');
      setTimeout(() => onSuccess(loginType), 1000);
    } else {
      setStatus('ERROR');
      setErrorMessage('INVALID_HANDSHAKE_ACCESS_DENIED');
      setAuthProgress(0);
      setTimeout(() => setStatus('IDLE'), 2000);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (status !== 'IDLE') return;
    setStatus('AUTHENTICATING');
    setAuthProgress(0);
  };

  const themeColor = loginType === 'ADMIN' ? '#00ff41' : '#f59e0b'; // Green vs Amber

  return (
    <div className="fixed inset-0 z-[500] bg-black text-[#00ff41] font-mono flex items-center justify-center p-6 overflow-hidden">
      <div className="absolute inset-0 opacity-[0.05] pointer-events-none bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')]"></div>

      {/* Dynamic HUD decorations */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none opacity-20" style={{ color: themeColor }}>
         <div className="absolute top-10 left-10 text-[10px] space-y-1">
            <p>SYSLOG: {loginType === 'ADMIN' ? 'CRITICAL_OVERRIDE_DETECTED' : 'SUPPLIER_NODE_UPLINK'}</p>
            <p>NODE_ID: {loginType === 'ADMIN' ? 'NT_CORE_ALPHA_9' : 'SUP_SHIPPING_X7'}</p>
         </div>
         <div className="absolute bottom-10 right-10 text-[10px] text-right">
            <p>AUTH_PROTOCOL: {loginType === 'ADMIN' ? 'V_SECURE_9.4' : 'L_LOGISTICS_3.0'}</p>
            <p>ENCRYPTION: AES_256_STABLE</p>
         </div>
      </div>

      <div className={`w-full max-w-lg space-y-10 transition-all duration-500 ${status === 'ERROR' ? 'animate-shake' : ''}`}>

        {/* Login Type Toggle */}
        <div className="flex bg-zinc-900/50 p-1.5 rounded-2xl border border-white/5 mx-auto w-fit relative z-10">
          <button 
            onClick={() => { setLoginType('ADMIN'); setStatus('IDLE'); }}
            className={`px-6 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${loginType === 'ADMIN' ? 'bg-[#00ff41] text-black shadow-[0_0_15px_#00ff41]' : 'text-zinc-600'}`}
          >
            Root Admin
          </button>
          <button 
            onClick={() => { setLoginType('SUPPLIER'); setStatus('IDLE'); }}
            className={`px-6 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${loginType === 'SUPPLIER' ? 'bg-[#f59e0b] text-black shadow-[0_0_15px_#f59e0b]' : 'text-zinc-600'}`}
          >
            Supplier Node
          </button>
        </div>

        {/* Biometric Header */}
        <div className="text-center space-y-6">
          <div className="relative w-24 h-24 mx-auto">
             <div 
              className="absolute inset-0 border-2 rounded-full transition-all duration-500"
              style={{ borderColor: status === 'AUTHENTICATING' ? themeColor : `${themeColor}33`, animation: status === 'AUTHENTICATING' ? 'spin 1s linear infinite' : 'none' }}
             ></div>
             <div className="absolute inset-0 flex items-center justify-center text-4xl" style={{ color: themeColor }}>
               {status === 'SUCCESS' ? '🔓' : status === 'ERROR' ? '🚫' : loginType === 'ADMIN' ? '🔐' : '🏭'}
             </div>
          </div>
          <div className="space-y-1">
            <h1 className="text-3xl font-black uppercase tracking-[0.3em]" style={{ color: themeColor }}>
              {loginType === 'ADMIN' ? 'Core_Admin' : 'Node_Access'}
            </h1>
            <p className="text-[10px] opacity-60 uppercase tracking-widest">Authorized Access Required</p>
          </div>
        </div>

        {/* Login Card */}
        <div 
          className="bg-black border p-10 rounded-[2rem] space-y-8 shadow-2xl transition-colors duration-500"
          style={{ borderColor: `${themeColor}44`, boxShadow: `0 0 50px ${themeColor}11` }}
        >
          {status === 'AUTHENTICATING' || status === 'SUCCESS' ? (
            <div className="py-10 space-y-8 text-center animate-in fade-in zoom-in-95 duration-500">
               <div className="space-y-4">
                  <p className="text-[10px] uppercase tracking-[0.5em] animate-pulse" style={{ color: themeColor }}>
                    {status === 'SUCCESS' ? 'UPLINK_STABLE' : 'CALIBRATING_HANDSHAKE'}
                  </p>
                  <div className="w-full h-1 bg-white/5 rounded-full overflow-hidden">
                     <div 
                      className="h-full transition-all duration-300"
                      style={{ width: `${authProgress}%`, backgroundColor: themeColor, boxShadow: `0 0 15px ${themeColor}` }}
                     ></div>
                  </div>
               </div>
               <div className="grid grid-cols-2 gap-4 text-[9px] text-left opacity-40" style={{ color: themeColor }}>
                  <p>HASH_CHECK... OK</p>
                  <p>PORT_SYNC... OK</p>
                  <p>MEM_ALLOC... OK</p>
                  <p>AUTH_TOKEN... OK</p>
               </div>
            </div>
          ) : (
            <form onSubmit={handleSubmit} className="space-y-6">
              <div className="space-y-4">
                <div className="space-y-2">
                   <label className="text-[9px] uppercase tracking-widest px-1 opacity-50">Identity_Handle</label>
                   <input 
                    type="text" 
                    required
                    autoFocus
                    value={credentials.username}
                    onChange={e => setCredentials({...credentials, username: e.target.value})}
                    className="w-full bg-white/5 border border-white/10 p-5 rounded-xl text-xs font-mono outline-none transition-all placeholder:text-white/10"
                    style={{ color: themeColor, borderColor: `${themeColor}22` }}
                    placeholder={loginType === 'ADMIN' ? "ADMIN_ID" : "NODE_ID"}
                   />
                </div>
                <div className="space-y-2">
                   <label className="text-[9px] uppercase tracking-widest px-1 opacity-50">Security_Key</label>
                   <input 
                    type="password" 
                    required
                    value={credentials.password}
                    onChange={e => setCredentials({...credentials, password: e.target.value})}
                    className="w-full bg-white/5 border border-white/10 p-5 rounded-xl text-xs font-mono outline-none transition-all placeholder:text-white/10"
                    style={{ color: themeColor, borderColor: `${themeColor}22` }}
                    placeholder="••••••••••••"
                   />
                </div>
              </div>

              {status === 'ERROR' && (
                <div className="p-4 bg-red-500/10 border border-red-500/30 rounded-xl text-red-500 text-[9px] text-center uppercase tracking-widest font-black animate-pulse">
                  {errorMessage}
                </div>
              )}

              <div className="flex gap-4 pt-4">
                 <button 
                  type="button"
                  onClick={onCancel}
                  className="flex-1 py-4 bg-white/5 text-white/40 rounded-xl text-[10px] font-black uppercase tracking-widest hover:text-white transition-all"
                 >
                   Abort
                 </button>
                 <button 
                  type="submit"
                  className="flex-[2] py-4 text-black rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-white transition-all shadow-xl"
                  style={{ backgroundColor: themeColor }}
                 >
                   Establish Connection
                 </button>
              </div>
            </form>
          )}

          <div className="pt-4 text-center">
             <p className="text-[8px] text-white/20 uppercase tracking-[0.2em]">
               {loginType === 'ADMIN' ? 'Root: ROOT / OVERRIDE_2025' : 'Node: SUPPLIER / NODE_2025'}
             </p>
          </div>
        </div>

        {/* Ticker */}
        <div className="h-4 overflow-hidden opacity-30">
           <div className="animate-[scrollUp_10s_linear_infinite] space-y-1 text-[8px] uppercase" style={{ color: themeColor }}>
              <p>Scanning_archives...</p>
              <p>Syncing_regional_inventory...</p>
              <p>Analyzing_heat_maps...</p>
              <p>Allocating_logistics_bandwidth...</p>
           </div>
        </div>
      </div>

      <style>{`
        @keyframes scrollUp { 0% { transform: translateY(0); } 100% { transform: translateY(-50%); } }
        .animate-shake { animation: shake 0.5s cubic-bezier(.36,.07,.19,.97) both; }
        @keyframes shake {
          10px, 90px { transform: translate3d(-1px, 0, 0); }
          20px, 80px { transform: translate3d(2px, 0, 0); }
          30px, 50px, 70px { transform: translate3d(-4px, 0, 0); }
          40px, 60px { transform: translate3d(4px, 0, 0); }
        }
        @keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
      `}</style>
    </div>
  );
};

