export const databaseService = {
  getAdminCredentials: () => {
    const saved = localStorage.getItem(ADMIN_AUTH_KEY);
    if (!saved) {
      localStorage.setItem(ADMIN_AUTH_KEY, JSON.stringify(DEFAULT_ADMIN));
      return DEFAULT_ADMIN;
    }
    return JSON.parse(saved);
  },

  updateAdminCredentials: (creds: typeof DEFAULT_ADMIN) => {
    localStorage.setItem(ADMIN_AUTH_KEY, JSON.stringify(creds));
    return creds;
  },

  getUsers: (): User[] => {
    const saved = localStorage.getItem(USER_DB_KEY);
    if (!saved) {
      localStorage.setItem(USER_DB_KEY, JSON.stringify(MOCK_USERS));
      return MOCK_USERS;
    }
    return JSON.parse(saved);
  },

  saveUsers: (users: User[]) => {
    localStorage.setItem(USER_DB_KEY, JSON.stringify(users));
  },

  getProducts: (): Product[] => {
    const saved = localStorage.getItem(PRODUCT_DB_KEY);
    if (!saved) {
      const seeded = EXTENDED_PRODUCTS.map((p, i) => ({
        ...p,
        supplierId: i % 2 === 0 ? 'sup1' : 'sup2'
      }));
      localStorage.setItem(PRODUCT_DB_KEY, JSON.stringify(seeded));
      return seeded;
    }
    return JSON.parse(saved);
  },

  saveProducts: (products: Product[]) => {
    localStorage.setItem(PRODUCT_DB_KEY, JSON.stringify(products));
  },

  getSuppliers: (): Supplier[] => {
    const saved = localStorage.getItem(SUPPLIER_DB_KEY);
    if (!saved) {
      localStorage.setItem(SUPPLIER_DB_KEY, JSON.stringify(MOCK_SUPPLIERS));
      return MOCK_SUPPLIERS;
    }
    return JSON.parse(saved);
  },

  saveSuppliers: (suppliers: Supplier[]) => {
    localStorage.setItem(SUPPLIER_DB_KEY, JSON.stringify(suppliers));
  },

  updateUserStatus: (userId: string, status: User['status']) => {
    const users = databaseService.getUsers();
    const updated = users.map(u => u.id === userId ? { ...u, status } : u);
    databaseService.saveUsers(updated);
    return updated;
  },

  deleteUser: (userId: string) => {
    const users = databaseService.getUsers();
    const updated = users.filter(u => u.id !== userId);
    databaseService.saveUsers(updated);
    return updated;
  },

  registerSupplier: (supplier: Partial<Supplier>) => {
    const suppliers = databaseService.getSuppliers();
    const newSupplier: Supplier = {
      ...supplier as Supplier,
      id: `sup${Date.now()}`,
      status: 'ACTIVE',
      performanceScore: 50,
      totalRevenueYield: 0,
      joinedDate: new Date().toISOString().split('T')[0]
    };
    const updated = [...suppliers, newSupplier];
    databaseService.saveSuppliers(updated);
    return updated;
  }
};

import React, { useState, useEffect } from 'react';
import { databaseService } from '../services/databaseService';

interface AdminLoginProps {
  onSuccess: (role: 'ADMIN' | 'SUPPLIER') => void;
  onCancel: () => void;
}

const AdminLogin: React.FC<AdminLoginProps> = ({ onSuccess, onCancel }) => {
  const [loginType, setLoginType] = useState<'ADMIN' | 'SUPPLIER'>('ADMIN');
  const [credentials, setCredentials] = useState({ username: '', password: '' });
  const [status, setStatus] = useState<'IDLE' | 'AUTHENTICATING' | 'SUCCESS' | 'ERROR'>('IDLE');
  const [authProgress, setAuthProgress] = useState(0);
  const [errorMessage, setErrorMessage] = useState('');

  useEffect(() => {
    let interval: any;
    if (status === 'AUTHENTICATING') {
      interval = setInterval(() => {
        setAuthProgress(prev => {
          if (prev >= 100) {
            clearInterval(interval);
            handleFinalAuth();
            return 100;
          }
          return prev + Math.random() * 15;
        });
      }, 150);
    }
    return () => clearInterval(interval);
  }, [status]);

  const handleFinalAuth = () => {
    const storedAdmin = databaseService.getAdminCredentials();

    const isAdmin = loginType === 'ADMIN' && 
                    credentials.username === storedAdmin.identifier && 
                    credentials.password === storedAdmin.password;

    const isSupplier = loginType === 'SUPPLIER' && 
                       credentials.username.toUpperCase() === 'SUPPLIER' && 
                       credentials.password === 'NODE_2025';

    if (isAdmin || isSupplier) {
      setStatus('SUCCESS');
      setTimeout(() => onSuccess(loginType), 1000);
    } else {
      setStatus('ERROR');
      setErrorMessage('INVALID_HANDSHAKE_ACCESS_DENIED');
      setAuthProgress(0);
      setTimeout(() => setStatus('IDLE'), 2000);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (status !== 'IDLE') return;
    setStatus('AUTHENTICATING');
    setAuthProgress(0);
  };

  const themeColor = loginType === 'ADMIN' ? '#00ff41' : '#f59e0b'; // Green vs Amber

  return (
    <div className="fixed inset-0 z-[500] bg-black text-[#00ff41] font-mono flex items-center justify-center p-6 overflow-hidden">
      <div className="absolute inset-0 opacity-[0.05] pointer-events-none bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')]"></div>

      {/* Dynamic HUD decorations */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none opacity-20" style={{ color: themeColor }}>
         <div className="absolute top-10 left-10 text-[10px] space-y-1">
            <p>SYSLOG: {loginType === 'ADMIN' ? 'CRITICAL_OVERRIDE_DETECTED' : 'SUPPLIER_NODE_UPLINK'}</p>
            <p>NODE_ID: {loginType === 'ADMIN' ? 'NT_CORE_ALPHA_9' : 'SUP_SHIPPING_X7'}</p>
         </div>
         <div className="absolute bottom-10 right-10 text-[10px] text-right">
            <p>AUTH_PROTOCOL: {loginType === 'ADMIN' ? 'V_SECURE_9.4' : 'L_LOGISTICS_3.0'}</p>
            <p>ENCRYPTION: AES_256_STABLE</p>
         </div>
      </div>

      <div className={`w-full max-w-lg space-y-10 transition-all duration-500 ${status === 'ERROR' ? 'animate-shake' : ''}`}>

        {/* Login Type Toggle */}
        <div className="flex bg-zinc-900/50 p-1.5 rounded-2xl border border-white/5 mx-auto w-fit relative z-10">
          <button 
            onClick={() => { setLoginType('ADMIN'); setStatus('IDLE'); }}
            className={`px-6 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${loginType === 'ADMIN' ? 'bg-[#00ff41] text-black shadow-[0_0_15px_#00ff41]' : 'text-zinc-600'}`}
          >
            Root Admin
          </button>
          <button 
            onClick={() => { setLoginType('SUPPLIER'); setStatus('IDLE'); }}
