            <div className={`relative mb-8 transition-all duration-500 ${isOpening ? 'scale-125 rotate-6' : 'group-hover:scale-110'}`}>
              <div className="text-8xl filter drop-shadow-[0_0_15px_rgba(236,72,153,0.4)]">
