              onClick={onClose}
              className="text-zinc-700 hover:text-white text-[8px] font-black uppercase tracking-[0.5em] transition-colors"
            >
              ← Return to Main Terminal
            </button>
            <button 
              onClick={() => onAdminAccess?.()}
              className="text-[8px] font-black text-zinc-800 group-hover:text-zinc-500 uppercase tracking-[0.3em] transition-colors"
            >
              Terminal Admin Access
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

