                  <button type="button" onClick={addSize} className="w-12 h-12 bg-white text-black rounded-2xl flex items-center justify-center font-black">+</button>
                </div>
                <div className="flex flex-wrap gap-2">
                  {formData.sizes?.map(size => (
                    <span 
                      key={size} 
                      onClick={() => removeSize(size)}
                      className="bg-white/5 border border-white/10 text-zinc-300 px-3 py-1 rounded-full text-[8px] font-black uppercase cursor-pointer hover:bg-red-500/20 hover:text-red-500 hover:border-red-500/30 transition-all"
                    >
                      {size} ✕
