import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import BottomNav from './components/BottomNav';
import ProductDetail from './components/ProductDetail';
import CartDrawer from './components/CartDrawer';
import Lobby from './components/HomeLobby';
import FamousProducts from './components/FamousProducts';
import TryOn from './components/TryOn';
import Bundles from './components/Bundles';
import OutfitBuilder from './components/OutfitBuilder';
import Categories from './components/Categories';
import FlashSales from './components/FlashSales';
import Profile from './components/Profile';
import WishlistView from './components/WishlistView';
import CategoryPanel from './components/CategoryPanel';
import SocialProofPopup from './components/SocialProofPopup';
import LandingScreen from './components/LandingScreen';
import AdminPanel from './components/AdminPanel';
import SupplierDashboard from './components/SupplierDashboard';
import CheckoutView from './components/CheckoutView';
import AdminLogin from './components/AdminLogin';
import SupplierLogin from './components/SupplierLogin';
import RoleSelection from './components/RoleSelection';
import TrendIntelligence from './components/TrendIntelligence';
import ContactPanel from './components/ContactPanel';
import { EXTENDED_PRODUCTS, MOCK_BUNDLES } from './mockData';
import { USER_ACHIEVEMENTS } from './data/extendedMock';
import { Product, CartItem, Page, ViewState, UserStats, Bundle, Category, Achievement } from './types';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(() => {
    return localStorage.getItem('closet-kraze-auth') === 'true';
  });

  const [currentView, setCurrentView] = useState<ViewState>(ViewState.LOBBY);
  const [activeSupplierId, setActiveSupplierId] = useState<string | null>(null);
  const [showAuthModal, setShowAuthModal] = useState(false);

  const [cart, setCart] = useState<CartItem[]>(() => {
    const saved = localStorage.getItem('closet-kraze-cart');
    return saved ? JSON.parse(saved) : [];
  });
  const [wishlist, setWishlist] = useState<string[]>(() => {
    const saved = localStorage.getItem('closet-kraze-wishlist');
    return saved ? JSON.parse(saved) : [];
  });
  const [achievements, setAchievements] = useState<Achievement[]>(() => {
    const saved = localStorage.getItem('closet-kraze-achievements');
    return saved ? JSON.parse(saved) : USER_ACHIEVEMENTS;
  });

  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isCategoryPanelOpen, setIsCategoryPanelOpen] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [selectedCategory, setSelectedCategory] = useState<Category>('All');
  const [timeLeft, setTimeLeft] = useState(300);

  const [stats, setStats] = useState<UserStats>(() => {
    const saved = localStorage.getItem('closet-kraze-stats');
    return saved ? JSON.parse(saved) : {
      dailyGameAttempts: 0,
      lastGameReset: new Date().toDateString(),
      quests: [
        { id: 'q1', title: 'Analyze Velocity Heat', rewardXP: 100, icon: '🔥', completed: false },
        { id: 'q2', title: 'Refine Identity', rewardXP: 150, icon: '🎨', completed: false }
      ],
      selectedPath: 'CYBER'
    };
  });

  const balances = {
    coins: 4250,
    gems: 120,
    xp: achievements.reduce((acc, ach) => acc + (ach.unlocked ? ach.rewardXP || 0 : 0), 0) + 8500
  };

  useEffect(() => {
    localStorage.setItem('closet-kraze-auth', isAuthenticated.toString());
  }, [isAuthenticated]);

  const requireAuth = (action: () => void) => {
    if (!isAuthenticated) {
      setShowAuthModal(true);
    } else {
      action();
    }
  };

  const addToCart = (product: Product, selectedSize?: string) => {
    requireAuth(() => {
      setCart(prev => {
        const existing = prev.find(item => item.id === product.id && item.selectedSize === selectedSize);
        if (existing) return prev.map(i => (i.id === product.id && i.selectedSize === selectedSize) ? { ...i, quantity: i.quantity + 1 } : i);
        return [...prev, { ...product, quantity: 1, selectedSize }];
      });
      setIsCartOpen(true);
    });
  };

  const toggleWishlist = (product: Product) => {
    requireAuth(() => {
      setWishlist(prev => 
        prev.includes(product.id) 
          ? prev.filter(id => id !== product.id) 
          : [...prev, product.id]
      );
    });
  };

  const handleNavigateView = (view: ViewState) => {
    const protectedViews = [ViewState.PROFILE, ViewState.WISHLIST, ViewState.CHECKOUT];
    if (protectedViews.includes(view)) {
      requireAuth(() => setCurrentView(view));
    } else {
      setCurrentView(view);
    }
  };

  const handleAdminSuccess = (role: 'ADMIN' | 'SUPPLIER', id?: string) => {
    setShowAuthModal(false);
    if (role === 'ADMIN') {
      setCurrentView(ViewState.ADMIN);
    } else {
      setActiveSupplierId(id || 'sup1');
      setCurrentView(ViewState.SUPPLIER_DASHBOARD);
    }
  };

  const handleLoginComplete = (archetype: string) => {
    setStats(prev => ({...prev, selectedPath: archetype}));
    setIsAuthenticated(true);
    setShowAuthModal(false);
  };

  const renderView = () => {
    switch (currentView) {
      case ViewState.LOBBY:
        return (
          <Lobby 
            products={EXTENDED_PRODUCTS} 
            stats={stats} 
            wishlist={wishlist}
            onNavigate={handleNavigateView} 
            onAddToCart={(pId) => {
              const p = EXTENDED_PRODUCTS.find(x => x.id === pId);
              if (p) addToCart(p, p.sizes?.[0]);
            }} 
            onToggleWishlist={toggleWishlist}
            onProductClick={setSelectedProduct}
            onCompleteQuest={(qId) => {
              setStats(prev => ({
                ...prev,
                quests: prev.quests.map(q => q.id === qId ? { ...q, completed: true } : q)
              }));
            }}
          />
        );
      case ViewState.FAMOUS:
        return (
          <FamousProducts 
            products={selectedCategory === 'All' ? EXTENDED_PRODUCTS : EXTENDED_PRODUCTS.filter(p => p.category === selectedCategory)} 
            wishlist={wishlist}
            onProductClick={setSelectedProduct} 
            onAddToCart={(p) => addToCart(p, p.sizes?.[0])}
            onToggleWishlist={toggleWishlist}
          />
        );
      case ViewState.TRY_ON: return <TryOn />;
      case ViewState.BUNDLES: return <Bundles bundles={MOCK_BUNDLES} onAddBundle={(b) => b.products.forEach(p => addToCart(p, p.sizes?.[0]))} />;
      case ViewState.CATEGORIES: return <Categories onSelectCategory={setSelectedCategory} onNavigate={handleNavigateView} />;
      case ViewState.FLASH: return <FlashSales onAddToCart={(p) => addToCart(p, p.sizes?.[0])} />;
      case ViewState.PROFILE: return <Profile stats={stats} onNavigate={handleNavigateView} onLogout={() => setIsAuthenticated(false)} />;
      case ViewState.WISHLIST: return <WishlistView products={EXTENDED_PRODUCTS} wishlistIds={wishlist} onAddToCart={(p) => addToCart(p, p.sizes?.[0])} onToggleWishlist={toggleWishlist} onProductClick={setSelectedProduct} onNavigate={handleNavigateView} />;
      case ViewState.TRENDS: return <TrendIntelligence stats={stats} />;
      case ViewState.CONTACT: return <ContactPanel />;
      case ViewState.ROLE_SELECTION: return <RoleSelection onSelect={(role) => setCurrentView(role === 'ADMIN' ? ViewState.ADMIN_LOGIN : ViewState.SUPPLIER_LOGIN)} onCancel={() => setCurrentView(ViewState.LOBBY)} />;
      case ViewState.ADMIN_LOGIN: return <AdminLogin onSuccess={handleAdminSuccess} onCancel={() => setCurrentView(ViewState.ROLE_SELECTION)} />;
      case ViewState.SUPPLIER_LOGIN: return <SupplierLogin onSuccess={(id) => handleAdminSuccess('SUPPLIER', id)} onCancel={() => setCurrentView(ViewState.ROLE_SELECTION)} />;
      case ViewState.ADMIN: return <AdminPanel onExit={() => setCurrentView(ViewState.LOBBY)} onNavigate={handleNavigateView} />;
      case ViewState.SUPPLIER_DASHBOARD: return <SupplierDashboard supplierId={activeSupplierId || 'sup1'} onLogout={() => setCurrentView(ViewState.LOBBY)} />;
      case ViewState.CHECKOUT: return <CheckoutView items={cart} onComplete={() => setCart([])} onCancel={() => setCurrentView(ViewState.LOBBY)} balances={balances} />;
      default: return <Lobby products={EXTENDED_PRODUCTS} stats={stats} wishlist={wishlist} onNavigate={handleNavigateView} onAddToCart={() => {}} onToggleWishlist={() => {}} onProductClick={setSelectedProduct} onCompleteQuest={() => {}} />;
    }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-[#FAFAFA] flex flex-col font-sans">
      <Header 
        cartCount={cart.reduce((a, b) => a + b.quantity, 0)} 
        wishlistCount={wishlist.length}
        stats={stats}
        onCartOpen={() => setIsCartOpen(true)}
        onNavigatePage={(p) => handleNavigateView(p === Page.HOME ? ViewState.LOBBY : ViewState.FAMOUS)}
        onNavigateView={handleNavigateView}
        currentPage={currentView === ViewState.LOBBY ? Page.HOME : Page.SHOP}
        currentView={currentView}
        dropTime={timeLeft}
        onOpenCategories={() => setIsCategoryPanelOpen(true)}
      />
      <main className="pt-24 flex-1">{renderView()}</main>
      <BottomNav currentView={currentView} onNavigate={handleNavigateView} onOpenCategories={() => setIsCategoryPanelOpen(true)} />
      <CartDrawer isOpen={isCartOpen} onClose={() => setIsCartOpen(false)} items={cart} onRemove={(id) => setCart(prev => prev.filter(i => i.id !== id))} onUpdateQuantity={(id, d) => setCart(prev => prev.map(i => i.id === id ? {...i, quantity: Math.max(1, i.quantity + d)} : i))} onNavigate={handleNavigateView} />
      <CategoryPanel isOpen={isCategoryPanelOpen} onClose={() => setIsCategoryPanelOpen(false)} onSelectCategory={setSelectedCategory} onNavigate={handleNavigateView} activeCategory={selectedCategory} products={EXTENDED_PRODUCTS} onProductSelect={setSelectedProduct} />
      <SocialProofPopup />
      {selectedProduct && <ProductDetail product={selectedProduct} stats={stats} onClose={() => setSelectedProduct(null)} onAddToCart={addToCart} onUpdateSynergy={() => {}} onToggleWishlist={toggleWishlist} isInWishlist={wishlist.includes(selectedProduct.id)} />}

      {/* Authentication Modal Overlay */}
      {showAuthModal && (
        <LandingScreen 
          onComplete={handleLoginComplete} 
          onAdminAccess={() => {
            setShowAuthModal(false);
            setCurrentView(ViewState.ROLE_SELECTION);
          }}
          onClose={() => setShowAuthModal(false)}
        />
      )}
    </div>
  );
};

export default App;

import React from 'react';
import { Product } from '../types';

interface ProductCardProps {
  product: Product;
  onClick: (product: Product) => void;
  onAddToCart: (product: Product) => void;
  onToggleWishlist: (product: Product) => void;
  isWishlisted: boolean;
}

const ProductCard: React.FC<ProductCardProps> = ({ 
  product, 
  onClick, 
  onAddToCart, 
  onToggleWishlist,
  isWishlisted 
}) => {
  const discountPercent = Math.round(((product.originalPrice - product.price) / product.originalPrice) * 100);

  // Rarity calculation based on Hype Score
  const getRarity = (score: number) => {
    if (score > 90) return { label: 'MYTHIC', color: 'text-purple-400', border: 'border-purple-500/30' };
    if (score > 75) return { label: 'RARE', color: 'text-pink-400', border: 'border-pink-500/30' };
    return { label: 'ARCHIVE', color: 'text-zinc-500', border: 'border-zinc-500/20' };
  };

  const rarity = getRarity(product.hypeScore);
  const demandWidth = Math.min(100, (product.viewers / 200) * 100);

  return (
    <div className="group relative flex flex-col h-full">
      {/* Visual Asset Container */}
      <div 
        className="relative aspect-[4/5] overflow-hidden bg-zinc-950 border border-white/5 cursor-pointer mb-5 rounded-sm"
        onClick={() => onClick(product)}
      >
        {/* Background Technical Noise */}
        <div className="absolute inset-0 opacity-[0.03] pointer-events-none bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')]"></div>

        <img 
          src={product.image} 
          alt={product.name} 
          className="w-full h-full object-cover transition-all duration-[1.5s] group-hover:scale-110 group-hover:opacity-30 group-hover:blur-[2px]"
        />

        {/* Urgent Overlays */}
        {discountPercent > 0 && (
          <div className="absolute top-0 right-0 p-4 z-10">
            <div className="bg-[#EC4899] text-white px-3 py-1 text-[9px] font-black uppercase tracking-widest shadow-[0_0_20px_rgba(236,72,153,0.4)]">
              -{discountPercent}%
            </div>
          </div>
        )}

        <div className="absolute top-0 left-0 p-4 z-10 space-y-2">
          <div className="bg-black/80 backdrop-blur-xl border border-white/10 px-3 py-1 flex items-center gap-2">
            <span className={`text-[8px] font-black uppercase tracking-tighter ${rarity.color}`}>
              {rarity.label}_TIER
            </span>
          </div>
          {product.isNew && (
            <div className="bg-blue-600 text-white px-3 py-1 text-[8px] font-black uppercase tracking-[0.2em] w-fit">
              NEW_SIGNAL
            </div>
          )}
        </div>

        {/* Hover UI: Decision Hub */}
        <div className="absolute inset-0 flex flex-col items-center justify-center translate-y-8 opacity-0 group-hover:translate-y-0 group-hover:opacity-100 transition-all duration-500 bg-black/40 backdrop-blur-sm p-8">
          <div className="text-[10px] font-black uppercase tracking-[0.4em] text-white mb-8 border-b border-white/20 pb-2">
            Asset_Control
          </div>

          <div className="flex w-full gap-2">
            <button 
              onClick={(e) => { e.stopPropagation(); onAddToCart(product); }}
              className="flex-1 py-5 bg-white text-black text-[10px] uppercase tracking-[0.3em] font-black hover:bg-[#EC4899] hover:text-white transition-all shadow-2xl active:scale-95"
            >
              Acquire
            </button>
            <button 
              onClick={(e) => { e.stopPropagation(); onToggleWishlist(product); }}
              className={`w-14 h-14 flex items-center justify-center rounded-sm border transition-all ${
                isWishlisted 
                ? 'bg-[#EC4899] border-[#EC4899] text-white shadow-lg' 
                : 'bg-black/50 border-white/20 text-white hover:bg-white hover:text-black'
              }`}
            >
              {isWishlisted ? '💖' : '🤍'}
            </button>
          </div>

          <div className="mt-8 text-center space-y-1">
             <div className="text-[8px] font-black text-zinc-500 uppercase tracking-widest">Protocol Version</div>
             <div className="text-[8px] font-mono text-zinc-600">CC_UPLINK_2.5</div>
          </div>
        </div>

        {/* Scarcity Trigger */}
        {product.stockCount <= 5 && product.stockCount > 0 && (
          <div className="absolute bottom-4 left-4 right-4 z-10">
             <div className="w-full bg-red-600/90 backdrop-blur-md text-white py-1.5 px-3 text-[8px] font-black uppercase tracking-widest text-center shadow-lg animate-pulse">
               CRITICAL_STOCK: {product.stockCount} LEFT
             </div>
          </div>
        )}
      </div>

      {/* Product Information Metadata */}
      <div className="flex flex-col gap-3 flex-1" onClick={() => onClick(product)}>
        <div className="flex justify-between items-start gap-4">
          <div className="space-y-1">
            <h3 className="text-sm font-black uppercase tracking-tight text-white group-hover:text-[#EC4899] transition-colors leading-tight">
              {product.name}
            </h3>
            <div className="flex items-center gap-2">
              <span className="text-[7px] font-black text-zinc-600 uppercase tracking-widest">
                Sector_{product.category}
              </span>
              <span className="w-1 h-1 bg-zinc-800 rounded-full"></span>
              <span className="text-[7px] font-black uppercase tracking-[0.2em] border border-zinc-500/30 px-1.5 py-0.5 rounded-sm text-zinc-500">
                {product.gender}
              </span>
            </div>
          </div>
          <div className="text-right flex flex-col">
            <span className="text-lg font-black font-mono tracking-tighter text-white">GH₵{product.price}</span>
            <span className="text-[9px] font-mono text-zinc-600 line-through opacity-50">GH₵{product.originalPrice}</span>
          </div>
        </div>

        {/* Neural Demand Visualizer (Optimized Display) */}
        <div className="space-y-1.5 pt-2 border-t border-white/5">
          <div className="flex justify-between items-center text-[7px] font-black uppercase tracking-[0.2em] text-zinc-600">
            <span>Neural Demand Signal</span>
            <span className="text-zinc-400">{demandWidth.toFixed(1)}% Active</span>
          </div>
          <div className="h-[2px] w-full bg-zinc-900 overflow-hidden">
            <div 
              className={`h-full bg-[#EC4899] shadow-[0_0_8px_#EC4899] transition-all duration-[2s] group-hover:bg-white`} 
              style={{ width: `${demandWidth}%` }}
            ></div>
          </div>
        </div>

        {/* Tags */}
        <div className="flex flex-wrap gap-1 mt-1">
          {product.tags?.slice(0, 3).map(tag => (
            <span 
              key={tag} 
              className="text-[6px] font-black uppercase tracking-widest bg-zinc-900 border border-white/5 px-2 py-0.5 text-zinc-500 group-hover:text-zinc-300 transition-colors"
            >
              #{tag}
            </span>
          ))}
        </div>
      </div>
    </div>
  );
};

