import React, { useState, useMemo, useEffect } from 'react';
import { Product, UserStats } from '../types';

interface ProductDetailProps {
  product: Product;
  stats: UserStats;
  allProducts: Product[];
  onClose: () => void;
  onAddToCart: (product: Product, selectedSize?: string) => void;
  onUpdateSynergy: (synergy: string) => void;
  onToggleWishlist: (product: Product) => void;
  onProductClick: (product: Product) => void;
  isInWishlist: boolean;
}

const ProductDetail: React.FC<ProductDetailProps> = ({ 
  product, 
  stats,
  allProducts,
  onClose, 
  onAddToCart, 
  onToggleWishlist,
  onProductClick,
  isInWishlist
}) => {
  const [selectedSize, setSelectedSize] = useState<string>(product.sizes?.[0] || '');
  const activeViewers = Math.floor(product.viewers / 4) + 12;

  // JSON-LD Structured Data for SEO
  useEffect(() => {
    const jsonLd = {
      "@context": "https://schema.org/",
      "@type": "Product",
      "name": product.name,
      "image": [product.image],
      "description": product.description,
      "sku": `CC-${product.id}`,
      "brand": {
        "@type": "Brand",
        "name": "Closet Kraze"
      },
      "offers": {
        "@type": "Offer",
        "url": `https://closetkraze.app/product/${product.id}`,
        "priceCurrency": "GHS",
        "price": product.price,
        "itemCondition": "https://schema.org/NewCondition",
        "availability": product.inStock ? "https://schema.org/InStock" : "https://schema.org/OutOfStock"
      }
    };

    const script = document.createElement('script');
    script.type = 'application/ld+json';
    script.id = `jsonld-${product.id}`;
    script.innerHTML = JSON.stringify(jsonLd);
    document.head.appendChild(script);

    return () => {
      const existing = document.getElementById(`jsonld-${product.id}`);
      if (existing) existing.remove();
    };
  }, [product]);

  const similarProducts = useMemo(() => {
    return allProducts
      .filter(p => p.id !== product.id && (p.category === product.category))
      .sort((a, b) => b.hypeScore - a.hypeScore)
      .slice(0, 6);
  }, [product.id, product.category, allProducts]);

  const isFootwear = product.category === 'Footwear';

  return (
    <div className="fixed inset-0 z-[150] bg-black flex flex-col md:flex-row animate-in fade-in duration-700 overflow-y-auto md:overflow-hidden">

