            <div className="w-2 h-2 rounded-full bg-red-500 animate-ping"></div>
            <span className="text-[8px] md:text-[10px] font-black uppercase tracking-[0.2em] text-white">
              {activeViewers} Watching
            </span>
          </div>
        </div>

        <div className="absolute bottom-10 left-6 right-6 md:bottom-12 md:left-12 md:right-12 space-y-4 md:space-y-6">
          <h1 className="text-4xl md:text-8xl font-serif italic text-white tracking-tighter leading-none max-w-2xl">{product.name}</h1>
          <div className="flex flex-wrap gap-2 md:gap-3">
            <span className="text-[8px] md:text-[10px] font-black uppercase tracking-widest text-zinc-500 glass px-3 py-1 md:px-4 md:py-1.5 rounded-full border border-zinc-500/40">
              {product.gender}
            </span>
            {product.tags?.map(tag => (
              <span key={tag} className="text-[8px] md:text-[10px] font-black uppercase tracking-widest text-zinc-400 glass px-3 py-1 md:px-4 md:py-1.5 rounded-full border-purple-500/40 border">
                #{tag}
              </span>
            ))}
          </div>
        </div>
      </div>

      {/* Commerce Zone */}
      <div className="w-full md:w-2/5 bg-[#050505] p-8 md:p-16 flex flex-col gap-8 md:gap-10 border-l border-white/5 overflow-y-auto">

        <section className="space-y-4 md:space-y-6">
          <div className="text-[9px] md:text-[10px] font-black text-zinc-500 uppercase tracking-[0.4em] mb-4">Market Valuation</div>
          <div className="flex items-end justify-between">
            <div className="space-y-1">
              <span className="text-zinc-600 text-base md:text-lg font-mono line-through block tracking-tighter">GH₵{product.originalPrice}</span>
              <span className="text-5xl md:text-6xl font-black font-mono tracking-tighter text-white">GH₵{product.price}</span>
