            <div className="flex justify-between items-center">
              <div className="text-[9px] md:text-[10px] font-black text-zinc-500 uppercase tracking-[0.4em]">
                {isFootwear ? 'Select Footing Scale' : 'Select Silhouette Scale'}
              </div>
              <div className="text-[7px] md:text-[8px] font-black text-[#EC4899] uppercase tracking-widest bg-[#EC4899]/5 border border-[#EC4899]/20 px-2 py-0.5 rounded">
                Standard ISO
              </div>
            </div>
            <div className={isFootwear ? "grid grid-cols-4 gap-2 md:gap-3" : "flex flex-wrap gap-2 md:gap-3"}>
