import { GoogleGenAI, Type } from "@google/genai";
import { TrendReport } from "../types";

// Initialize the Gemini API client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Generates high-fashion technical styling advice.
 */
export const getStylingAdvice = async (mood: string, occasion: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `You are the Senior Style Architect of the New Tokyo circuit. Provide brief, lethal, high-fashion styling advice for a ${mood} mood for a ${occasion} objective. Use technical and archival terminology. Keep it under 45 words.`,
      config: {
        temperature: 0.8,
        topP: 0.95,
      }
    });
    return response.text || "Neural sensors jammed. Maintain current silhouette protocol.";
  } catch (error) {
    console.error("Styling Intel Failure:", error);
    return "The circuit is experiencing interference. Re-synchronize later.";
  }
};

/**
 * Pulls structured trend intelligence for specific archetypes.
 */
export const getTrendIntelligence = async (archetype: string): Promise<TrendReport> => {
  try {
