                </p>
              </div>
            </footer>
          )}

          {/* Clear Confirmation Modal */}
          {showClearConfirm && (
            <div className="absolute inset-0 z-50 bg-black/95 backdrop-blur-3xl flex items-center justify-center p-8 animate-in fade-in duration-300">
               <div className="w-full space-y-12 text-center animate-in zoom-in-95 duration-500">
                  <div className="relative w-32 h-32 mx-auto">
                    <div className="absolute inset-0 border-2 border-red-500/20 rounded-full animate-ping"></div>
                    <div className="absolute inset-0 flex items-center justify-center text-6xl">💣</div>
                  </div>

                  <div className="space-y-4">
                    <h3 className="text-4xl font-serif italic text-white tracking-tighter">Abort Haul?</h3>
                    <p className="text-zinc-500 text-[10px] font-black uppercase tracking-[0.5em] max-w-xs mx-auto leading-relaxed">
                      All reserved silhouettes will be returned to the circuit immediately. This action is non-reversible.
                    </p>
                  </div>

                  <div className="flex flex-col gap-4">
                    <button 
                      onClick={handleClearAll}
                      className="w-full py-6 bg-red-600 text-white rounded-2xl font-black uppercase tracking-widest text-[10px] hover:bg-red-500 transition-all shadow-xl active:scale-95"
                    >
                      Initialize Wipe
                    </button>
                    <button 
                      onClick={() => setShowClearConfirm(false)}
                      className="w-full py-6 bg-white/5 border border-white/10 text-white rounded-2xl font-black uppercase tracking-widest text-[10px] hover:bg-white hover:text-black transition-all"
                    >
                      Maintain Reserves
                    </button>
                  </div>
               </div>
            </div>
          )}
        </div>
      </div>
    </>
  );
};

