export default StylistAI;

import React, { useState, useMemo, useRef } from 'react';
import { Product, UserStats } from '../types';

interface ProductDetailProps {
  product: Product;
  stats: UserStats;
  allProducts: Product[];
  onClose: () => void;
  onAddToCart: (product: Product, selectedSize?: string) => void;
  onUpdateSynergy: (synergy: string) => void;
  onToggleWishlist: (product: Product) => void;
  onProductClick: (product: Product) => void;
  isInWishlist: boolean;
}

const ProductDetail: React.FC<ProductDetailProps> = ({ 
  product, 
  stats,
  allProducts,
  onClose, 
  onAddToCart, 
  onToggleWishlist,
  onProductClick,
  isInWishlist
}) => {
  const [selectedSize, setSelectedSize] = useState<string>(product.sizes?.[0] || '');
  const [isMaterializing, setIsMaterializing] = useState(false);
  const [tryOnResult, setTryOnResult] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const activeViewers = Math.floor(product.viewers / 4) + 12;

  // Pairing Logic: Suggest items from different categories to complete the look
  const pairingSuggestions = useMemo(() => {
    return allProducts
      .filter(p => p.id !== product.id && p.category !== product.category)
      .sort((a, b) => b.hypeScore - a.hypeScore)
      .slice(0, 6);
  }, [product.id, product.category, allProducts]);

  const handleProductSwap = (newProduct: Product) => {
    onProductClick(newProduct);
    setTryOnResult(null);
    const detailContainer = document.getElementById('product-detail-container');
    if (detailContainer) {
      detailContainer.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setIsMaterializing(true);
      setTryOnResult(null);
      setTimeout(() => {
        const reader = new FileReader();
        reader.onload = (event) => {
          setTryOnResult(event.target?.result as string);
          setIsMaterializing(false);
        };
        reader.readAsDataURL(file);
      }, 2500);
    }
  };

  const handleShare = async () => {
    const shareMessage = `Silhouette: ${product.name}\nIntel: ${product.description}\nSource: www.closetkraze.com\n\nBuy now!`;

    if (navigator.share) {
      try {
        await navigator.share({
          title: `Closet Kraze | ${product.name}`,
          text: shareMessage,
          url: 'https://www.closetkraze.com',
        });
      } catch (err) {
        console.error('Transmission aborted');
      }
    } else {
      navigator.clipboard.writeText(`${shareMessage} https://www.closetkraze.com`);
      alert('Transmission protocol copied to clipboard.');
    }
  };

  return (
    <div id="product-detail-container" className="fixed inset-0 z-[150] bg-black flex flex-col md:flex-row animate-in fade-in duration-700 overflow-y-auto md:overflow-hidden font-sans text-white">

      {/* Visual Immersive Zone */}
      <div className="w-full md:w-3/5 h-[70vh] md:h-full relative bg-zinc-950 overflow-hidden shrink-0">
        {isMaterializing ? (
          <div className="absolute inset-0 z-30 bg-black flex flex-col items-center justify-center p-12">
            <div className="relative w-48 h-48 mb-8">
               <div className="absolute inset-0 border-4 border-[#EC4899]/20 border-t-[#EC4899] rounded-full animate-spin"></div>
               <div className="absolute inset-4 border-2 border-white/5 border-b-white/20 rounded-full animate-spin-slow"></div>
               <div className="absolute inset-0 flex items-center justify-center text-5xl">🧬</div>
            </div>
            <div className="space-y-2 text-center">
               <p className="text-[11px] font-black uppercase tracking-[0.5em] text-[#EC4899] animate-pulse">Materializing Silhouette</p>
               <p className="text-[8px] text-zinc-600 uppercase tracking-widest">Applying neural layers to user archive...</p>
            </div>
          </div>
        ) : tryOnResult ? (
          <div className="absolute inset-0 z-20 group">
             <img src={tryOnResult} className="w-full h-full object-cover animate-in zoom-in-110 duration-[2s]" alt="Try On Result" />
             <div className="absolute inset-0 bg-gradient-to-t from-black via-black/20 to-transparent"></div>
             <div className="absolute inset-0 opacity-40 mix-blend-overlay pointer-events-none">
                <img src={product.image} className="w-full h-full object-contain" alt="Product Mask" />
             </div>
             <button 
               onClick={() => setTryOnResult(null)}
               className="absolute top-10 left-32 px-6 py-2 glass rounded-full border-white/20 text-[10px] font-black uppercase tracking-widest hover:bg-white hover:text-black transition-all"
             >
               Reset View
             </button>
             <div className="absolute top-10 right-10 flex flex-col items-end gap-3">
                <div className="bg-purple-600/90 text-white px-4 py-1.5 rounded-xl text-[9px] font-black uppercase tracking-[0.2em] shadow-2xl">
                  AI_SYNTH_VERIFIED
                </div>
             </div>
          </div>
        ) : null}

        <img 
          src={product.image} 
          className={`w-full h-full object-cover transition-opacity duration-1000 ${tryOnResult ? 'opacity-0' : 'opacity-80'}`} 
          alt={product.name} 
        />

        <div className="absolute inset-0 bg-gradient-to-t from-black via-black/40 to-transparent pointer-events-none"></div>

        <button 
          onClick={onClose} 
          className="absolute top-10 left-10 w-14 h-14 rounded-full glass flex items-center justify-center text-white text-xl z-20 hover:bg-white hover:text-black transition-all"
        >
          ←
        </button>

        <div className="absolute top-10 right-10 flex flex-col items-end gap-3 z-20">
          <div className="bg-black/60 backdrop-blur-xl border border-white/10 px-5 py-2.5 rounded-2xl flex items-center gap-3">
            <div className="w-2 h-2 rounded-full bg-red-500 animate-ping"></div>
            <span className="text-[10px] font-black uppercase tracking-[0.2em] text-white">
              {activeViewers} Watching
            </span>
          </div>
        </div>

        <div className="absolute bottom-12 left-12 right-12 space-y-6">
          <div className="flex items-center gap-4 group/camera">
            <h2 className="text-5xl md:text-8xl font-serif italic text-white tracking-tighter leading-none max-w-2xl">{product.name}</h2>

            <button 
              onClick={() => fileInputRef.current?.click()}
              className="w-12 h-12 md:w-16 md:h-16 rounded-full glass border border-white/10 flex items-center justify-center text-2xl md:text-3xl hover:bg-[#EC4899] hover:border-[#EC4899] hover:shadow-[0_0_30px_rgba(236,72,153,0.5)] transition-all active:scale-90 relative shrink-0 group/btn"
              title="Initialize Neural Try-On"
            >
              <span className="group-hover/btn:scale-110 transition-transform duration-300">📸</span>
              <div className="absolute -bottom-1 w-1.5 h-1.5 bg-[#EC4899] rounded-full animate-pulse"></div>
            </button>
            <input 
              type="file" 
              ref={fileInputRef} 
              className="hidden" 
              accept="image/*" 
              onChange={handleFileUpload}
            />
          </div>

          <div className="flex flex-wrap gap-3">
            <span className="text-[10px] font-black uppercase tracking-widest text-zinc-500 glass px-4 py-1.5 rounded-full border border-zinc-500/40">
              {product.gender}
            </span>
            {product.tags?.map(tag => (
              <span key={tag} className="text-[10px] font-black uppercase tracking-widest text-zinc-400 glass px-4 py-1.5 rounded-full border border-purple-500/40">
                #{tag}
              </span>
            ))}
          </div>
        </div>
      </div>

      {/* Commerce Zone */}
      <div className="w-full md:w-2/5 bg-[#050505] p-10 md:p-16 flex flex-col gap-12 border-l border-white/5 overflow-y-auto scrollbar-hide">

        <section className="space-y-6">
          <div className="text-[10px] font-black text-zinc-500 uppercase tracking-[0.4em] mb-4">Market Valuation</div>
          <div className="flex items-end justify-between">
            <div className="space-y-1">
              <span className="text-zinc-600 text-lg font-mono line-through block tracking-tighter">GH₵{product.originalPrice}</span>
              <span className="text-6xl font-black font-mono tracking-tighter text-white">GH₵{product.price}</span>
            </div>
          </div>
        </section>

        {/* Size Selection */}
        {product.sizes && product.sizes.length > 0 && (
          <section className="space-y-4">
            <div className="text-[10px] font-black text-zinc-500 uppercase tracking-[0.4em]">Select Silhouette Scale</div>
            <div className="flex flex-wrap gap-3">
              {product.sizes.map(size => (
                <button
                  key={size}
                  onClick={() => setSelectedSize(size)}
                  className={`min-w-[50px] h-12 rounded-xl font-mono text-xs font-black transition-all border ${
                    selectedSize === size 
                    ? 'bg-white text-black border-white shadow-[0_0_20px_rgba(255,255,255,0.2)]' 
                    : 'bg-transparent text-zinc-500 border-white/10 hover:border-white/30'
                  }`}
                >
                  {size}
                </button>
              ))}
            </div>
          </section>
        )}

        <section className="space-y-4">
          <div className="text-[10px] font-black text-zinc-500 uppercase tracking-[0.4em]">Silhouette Intel</div>
          <p className="text-zinc-300 text-sm md:text-base italic font-serif leading-relaxed">
            "{product.description}"
          </p>
          <div className="grid grid-cols-1 gap-3 pt-4 border-b border-white/5 pb-10">
            {product.details.map((detail, idx) => (
              <div key={idx} className="flex items-center gap-4">
                <div className="w-1.5 h-1.5 rounded-full border border-pink-500/30"></div>
                <span className="text-[10px] font-black uppercase tracking-[0.2em] text-zinc-500">{detail}</span>
              </div>
            ))}
          </div>
        </section>

        {/* Pairing Suggestions: Complete the Silhouette */}
        {pairingSuggestions.length > 0 && (
          <section className="space-y-8 pt-4">
            <div className="flex justify-between items-end border-b border-white/5 pb-4">
              <div className="space-y-1">
                 <div className="flex items-center gap-2">
                    <div className="w-1.5 h-1.5 rounded-full bg-[#EC4899] animate-pulse"></div>
                    <h4 className="text-[10px] font-black text-white uppercase tracking-[0.4em]">Complete the Silhouette</h4>
                 </div>
                 <p className="text-[8px] text-zinc-600 uppercase tracking-widest font-bold">Neural Pairing Suggestions</p>
              </div>
              <div className="text-[8px] font-black text-zinc-500 uppercase tracking-widest">Recommended</div>
            </div>

            <div className="flex gap-6 overflow-x-auto pb-6 scrollbar-hide snap-x snap-mandatory -mx-2 px-2">
               {pairingSuggestions.map(p => {
                 const matchPercent = 94 + Math.floor(Math.random() * 5);
                 return (
                    <button 
                      key={p.id}
                      onClick={() => handleProductSwap(p)}
                      className="min-w-[140px] md:min-w-[160px] text-left group snap-start relative flex flex-col"
                    >
                      <div className="aspect-[3/4] rounded-2xl overflow-hidden bg-zinc-900 border border-white/5 mb-3 group-hover:border-[#EC4899]/40 transition-all duration-500 relative">
                        <img 
                          src={p.image} 
                          className="w-full h-full object-cover opacity-50 group-hover:opacity-100 transition-all duration-700 group-hover:scale-105" 
                          alt={p.name}
                        />
                        <div className="absolute top-2 left-2 bg-black/80 backdrop-blur-md px-1.5 py-0.5 rounded-md border border-white/10">
                           <span className="text-[7px] font-black text-[#EC4899] uppercase">{p.category}</span>
                        </div>
                      </div>
                      <div className="space-y-1">
                        <div className="text-[8px] font-black text-blue-400 uppercase tracking-widest leading-none">{matchPercent}% SYNERGY</div>
                        <div className="text-[10px] font-bold text-zinc-300 uppercase truncate group-hover:text-white transition-colors">{p.name}</div>
                        <div className="text-[9px] font-mono font-black text-zinc-500">GH₵{p.price}</div>
                      </div>
                    </button>
                 );
               })}
            </div>
          </section>
        )}

        <section className="space-y-10 pt-12 border-t border-white/5 sticky bottom-0 bg-[#050505] pb-10 mt-auto z-10">
          {/* Social Transmission Circle Button */}
          <div className="flex flex-col items-center gap-6 group/share">
             <p className="text-[10px] font-black text-zinc-500 uppercase tracking-[0.3em] text-center italic opacity-60">
                (do you know anyone that might be interested?)
             </p>
             <button 
                onClick={handleShare}
                className="w-20 h-20 rounded-full bg-white text-black flex items-center justify-center text-3xl shadow-[0_0_40px_rgba(255,255,255,0.05)] hover:shadow-[0_0_50px_rgba(236,72,153,0.3)] hover:bg-[#EC4899] hover:text-white transition-all duration-500 active:scale-90 relative overflow-hidden"
             >
                <div className="absolute inset-0 bg-gradient-to-tr from-transparent via-white/20 to-transparent -translate-x-full group-hover/share:translate-x-full transition-transform duration-1000"></div>
                <span className="relative z-10">📤</span>
             </button>
             <p className="text-[8px] font-black text-zinc-700 uppercase tracking-[0.5em]">Transmit Protocol</p>
          </div>

          <div className="flex gap-4">
            <button 
              onClick={() => onAddToCart(product, selectedSize)}
              className="flex-[4] h-20 bg-white text-black rounded-3xl font-black uppercase tracking-[0.4em] text-xs hover:bg-[#EC4899] hover:text-white transition-all shadow-3xl active:scale-95 group relative overflow-hidden"
            >
              <span className="relative z-10">Initialize Acquisition</span>
              <div className="absolute inset-0 bg-[#EC4899] translate-y-full group-hover:translate-y-0 transition-transform duration-300"></div>
            </button>
            <button 
              onClick={() => onToggleWishlist(product)}
              className={`flex-1 h-20 rounded-3xl border flex items-center justify-center text-2xl transition-all ${
                isInWishlist ? 'bg-[#EC4899] border-[#EC4899] text-white shadow-lg' : 'bg-transparent border-white/10 text-zinc-500 hover:border-white/30'
              }`}
            >
              {isInWishlist ? '💖' : '🤍'}
            </button>
          </div>
          <p className="text-center text-[9px] font-black uppercase tracking-[0.3em] text-zinc-700">
            Secure checkout via circuit encryption v2.5
          </p>
        </section>
      </div>
    </div>
  );
};

export default ProductDetail;

export type Category = 'All' | 'Apparel' | 'Accessories' | 'Home' | 'Beauty';
export type Gender = 'MALE' | 'FEMALE' | 'UNISEX';

export interface Notification {
  id: string;
  title: string;
  message: string;
  type: 'INFO' | 'URGENT' | 'REWARD' | 'WELCOME';
  timestamp: string;
  read: boolean;
}

export interface Product {
  id: string;
  name: string;
  price: number;
  originalPrice: number;
  image: string;
  category: Category;
  gender: Gender;
  description: string;
  details: string[];
  inStock: boolean;
  isNew?: boolean;
  viewers: number;
  stockCount: number;
  hypeScore: number;
  velocityScore: number; // Calculated: (Sales/TotalUsers) / (Stock/TimeToSoldOut)
  synergyPath?: string;
  tags?: string[];
  supplierId?: string; // Link to supplier
  sizes: string[]; // Available sizes e.g. ['S', 'M', 'L', 'XL'] or ['OS']
}

export interface Supplier {
  id: string;
  name: string;
  contactEmail: string;
  region: string;
  status: 'ACTIVE' | 'SUSPENDED' | 'RESTRICTED';
  performanceScore: number; // 0-100
  totalRevenueYield: number;
  joinedDate: string;
}

export interface User {
  id: string;
  handle: string;
  email: string;
  archetype: string;
  xp: number;
  coins: number;
  gems: number;
  status: 'ACTIVE' | 'BANNED' | 'RESTRICTED';
  lastLogin: string;
  totalSpent: number;
}

export interface Bundle {
  id: string;
  name: string;
  products: Product[];
  bundlePrice: number;
  description: string;
  expiresIn: number; // seconds
}

export interface FlashSale extends Product {
  saleEndTime: number; // timestamp
  discountPercent: number;
}

export interface CartItem extends Product {
  quantity: number;
  selectedSize?: string;
}

