  TRY_ON = 'TRY_ON',
  CATEGORIES = 'CATEGORIES',
  BUNDLES = 'BUNDLES',
  FLASH = 'FLASH',
  PROFILE = 'PROFILE',
  OUTFIT_BUILDER = 'OUTFIT_BUILDER',
  WISHLIST = 'WISHLIST',
  ADMIN = 'ADMIN',
  ADMIN_LOGIN = 'ADMIN_LOGIN',
  SUPPLIER_LOGIN = 'SUPPLIER_LOGIN',
  ROLE_SELECTION = 'ROLE_SELECTION',
  SUPPLIER_DASHBOARD = 'SUPPLIER_DASHBOARD',
  CHECKOUT = 'CHECKOUT',
  TRENDS = 'TRENDS',
  CONTACT = 'CONTACT',
  GAME_SHOWROOM = 'GAME_SHOWROOM',
