        {/* Main Console */}
        <main className="flex-1 overflow-y-auto p-12 bg-[radial-gradient(circle_at_top_right,_#111_0%,_transparent_50%)]">
          {activeTab === 'BROADCAST' && (
            <div className="max-w-4xl space-y-12 animate-in fade-in duration-500">
               <header>
                  <h2 className="text-3xl font-serif italic text-white leading-none">Broadcast_Hub</h2>
                  <p className="text-[10px] font-black text-zinc-500 uppercase tracking-[0.4em] mt-2">Initialize Global Signal Transmissions</p>
               </header>

               <div className="grid lg:grid-cols-2 gap-10">
                  <div className="bg-zinc-950 border border-white/5 p-10 rounded-[3rem] space-y-8 shadow-2xl">
                     <div className="text-[10px] font-black text-[#EC4899] uppercase tracking-widest border-l-2 border-[#EC4899] pl-3">Compose Transmission</div>
                     <form onSubmit={handleSendBroadcast} className="space-y-6">
                        <div className="space-y-2">
