                            className="w-full bg-black border border-white/10 p-5 rounded-2xl text-xs font-black text-white outline-none appearance-none"
                           >
                              <option value="INFO">Aura: Standard Info</option>
                              <option value="URGENT">Aura: High Alert (Urgent)</option>
                              <option value="REWARD">Aura: Gift / Reward</option>
                           </select>
                        </div>
                        <div className="space-y-2">
                           <label className="text-[9px] font-black text-zinc-600 uppercase tracking-widest px-2">Intel Payload</label>
                           <textarea 
                            required rows={4}
