                </div>

                <div className="mt-8 flex justify-between items-center relative z-10">
                   <div className="text-[8px] font-black text-zinc-600 uppercase tracking-[0.2em]">Synchronization</div>
                   <div className="text-[10px] font-mono font-black text-zinc-400">
                     {ach.progress} <span className="text-zinc-700">/</span> {ach.goal}
                   </div>
                </div>
              </div>
            );
          })}
        </div>
      </section>

      {/* Global Influence Section */}
      <section className="bg-red-950/10 border border-red-500/20 p-10 rounded-[3rem] flex flex-col md:flex-row items-center justify-between gap-8">
        <div className="flex items-center gap-6">
          <div className="w-16 h-16 rounded-full bg-red-500/10 border border-red-500/30 flex items-center justify-center text-3xl animate-pulse">📢</div>
          <div className="space-y-1">
            <h4 className="text-xl font-serif italic text-white">Market Influence</h4>
            <p className="text-[10px] font-black text-red-500 uppercase tracking-widest">Your Rep Matrix accounts for 0.04% of global trend volatility.</p>
          </div>
        </div>
        <button 
          onClick={() => onNavigate(ViewState.FAMOUS)}
          className="px-10 py-4 bg-white text-black rounded-2xl font-black uppercase tracking-widest text-[10px] hover:bg-[#EC4899] hover:text-white transition-all shadow-xl"
        >
          Increase Influence
        </button>
      </section>
    </div>
  );
};

export default Profile;

import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import BottomNav from './components/BottomNav';
import ProductDetail from './components/ProductDetail';
import CartDrawer from './components/CartDrawer';
import NotificationCenter from './components/NotificationCenter';
import Lobby from './components/HomeLobby';
import FamousProducts from './components/FamousProducts';
import TryOn from './components/TryOn';
import Bundles from './components/Bundles';
import OutfitBuilder from './components/OutfitBuilder';
import Categories from './components/Categories';
import FlashSales from './components/FlashSales';
import Profile from './components/Profile';
import WishlistView from './components/WishlistView';
import CategoryPanel from './components/CategoryPanel';
import SocialProofPopup from './components/SocialProofPopup';
import LandingScreen from './components/LandingScreen';
import AdminPanel from './components/AdminPanel';
import SupplierDashboard from './components/SupplierDashboard';
import CheckoutView from './components/CheckoutView';
import AdminLogin from './components/AdminLogin';
import SupplierLogin from './components/SupplierLogin';
import RoleSelection from './components/RoleSelection';
import TrendIntelligence from './components/TrendIntelligence';
import ContactPanel from './components/ContactPanel';
import GameShowroom from './components/GameShowroom';
import PayForMe from './components/PayForMe';
import { EXTENDED_PRODUCTS, MOCK_BUNDLES } from './mockData';
import { USER_ACHIEVEMENTS } from './data/extendedMock';
import { databaseService } from './services/databaseService';
import { Product, CartItem, Page, ViewState, UserStats, Bundle, Category, Achievement, Notification, PromoCode } from './types';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(() => {
    return localStorage.getItem('closet-kraze-auth') === 'true';
  });

  const [currentView, setCurrentView] = useState<ViewState>(ViewState.LOBBY);
  const [activeSupplierId, setActiveSupplierId] = useState<string | null>(null);
  const [showAuthModal, setShowAuthModal] = useState(false);

  const [cart, setCart] = useState<CartItem[]>(() => {
    const saved = localStorage.getItem('closet-kraze-cart');
    return saved ? JSON.parse(saved) : [];
  });
  const [wishlist, setWishlist] = useState<string[]>(() => {
    const saved = localStorage.getItem('closet-kraze-wishlist');
    return saved ? JSON.parse(saved) : [];
  });
  const [achievements, setAchievements] = useState<Achievement[]>(() => {
    const saved = localStorage.getItem('closet-kraze-achievements');
    return saved ? JSON.parse(saved) : USER_ACHIEVEMENTS;
  });
  const [notifications, setNotifications] = useState<Notification[]>([]);

  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isNotificationOpen, setIsNotificationOpen] = useState(false);
  const [isCategoryPanelOpen, setIsCategoryPanelOpen] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [selectedCategory, setSelectedCategory] = useState<Category>('All');
  const [timeLeft, setTimeLeft] = useState(300);

  // Applied Promo Code state
  const [activePromo, setActivePromo] = useState<PromoCode | null>(null);

  // Velocity Surge State (5-minute timer for extra 10% discount)
  const [surgeTimerEnd, setSurgeTimerEnd] = useState<number | null>(() => {
    const saved = localStorage.getItem('cc-surge-timer');
    return saved ? Number(saved) : null;
  });

  const [stats, setStats] = useState<UserStats>(() => {
    const saved = localStorage.getItem('closet-kraze-stats');
    return saved ? JSON.parse(saved) : {
      dailyGameAttempts: 3,
      lastGameReset: new Date().toDateString(),
      quests: [
        { id: 'q1', title: 'Analyze Velocity Heat', rewardXP: 100, icon: '🔥', completed: false },
        { id: 'q2', title: 'Refine Identity', rewardXP: 150, icon: '🎨', completed: false }
      ],
      selectedPath: 'CYBER'
    };
  });

  const balances = {
    coins: 4250,
    gems: 120,
    xp: achievements.reduce((acc, ach) => acc + (ach.unlocked ? ach.rewardXP || 0 : 0), 0) + 8500
  };

  useEffect(() => {
    localStorage.setItem('closet-kraze-auth', isAuthenticated.toString());
  }, [isAuthenticated]);

  useEffect(() => {
    localStorage.setItem('closet-kraze-cart', JSON.stringify(cart));
    // Reset surge timer if cart is emptied
    if (cart.length === 0) {
      setSurgeTimerEnd(null);
      localStorage.removeItem('cc-surge-timer');
    }
  }, [cart]);

  useEffect(() => {
    if (surgeTimerEnd) {
      localStorage.setItem('cc-surge-timer', surgeTimerEnd.toString());
    }
  }, [surgeTimerEnd]);

  useEffect(() => {
    // Poll for new signals
    const interval = setInterval(() => {
      setNotifications(databaseService.getGlobalNotifications());
    }, 5000);
    setNotifications(databaseService.getGlobalNotifications());
    return () => clearInterval(interval);
  }, []);

  const requireAuth = (action: () => void) => {
    if (!isAuthenticated) {
      setShowAuthModal(true);
    } else {
      action();
    }
  };

  const addToCart = (product: Product, selectedSize?: string) => {
    requireAuth(() => {
      // Start 5-minute surge if not already active
      if (!surgeTimerEnd || Date.now() > surgeTimerEnd) {
        const newEnd = Date.now() + (300 * 1000);
        setSurgeTimerEnd(newEnd);
      }

      setCart(prev => {
        const existing = prev.find(item => item.id === product.id && item.selectedSize === selectedSize);
        if (existing) return prev.map(i => (i.id === product.id && i.selectedSize === selectedSize) ? { ...i, quantity: i.quantity + 1 } : i);
        return [...prev, { ...product, quantity: 1, selectedSize }];
      });
      setIsCartOpen(true);
    });
  };

  const toggleWishlist = (product: Product) => {
    requireAuth(() => {
      setWishlist(prev => 
        prev.includes(product.id) 
          ? prev.filter(id => id !== product.id) 
          : [...prev, product.id]
      );
    });
  };

  const handleMarkRead = (id: string) => {
    const updated = notifications.map(n => n.id === id ? { ...n, read: true } : n);
    setNotifications(updated);
    databaseService.updateNotifications(updated);
  };

  const handleMarkAllRead = () => {
    const updated = notifications.map(n => ({ ...n, read: true }));
    setNotifications(updated);
    databaseService.updateNotifications(updated);
  };

  const handleNavigateView = (view: ViewState) => {
    const protectedViews = [ViewState.PROFILE, ViewState.WISHLIST, ViewState.CHECKOUT, ViewState.GAME_SHOWROOM];
    if (protectedViews.includes(view)) {
      requireAuth(() => setCurrentView(view));
    } else {
      setCurrentView(view);
    }
  };

  const handleAdminSuccess = (role: 'ADMIN' | 'SUPPLIER', id?: string) => {
    setShowAuthModal(false);
    if (role === 'ADMIN') {
      setCurrentView(ViewState.ADMIN);
    } else {
      setActiveSupplierId(id || 'sup1');
      setCurrentView(ViewState.SUPPLIER_DASHBOARD);
    }
  };

  const handleLoginComplete = (archetype: string) => {
    setStats(prev => ({...prev, selectedPath: archetype}));
    setIsAuthenticated(true);
    setShowAuthModal(false);
  };

  const handleClearCart = () => {
    setCart([]);
    setSurgeTimerEnd(null);
    localStorage.removeItem('cc-surge-timer');
  };

  const renderView = () => {
    switch (currentView) {
      case ViewState.LOBBY:
        return (
          <Lobby 
            products={EXTENDED_PRODUCTS} 
            stats={stats} 
            wishlist={wishlist}
            onNavigate={handleNavigateView} 
            onAddToCart={(pId) => {
              const p = EXTENDED_PRODUCTS.find(x => x.id === pId);
              if (p) addToCart(p, p.sizes?.[0]);
            }} 
            onToggleWishlist={toggleWishlist}
            onProductClick={setSelectedProduct}
            onCompleteQuest={(qId) => {
              setStats(prev => ({
                ...prev,
                quests: prev.quests.map(q => q.id === qId ? { ...q, completed: true } : q)
              }));
            }}
          />
        );
      case ViewState.FAMOUS:
        return (
          <FamousProducts 
            products={selectedCategory === 'All' ? EXTENDED_PRODUCTS : EXTENDED_PRODUCTS.filter(p => p.category === selectedCategory)} 
            wishlist={wishlist}
            onProductClick={setSelectedProduct} 
            onAddToCart={(p) => addToCart(p, p.sizes?.[0])}
            onToggleWishlist={toggleWishlist}
          />
        );
      case ViewState.TRY_ON: return <TryOn />;
      case ViewState.BUNDLES: return <Bundles bundles={MOCK_BUNDLES} onAddBundle={(b) => b.products.forEach(p => addToCart(p, p.sizes?.[0]))} />;
      case ViewState.CATEGORIES: return <Categories onSelectCategory={setSelectedCategory} onNavigate={handleNavigateView} />;
      case ViewState.FLASH: return <FlashSales onAddToCart={(p) => addToCart(p, p.sizes?.[0])} />;
      case ViewState.PROFILE: return <Profile stats={stats} onNavigate={handleNavigateView} onLogout={() => setIsAuthenticated(false)} onApplyPromo={setActivePromo} activePromo={activePromo} />;
      case ViewState.WISHLIST: return <WishlistView products={EXTENDED_PRODUCTS} wishlistIds={wishlist} onAddToCart={(p) => addToCart(p, p.sizes?.[0])} onToggleWishlist={toggleWishlist} onProductClick={setSelectedProduct} onNavigate={handleNavigateView} />;
      case ViewState.TRENDS: return <TrendIntelligence stats={stats} />;
      case ViewState.CONTACT: return <ContactPanel />;
      case ViewState.GAME_SHOWROOM: return <GameShowroom attemptsRemaining={stats.dailyGameAttempts} onPlay={() => setStats(s => ({...s, dailyGameAttempts: s.dailyGameAttempts - 1}))} onWin={(r) => alert(`Reward Unlocked: ${r}`)} />;
      case ViewState.PAY_FOR_ME: return <PayForMe />;
      case ViewState.ROLE_SELECTION: return <RoleSelection onSelect={(role) => setCurrentView(role === 'ADMIN' ? ViewState.ADMIN_LOGIN : ViewState.SUPPLIER_LOGIN)} onCancel={() => setCurrentView(ViewState.LOBBY)} />;
      case ViewState.ADMIN_LOGIN: return <AdminLogin onSuccess={handleAdminSuccess} onCancel={() => setCurrentView(ViewState.ROLE_SELECTION)} />;
      case ViewState.SUPPLIER_LOGIN: return <SupplierLogin onSuccess={(id) => handleAdminSuccess('SUPPLIER', id)} onCancel={() => setCurrentView(ViewState.ROLE_SELECTION)} />;
      case ViewState.ADMIN: return <AdminPanel onExit={() => setCurrentView(ViewState.LOBBY)} onNavigate={handleNavigateView} />;
      case ViewState.SUPPLIER_DASHBOARD: return <SupplierDashboard supplierId={activeSupplierId || 'sup1'} onLogout={() => setCurrentView(ViewState.LOBBY)} />;
      case ViewState.CHECKOUT: return <CheckoutView items={cart} onComplete={() => handleClearCart()} onCancel={() => setCurrentView(ViewState.LOBBY)} balances={balances} activePromo={activePromo} />;
      default: return <Lobby products={EXTENDED_PRODUCTS} stats={stats} wishlist={wishlist} onNavigate={handleNavigateView} onAddToCart={() => {}} onToggleWishlist={() => {}} onProductClick={setSelectedProduct} onCompleteQuest={() => {}} />;
    }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-[#FAFAFA] flex flex-col font-sans">
      <Header 
        cartCount={cart.reduce((a, b) => a + b.quantity, 0)} 
        wishlistCount={wishlist.length}
        notificationCount={notifications.filter(n => !n.read).length}
        stats={stats}
        onCartOpen={() => setIsCartOpen(true)}
        onNotificationOpen={() => setIsNotificationOpen(true)}
        onNavigatePage={(p) => handleNavigateView(p === Page.HOME ? ViewState.LOBBY : ViewState.FAMOUS)}
        onNavigateView={handleNavigateView}
        currentPage={currentView === ViewState.LOBBY ? Page.HOME : Page.SHOP}
        currentView={currentView}
        dropTime={timeLeft}
        onOpenCategories={() => setIsCategoryPanelOpen(true)}
      />
      <main className="pt-24 flex-1">{renderView()}</main>
      <BottomNav currentView={currentView} onNavigate={handleNavigateView} onOpenCategories={() => setIsCategoryPanelOpen(true)} />

      <CartDrawer 
        isOpen={isCartOpen} 
        onClose={() => setIsCartOpen(false)} 
        items={cart} 
        onRemove={(id) => setCart(prev => prev.filter(i => i.id !== id))} 
        onUpdateQuantity={(id, d) => setCart(prev => prev.map(i => i.id === id ? {...i, quantity: Math.max(1, i.quantity + d)} : i))} 
        onClear={handleClearCart}
        onNavigate={handleNavigateView}
        surgeTimerEnd={surgeTimerEnd}
        activePromo={activePromo}
      />

      <NotificationCenter 
        isOpen={isNotificationOpen} 
        onClose={() => setIsNotificationOpen(false)} 
        notifications={notifications} 
        onMarkRead={handleMarkRead}
        onMarkAllRead={handleMarkAllRead}
      />

      <CategoryPanel isOpen={isCategoryPanelOpen} onClose={() => setIsCategoryPanelOpen(false)} onSelectCategory={setSelectedCategory} onNavigate={handleNavigateView} activeCategory={selectedCategory} products={EXTENDED_PRODUCTS} onProductSelect={setSelectedProduct} />
      <SocialProofPopup />
      {selectedProduct && (
        <ProductDetail 
          product={selectedProduct} 
          stats={stats} 
          allProducts={EXTENDED_PRODUCTS}
          onClose={() => setSelectedProduct(null)} 
          onAddToCart={addToCart} 
          onUpdateSynergy={() => {}} 
          onToggleWishlist={toggleWishlist} 
          onProductClick={setSelectedProduct}
          isInWishlist={wishlist.includes(selectedProduct.id)} 
        />
      )}

      {/* Authentication Modal Overlay */}
      {showAuthModal && (
        <LandingScreen 
          onComplete={handleLoginComplete} 
          onAdminAccess={() => {
            setShowAuthModal(false);
            setCurrentView(ViewState.ROLE_SELECTION);
          }}
          onClose={() => setShowAuthModal(false)}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { CartItem, ViewState, PromoCode } from '../types';

interface CartDrawerProps {
  isOpen: boolean;
  onClose: () => void;
  items: CartItem[];
  onRemove: (id: string) => void;
  onUpdateQuantity: (id: string, delta: number) => void;
  onClear: () => void;
  onNavigate?: (view: ViewState) => void;
  surgeTimerEnd: number | null;
  activePromo?: PromoCode | null;
}

const CartDrawer: React.FC<CartDrawerProps> = ({ 
  isOpen, 
  onClose, 
  items, 
  onRemove, 
  onUpdateQuantity, 
  onClear, 
  onNavigate,
  surgeTimerEnd,
  activePromo
}) => {
  const subtotal = items.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const totalOriginal = items.reduce((acc, item) => acc + (item.originalPrice * item.quantity), 0);

  // Velocity Surge Logic
  const [surgeTimeRemaining, setSurgeTimeRemaining] = useState<number>(0);
  const isSurgeActive = surgeTimeRemaining > 0;

  // Apply Surge Discount
  let calculatedValuation = isSurgeActive ? subtotal * 0.9 : subtotal;

  // Apply Promo Fragment
  if (activePromo) {
    if (activePromo.type === 'PERCENT') {
      calculatedValuation = calculatedValuation * (1 - activePromo.value / 100);
    } else {
      calculatedValuation = Math.max(0, calculatedValuation - activePromo.value);
    }
  }

  const finalValuation = Math.floor(calculatedValuation);
  const efficiency = totalOriginal > 0 ? Math.round(((totalOriginal - finalValuation) / totalOriginal) * 100) : 0;

  // Loss Aversion: De-materialization Counter
  const [expiry, setExpiry] = useState(600); // 10 minutes
  const [showClearConfirm, setShowClearConfirm] = useState(false);

  useEffect(() => {
    if (!isOpen || items.length === 0) return;
    const timer = setInterval(() => {
      setExpiry(prev => (prev > 0 ? prev - 1 : 0));

      if (surgeTimerEnd) {
        const remaining = Math.max(0, Math.floor((surgeTimerEnd - Date.now()) / 1000));
        setSurgeTimeRemaining(remaining);
      }
    }, 1000);
    return () => clearInterval(timer);
  }, [isOpen, items, surgeTimerEnd]);

  const min = Math.floor(expiry / 60);
  const sec = expiry % 60;
  const isCritical = expiry < 60;

  const sMin = Math.floor(surgeTimeRemaining / 60);
  const sSec = surgeTimeRemaining % 60;

  const handleStartCheckout = () => {
    onClose();
    if (onNavigate) onNavigate(ViewState.CHECKOUT);
  };

  const handleClearAll = () => {
    onClear();
    setShowClearConfirm(false);
  };

  return (
    <>
      {/* Backdrop */}
      <div 
        className={`fixed inset-0 bg-black/80 backdrop-blur-sm z-[200] transition-opacity duration-700 ${isOpen ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}
        onClick={onClose}
      />

      {/* Terminal Panel */}
      <div className={`fixed top-0 right-0 h-full w-full max-w-xl bg-[#050505] z-[210] shadow-[-30px_0_100px_rgba(0,0,0,0.9)] transition-transform duration-700 ease-[cubic-bezier(0.23,1,0.32,1)] border-l border-white/5 ${isOpen ? 'translate-x-0' : 'translate-x-full'}`}>
        <div className="h-full flex flex-col relative overflow-hidden">

          {/* Background Technical Grid */}
          <div className="absolute inset-0 opacity-[0.02] pointer-events-none" style={{ backgroundImage: 'linear-gradient(#fff 1px, transparent 1px), linear-gradient(90deg, #fff 1px, transparent 1px)', backgroundSize: '40px 40px' }}></div>
          <div className="absolute inset-0 bg-gradient-to-b from-[#EC4899]/5 via-transparent to-transparent pointer-events-none"></div>

          {/* Header Area */}
          <header className="relative z-10 px-8 py-10 md:px-12 flex justify-between items-start border-b border-white/5">
            <div className="space-y-3">
              <div className="flex items-center gap-3">
                <span className={`w-2 h-2 rounded-full ${items.length > 0 ? 'bg-[#EC4899] animate-pulse' : 'bg-zinc-800'}`}></span>
                <span className="text-[10px] font-black text-[#EC4899] uppercase tracking-[0.4em]">Inventory Terminal // V.2.5</span>
              </div>
              <div className="flex items-baseline gap-4">
                <h2 className="text-4xl md:text-5xl font-serif italic text-white tracking-tighter leading-none">Your Haul</h2>
                {items.length > 0 && (
                  <button 
                    onClick={() => setShowClearConfirm(true)}
                    className="text-[8px] font-black text-zinc-600 hover:text-red-500 uppercase tracking-widest transition-colors border-b border-zinc-900 hover:border-red-500/30 pb-0.5"
                  >
                    Clear_Archive
                  </button>
                )}
              </div>
            </div>
            <button 
              onClick={onClose} 
              className="w-12 h-12 rounded-full glass border-white/10 flex items-center justify-center text-white text-xl hover:bg-[#EC4899] hover:border-[#EC4899] transition-all hover:rotate-90"
            >
              ✕
            </button>
          </header>

          {/* Velocity Surge Banner */}
          {isSurgeActive && items.length > 0 && (
            <div className="mx-8 md:mx-12 mt-6 p-4 bg-[#EC4899] rounded-2xl flex items-center justify-between shadow-[0_0_30px_rgba(236,72,153,0.3)] animate-in slide-in-from-top-4 duration-500">
               <div className="flex items-center gap-4">
                  <div className="text-2xl animate-bounce">⚡</div>
                  <div className="flex flex-col">
                    <span className="text-[10px] font-black text-white uppercase tracking-widest">Velocity Surge Active</span>
                    <span className="text-[8px] font-bold text-white/80 uppercase">Extra 10% Decisive Bonus Applied</span>
                  </div>
               </div>
               <div className="text-2xl font-mono font-black text-white">
                 {sMin}:{sSec.toString().padStart(2, '0')}
               </div>
            </div>
          )}

          {/* Promo Code Applied Label */}
          {activePromo && items.length > 0 && (
            <div className="mx-8 md:mx-12 mt-3 px-4 py-2 bg-blue-600/20 border border-blue-500/30 rounded-xl flex items-center justify-between animate-in fade-in duration-300">
               <div className="flex items-center gap-2">
                 <span className="text-[10px] font-black text-blue-400 uppercase tracking-widest">Aura Fragment: {activePromo.code}</span>
               </div>
               <span className="text-[10px] font-mono font-black text-white">-{activePromo.value}{activePromo.type === 'PERCENT' ? '%' : ' GH₵'}</span>
            </div>
          )}

          {/* Loss Aversion Timer */}
          {items.length > 0 && (
            <div className={`relative z-10 mx-8 md:mx-12 mt-4 p-6 rounded-3xl border transition-all duration-500 flex items-center justify-between overflow-hidden ${isCritical ? 'bg-red-950/20 border-red-500/30 shadow-[0_0_30px_rgba(239,68,68,0.2)]' : 'bg-zinc-950 border-white/5'}`}>
               <div className="space-y-1">
                  <div className={`text-[10px] font-black uppercase tracking-widest ${isCritical ? 'text-red-500' : 'text-zinc-500'}`}>
                    {isCritical ? 'Dematerialization Imminent' : 'Signal Stability Window'}
                  </div>
                  <p className="text-[9px] font-bold text-zinc-600 uppercase tracking-tighter">
                    Unconfirmed silhouettes will return to global archives.
                  </p>
               </div>
               <div className={`text-3xl font-mono font-black tracking-tighter ${isCritical ? 'text-red-500 animate-pulse' : 'text-white'}`}>
                  {min}:{sec.toString().padStart(2, '0')}
               </div>

               {/* Animated Progress Bar */}
               <div className="absolute bottom-0 left-0 h-0.5 bg-zinc-800 w-full">
                  <div 
                    className={`h-full transition-all duration-1000 ${isCritical ? 'bg-red-500' : 'bg-[#EC4899]'}`} 
                    style={{ width: `${(expiry / 600) * 100}%` }}
                  ></div>
               </div>
            </div>
          )}

          {/* Content Area */}
          <div className="flex-1 overflow-y-auto px-8 md:px-12 py-10 space-y-12 scrollbar-hide relative z-10">
            {items.length === 0 ? (
              <div className="h-full flex flex-col items-center justify-center text-center py-20 opacity-40">
                <div className="text-9xl mb-10 grayscale brightness-50">🎒</div>
                <div className="space-y-4">
                  <p className="text-zinc-500 uppercase text-[12px] font-black tracking-[0.5em]">The Void Archive is Empty</p>
                  <p className="text-zinc-700 text-[9px] font-bold uppercase tracking-widest max-w-[240px] leading-relaxed mx-auto italic">
                    Initialize acquisition protocol by selecting silhouettes from the main database.
                  </p>
                </div>
                <button 
                  onClick={onClose}
                  className="mt-12 px-12 py-5 bg-white text-black text-[10px] font-black uppercase tracking-[0.3em] rounded-2xl hover:bg-[#EC4899] hover:text-white transition-all shadow-2xl"
                >
                  Return to Circuit
                </button>
              </div>
            ) : (
              items.map((item, idx) => (
                <div 
                  key={`${item.id}-${item.selectedSize}`} 
                  className="group flex flex-col md:flex-row gap-8 animate-in slide-in-from-right-12 duration-500"
                  style={{ animationDelay: `${idx * 100}ms` }}
                >
                  {/* Image with Heat Indicator */}
