                </p>
              </div>
            </footer>
          )}

          {/* Clear Confirmation Modal */}
          {showClearConfirm && (
            <div className="absolute inset-0 z-50 bg-black/95 backdrop-blur-3xl flex items-center justify-center p-8 animate-in fade-in duration-300">
