import React from 'react';
import { Product } from '../types';

interface ProductCardProps {
  product: Product;
  onClick: (product: Product) => void;
  onAddToCart: (product: Product) => void;
  onToggleWishlist: (product: Product) => void;
  isWishlisted: boolean;
}

const ProductCard: React.FC<ProductCardProps> = ({ 
  product, 
  onClick, 
  onAddToCart, 
  onToggleWishlist,
  isWishlisted 
}) => {
  const discountPercent = Math.round(((product.originalPrice - product.price) / product.originalPrice) * 100);

  // Rarity calculation based on Hype Score
  const getRarity = (score: number) => {
    if (score > 90) return { label: 'MYTHIC', color: 'text-purple-400', border: 'border-purple-500/30' };
    if (score > 75) return { label: 'RARE', color: 'text-pink-400', border: 'border-pink-500/30' };
    return { label: 'ARCHIVE', color: 'text-zinc-500', border: 'border-zinc-500/20' };
  };

  const rarity = getRarity(product.hypeScore);
  const demandWidth = Math.min(100, (product.viewers / 200) * 100);

  return (
    <div className="group relative flex flex-col h-full">
      {/* Visual Asset Container */}
      <div 
        className="relative aspect-[4/5] overflow-hidden bg-zinc-950 border border-white/5 cursor-pointer mb-5 rounded-sm"
        onClick={() => onClick(product)}
      >
        {/* Background Technical Noise */}
        <div className="absolute inset-0 opacity-[0.03] pointer-events-none bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')]"></div>

        <img 
          src={product.image} 
          alt={product.name} 
          className="w-full h-full object-cover transition-all duration-[1.5s] group-hover:scale-110 group-hover:opacity-30 group-hover:blur-[2px]"
        />

        {/* Urgent Overlays */}
        {discountPercent > 0 && (
          <div className="absolute top-0 right-0 p-4 z-10">
            <div className="bg-[#EC4899] text-white px-3 py-1 text-[9px] font-black uppercase tracking-widest shadow-[0_0_20px_rgba(236,72,153,0.4)]">
              -{discountPercent}%
            </div>
          </div>
        )}

        <div className="absolute top-0 left-0 p-4 z-10 space-y-2">
          <div className="bg-black/80 backdrop-blur-xl border border-white/10 px-3 py-1 flex items-center gap-2">
            <span className={`text-[8px] font-black uppercase tracking-tighter ${rarity.color}`}>
              {rarity.label}_TIER
            </span>
          </div>
          {product.isNew && (
            <div className="bg-blue-600 text-white px-3 py-1 text-[8px] font-black uppercase tracking-[0.2em] w-fit">
              NEW_SIGNAL
            </div>
          )}
        </div>

        {/* Hover UI: Decision Hub */}
        <div className="absolute inset-0 flex flex-col items-center justify-center translate-y-8 opacity-0 group-hover:translate-y-0 group-hover:opacity-100 transition-all duration-500 bg-black/40 backdrop-blur-sm p-8">
          <div className="text-[10px] font-black uppercase tracking-[0.4em] text-white mb-8 border-b border-white/20 pb-2">
            Asset_Control
          </div>

          <div className="flex w-full gap-2">
            <button 
              onClick={(e) => { e.stopPropagation(); onAddToCart(product); }}
              className="flex-1 py-5 bg-white text-black text-[10px] uppercase tracking-[0.3em] font-black hover:bg-[#EC4899] hover:text-white transition-all shadow-2xl active:scale-95"
            >
              Acquire
            </button>
            <button 
              onClick={(e) => { e.stopPropagation(); onToggleWishlist(product); }}
              className={`w-14 h-14 flex items-center justify-center rounded-sm border transition-all ${
                isWishlisted 
                ? 'bg-[#EC4899] border-[#EC4899] text-white shadow-lg' 
                : 'bg-black/50 border-white/20 text-white hover:bg-white hover:text-black'
              }`}
            >
              {isWishlisted ? '💖' : '🤍'}
            </button>
          </div>
        </div>

        {/* Scarcity Trigger */}
        {product.stockCount <= 5 && product.stockCount > 0 && (
          <div className="absolute bottom-4 left-4 right-4 z-10">
             <div className="w-full bg-red-600/90 backdrop-blur-md text-white py-1.5 px-3 text-[8px] font-black uppercase tracking-widest text-center shadow-lg animate-pulse">
               CRITICAL_STOCK: {product.stockCount} LEFT
             </div>
          </div>
        )}
      </div>

      {/* Product Information Metadata */}
      <div className="flex flex-col gap-3 flex-1" onClick={() => onClick(product)}>
        <div className="flex justify-between items-start gap-4">
          <div className="space-y-1">
            <h3 className="text-sm font-black uppercase tracking-tight text-white group-hover:text-[#EC4899] transition-colors leading-tight">
              {product.name}
            </h3>
            <div className="flex items-center gap-2">
              <span className="text-[7px] font-black text-zinc-600 uppercase tracking-widest">
                Sector_{product.category}
              </span>
            </div>
          </div>
          <div className="text-right flex flex-col">
            <div className="flex items-baseline gap-1 justify-end">
              <span className="text-lg font-black font-mono tracking-tighter text-white">GH₵{product.price}</span>
              <span className="text-[10px] font-black text-blue-400 uppercase tracking-tighter">+ GH₵{product.shippingFee || 0} ship</span>
            </div>
            <span className="text-[9px] font-mono text-zinc-600 line-through opacity-50">GH₵{product.originalPrice}</span>
          </div>
        </div>

        {/* Neural Demand Visualizer */}
        <div className="space-y-1.5 pt-2 border-t border-white/5">
          <div className="flex justify-between items-center text-[7px] font-black uppercase tracking-[0.2em] text-zinc-600">
            <span>Neural Demand Signal</span>
            <span className="text-zinc-400">{demandWidth.toFixed(1)}% Active</span>
          </div>
          <div className="h-[2px] w-full bg-zinc-900 overflow-hidden">
            <div 
              className={`h-full bg-[#EC4899] shadow-[0_0_8px_#EC4899] transition-all duration-[2s] group-hover:bg-white`} 
              style={{ width: `${demandWidth}%` }}
            ></div>
          </div>
        </div>
      </div>
    </div>
  );
};

