import React, { useState, useMemo, useRef } from 'react';
import { Product, UserStats } from '../types';

interface ProductDetailProps {
  product: Product;
  stats: UserStats;
  allProducts: Product[];
  onClose: () => void;
  onAddToCart: (product: Product, selectedSize?: string) => void;
  onUpdateSynergy: (synergy: string) => void;
  onToggleWishlist: (product: Product) => void;
  onProductClick: (product: Product) => void;
  isInWishlist: boolean;
}

const ProductDetail: React.FC<ProductDetailProps> = ({ 
  product, 
  stats,
  allProducts,
  onClose, 
  onAddToCart, 
  onToggleWishlist,
  onProductClick,
  isInWishlist
}) => {
  const [selectedSize, setSelectedSize] = useState<string>(product.sizes?.[0] || '');
  const [isMaterializing, setIsMaterializing] = useState(false);
  const [tryOnResult, setTryOnResult] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const activeViewers = Math.floor(product.viewers / 4) + 12;

  // Pairing Logic: Suggest items from different categories to complete the look
  const pairingSuggestions = useMemo(() => {
    return allProducts
      .filter(p => p.id !== product.id && p.category !== product.category)
      .sort((a, b) => b.hypeScore - a.hypeScore)
      .slice(0, 6);
  }, [product.id, product.category, allProducts]);

  const handleProductSwap = (newProduct: Product) => {
    onProductClick(newProduct);
    setTryOnResult(null);
    const detailContainer = document.getElementById('product-detail-container');
    if (detailContainer) {
      detailContainer.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setIsMaterializing(true);
      setTryOnResult(null);
      setTimeout(() => {
        const reader = new FileReader();
        reader.onload = (event) => {
          setTryOnResult(event.target?.result as string);
          setIsMaterializing(false);
        };
        reader.readAsDataURL(file);
      }, 2500);
    }
  };

  const handleShare = async () => {
    const shareMessage = `Silhouette: ${product.name}\nIntel: ${product.description}\nSource: www.closetkraze.com\n\nBuy now!`;

    if (navigator.share) {
      try {
        await navigator.share({
          title: `Closet Kraze | ${product.name}`,
          text: shareMessage,
          url: 'https://www.closetkraze.com',
        });
      } catch (err) {
        console.error('Transmission aborted');
      }
    } else {
      navigator.clipboard.writeText(`${shareMessage} https://www.closetkraze.com`);
      alert('Transmission protocol copied to clipboard.');
    }
  };

  return (
    <div id="product-detail-container" className="fixed inset-0 z-[150] bg-black flex flex-col md:flex-row animate-in fade-in duration-700 overflow-y-auto md:overflow-hidden font-sans text-white">

      {/* Visual Immersive Zone */}
      <div className="w-full md:w-3/5 h-[70vh] md:h-full relative bg-zinc-950 overflow-hidden shrink-0">
        {isMaterializing ? (
